entries[190186] = { ["name"] = "Holzstatuette", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Ruft mit dem Beschwörungskreis einen Inkubus herbei. (3 Min Abklingzeit)\n\"In den Sockel ist etwas graviert: Ich bin wieder zu Hause.\"" }
entries[190187] = { ["name"] = "Abgetragener Schal", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Ruft mit dem Beschwörungskreis einen Inkubus herbei. (3 Min Abklingzeit)\n\"Der Stoff ist mit feinen Mustern bestickt, sowie den Buchstaben 'M+K'.\"" }
entries[190232] = { ["name"] = "Abgetragener Schal", ["text"] = "Questgegenstand\nEinzigartig\n\"Der Stoff ist mit feinen Mustern bestickt, sowie den Buchstaben 'M+K'.\"" }
entries[190307] = { ["name"] = "Nicht angezündete Fackel", ["text"] = "Herbeigezauberter Gegenstand\nQuestgegenstand\nEinzigartig\n\"Wisst Ihr, was diese Fackel gebrauchen könnte? Eine Flamme.\"" }
entries[190308] = { ["name"] = "Brennende Fackel", ["text"] = "Herbeigezauberter Gegenstand\nQuestgegenstand\nEinzigartig\nDauer: 5 min\nBenutzen: Wirft eine Fackel auf die Zielposition und entzündet ein Feuer.\n\"Nützlich, um für feurige Ablenkung zu sorgen!\"" }
entries[190309] = { ["name"] = "Holzstatuette", ["text"] = "Questgegenstand\nEinzigartig\n\"In den Sockel ist etwas graviert: Ich bin wieder zu Hause.\"" }
entries[191204] = { ["name"] = "Geringer Todesstein", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Macht aus 100 geringen Todessteinen einen großen Todesstein." }
entries[191249] = { ["name"] = "Großer Todesstein", ["text"] = "Wird beim Aufheben gebunden\n\"Ein grüner Stein, in dem unbekannte Energie leuchtet.\"" }
entries[191267] = { ["name"] = "Rune der Teleportation: Vorkammer", ["text"] = "Wird beim Aufheben gebunden\nDauer: 7 tagen\nBenutzen: Teleportiert Euch in die Vorkammer in Naxxramas." }
entries[191268] = { ["name"] = "Kugel der Verderbnis", ["text"] = "Wird beim Aufheben gebunden\nDauer: 7 tagen\nBenutzen: Zerschmettert die Kugel und erhöht so die von Kel'Thuzads Dienern absorbierte Menge geringer Todessteine 30 Min. lang um 50%." }
entries[191272] = { ["name"] = "Rute der Totenbeschwörung", ["text"] = "Wird beim Aufheben gebunden\nDauer: 7 tagen\nBenutzen: Unterwirft den Willen eines untoten Ziels in Naxxramas, sodass es 5 Min. lang bezaubert wird.\n3 Aufladungen" }
entries[191280] = { ["name"] = "Pilzsporenansammlung", ["text"] = "Wird beim Aufheben gebunden\nDauer: 7 tagen\nBenutzen: Gewährt Euren offensiven Fähigkeiten eine Chance, eine Spore zu beschwören, die Spielercharaktere in der Nähe mit 'Pilzwucher' belegt, wenn sie getötet wird. Dieser Effekt hält 1 Stunde lang an.\n\nPilzwucher\nVerursacht alle 1 Sek. 150 Naturschaden und erhöht die Chance auf einen kritischen Treffer mit Nahkampf-, Distanzangriffen und Zaubern um 15%. (Procchance: 10%, 15s Abklingzeit)" }
entries[191288] = { ["name"] = "Rune der Teleportation: Hort des Frostwyrms", ["text"] = "Wird beim Aufheben gebunden\nDauer: 7 tagen\nBenutzen: Teleportiert Euch zum Hort des Frostwyrms in Naxxramas." }
entries[191292] = { ["name"] = "Ritualdolch", ["text"] = "Wird beim Aufheben gebunden\nDauer: 7 tagen\nBenutzen: Absorbiert die Lebenskraft derer in Eurer Umgebung und erhöht so die Ausdauer pro getroffenem Ziel um 3. Dieser Effekt ist bis zu 40-mal stapelbar und hält 1 Stunde lang an." }
entries[191312] = { ["name"] = "Vorsorgephylakterium", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 7 tagenSchmuck\nBenötigt Stufe 60\nAnlegen: Verhindert einen Angriff, der Euch ansonsten töten würde. Wenn dieser Effekt ausgelöst wird, werdet Ihr 3 Sek. lang immun gegen Schaden und das Phylakterium wird zerstört." }
entries[191313] = { ["name"] = "Maske des Todes", ["text"] = "Dauer: 7 tagen\nBenutzen: Nehmt das Antlitz eines Bewohners von Naxxramas an." }
entries[191414] = { ["name"] = "Skelettartefakt", ["text"] = "Wird beim Aufheben gebunden\nDauer: 7 tagen\nBenutzen: Fängt die Seele des toten Ziels ein und gewährt Euch so einen vorteilhaften Effekt. Dieser Effekt hält 1 Stunde lang an." }
entries[191458] = { ["name"] = "Zerschmettertes Phylakterium", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 7 tagenSchmuck\nBenötigt Stufe 60\n\"Glanz- und nutzlos.\"" }
entries[191459] = { ["name"] = "Rune des Glücks", ["text"] = "Wird beim Aufheben gebunden\nDauer: 7 tagen\nBenutzen: Ermächtigt Kel'Thuzad und seinen Untergebenen mit nekromantischer Energie, was ihnen erhöhte Gesundheit und erhöhten Schaden gewährt. Ermächtigte Gegner bedeuten zusätzliche Belohnungen, wenn sie besiegt werden.\n\nDieser Effekt ist stapelbar und hält eine ganze Woche lang an." }
entries[191477] = { ["name"] = "Skelettanbindepfosten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 7 tagen\nBenötigt Stufe 60\nBenutzen: Beschwört einen Skelettanbindepfosten.\n\nGruppenmitglieder können den Pfosten verwenden, um ein Skelettross zu erhalten." }
entries[191480] = { ["name"] = "Skelettross", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde\nReittier\nBenötigt Stufe 40\nBenutzen: Beschwört ein Skelettross oder gibt es wieder frei. Dieses Ross gehorcht dem Beschwörenden und kann als Reittier in Naxxramas genutzt werden. Feindliche Aktionen gegenüber dem Reiter lassen das Ross furchterfüllt fliehen. (3 Sek. Abklingzeit)" }
entries[191481] = { ["name"] = "Wappenrock der Meisterschaft", ["text"] = "Wird beim Aufheben gebunden\nWappenrock\n\"Ein Beweis für wahre Meisterschaft.\"" }
entries[191550] = { ["name"] = "Buch der Todessteine: Maske des Todes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n\"Ein Foliant über die Kunst, Todessteine in eine Maske des Todes umzuwandeln.\"" }
