entries[191656] = { ["name"] = "Essenz des Todes", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[191660] = { ["name"] = "Thaddius' Blitzbolzen", ["text"] = "Wird beim Aufheben gebunden\nDauer: 7 tagen\nBenutzen: Bringt die Bolzen an Eurem Hals an, sodass sie zufällig eine positive oder negative Ladung anwenden, die Schaden und Heilung um 1% erhöht.\n\nDieser Effekt wird gestapelt, wenn sich Verbündete mit einer ähnlichen Ladung in der Nähe befinden, und fügt Verbündeten mit einer entgegengesetzten Ladung Naturschaden zu." }
entries[191661] = { ["name"] = "Monströser Spinnenfangzahn", ["text"] = "Wird beim Aufheben gebunden\nDauer: 7 tagen\nBenutzen: Stecht Euch mit dem Fangzahn, was die Bewegungsgeschwindigkeit, das Angriffstempo und das Zaubertempo 1 Stunde lang um 15% erhöht. (Procchance: 5%, 30s Abklingzeit)" }
entries[191664] = { ["name"] = "Buch der Todessteine: Thaddius' Blitzbolzen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n\"Ein Foliant über die Kunst, Todessteine in Thaddius' Blitzbolzen umzuwandeln.\"" }
entries[191666] = { ["name"] = "Buch der Todessteine: Monströser Spinnenfangzahn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60\n\"Ein Foliant über die Kunst, Todessteine in einen monströsen Spinnenfangzahn umzuwandeln.\"" }
entries[202251] = { ["name"] = "Tüte mit Leckerlis", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Öffnet den Leckerlibeutel und steckt ihn in die Tasche Eures Ziels. Dadurch wird der Schaden, den Wildtiere diesem Ziel zufügen, um 20 erhöht. (1 Min Abklingzeit)" }
entries[202254] = { ["name"] = "Armschienen der Umlenkung", ["text"] = "Wird beim Anlegen gebunden\nHandgelenke Leder\n44 Rüstung\n+11 Ausdauer\n+13 Intelligenz\n+8 Willenskraft\nHaltbarkeit 35 / 35\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Chance, einen kritischen Treffer durch Zauber zu erzielen, um 1%." }
entries[202256] = { ["name"] = "Verzierte Pistole des Freibeuters", ["text"] = "Wird beim Aufheben gebunden\nDistanz Schusswaffe\n6 - 13 Schaden Tempo 1.90\n(5.00 Schaden pro Sekunde)\nHaltbarkeit 35 / 35\nKlassen: Schurke\nAnlegen: Erhaltet die Fähigkeit 'Pistolenheld':\n\nZieht Eure Fernkampfwaffe und feuert einen Schnellschuss auf einen Gegner ab, der normalen Distanzwaffenschaden verursacht und die Bewegungsgeschwindigkeit des Ziels 6 Sek. lang um 50% verringert. Gewährt 1 Combopunkt.\n\n'Pistolenheld' profitiert von allen Talenten und Effekten, die durch 'Finsterer Stoß' ausgelöst werden oder 'Finsterer Stoß' modifizieren." }
entries[202641] = { ["name"] = "Schlammbedecktes Notizbuch.", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\nKlassen: Schurke\n\"Dieses Buch ist voller Schlamm, aber auf jeder Seite finden sich Runen und eine kurze Notiz in einer Art Geheimsprache.\"" }
entries[203723] = { ["name"] = "Schnittis Notiz", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schurke\n\"Eine in Diebesschrift verfasste Nachricht.\"\n<Zum Lesen rechtsklicken>" }
entries[203726] = { ["name"] = "Schnittis Rune", ["text"] = "Klassen: Schurke" }
entries[203745] = { ["name"] = "Zaubernotizen: Eislanze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenötigt Runenschnitzen\n(1)\nPrägt Eure Handschuhe mit der Rune 'Eislanze':\n\nFügt dem gegnerischen Ziel [Quellwert] bis [Quellwert] Frostschaden zu. Fügt eingefrorenen Zielen 400% Schaden zu.\n\nWenn Eure anderen Frostzauber einem Ziel, das nicht von einem Spielercharakter kontrolliert wird, Schaden zufügen, erhöhen sie den Schaden, den das Ziel durch Euren nächsten Einsatz von 'Eislanze' erleidet, um 20%. Dieser Effekt ist bis zu 5-mal stapelbar und benötigt das Talent 'Winterkälte'.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[203746] = { ["name"] = "Zaubernotizen: Lebende Flamme", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenötigt Runenschnitzen\n(1)\nPrägt Eure Hosen mit der Rune 'Lebende Flamme':\n\nBeschwört eine Zauberfeuerflamme, die sich auf das Ziel zubewegt und einen Pfad aus Zauberfeuer hinterlässt. Dieser Pfad fügt Gegnern in der Nähe pro Sekunde [Quellwert] Zauberfeuerschaden zu. Hält 10 Sek. lang an.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[203747] = { ["name"] = "Zaubernotizen: Eisige Finger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenötigt Runenschnitzen\n(1)\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Eisige Finger':\n\nVerleiht Euren Kälteeffekten eine Chance von 25%, den Effekt 'Eisige Finger' hervorzurufen. Die eisigen Finger bewirken, dass Eure nächsten 2 gewirkten Zauber einen Effekt haben, den sie auf ein gefrorenes Ziel hätten. Hält 15 Sek. lang an.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[203748] = { ["name"] = "Zaubernotizen: Feuerfontäne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Euer Brustteil mit der Rune 'Feuerfontäne':\n\nErhöht die kritische Trefferchance aller Eurer Zauber um 15%, aber die kritischen Treffer Eurer Zauber ohne regelmäßige Effekte kosten zusätzlich 1% eures Grundmanas.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[203749] = { ["name"] = "Zaubernotizen: Erleuchtung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Erleuchtung':\n\nIhr verursacht 10% mehr Schaden, solange Ihr mehr als 70% Mana habt. Während Ihr weniger als 30% Mana habt, beträgt Eure Manaregeneration während des Zauberwirkens 10%.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[203750] = { ["name"] = "Schatzkarte von Elwynn", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schurke\nBenutzen: Gräbt einen Schatz an dem markierten Ort aus. (1 Min Abklingzeit)\n\"Westlich von Kammwacht. In der Nähe des Stumpfs hinter dem Streunerbau.\"" }
entries[203751] = { ["name"] = "Zaubernotizen: NSZEIELA", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenutzen: Entziffert die Zaubernotizen mit einer Verständnisfibel, um einen neuen Runenschnitzenzauber zu erlernen." }
entries[203752] = { ["name"] = "Zaubernotizen: DEELFANE LMEBM", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenutzen: Entschlüsselt die Zaubernotizen mit einem Verständnisamulett, um einen neuen Runenschnitzenzauber zu erlernen." }
entries[203753] = { ["name"] = "Zaubernotizen: ENEGSG IERIFI", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenutzen: Entschlüsselt die Zaubernotizen mit einem Verständnisamulett, um einen neuen Runenschnitzenzauber zu erlernen." }
entries[203754] = { ["name"] = "Erzmagier Antonidas: Die ungekürzte Autobiografie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Etwas ausschweifend, aber dennoch eine schöne Erweiterung für die Sammlung jeder Bücherei.\"" }
entries[203755] = { ["name"] = "Forschungsaufzeichnungen von Erzmagier Theocritus", ["text"] = "Einzigartig\n\"Forschungsnotizen aus dem Turm von Azora. Eine tolle Ergänzung für die Sammlung einer jeden Bibliothek.\"" }
entries[203756] = { ["name"] = "Notizen eines Lehrlings aus Azora: Seite 1", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kombiniert 6 Notizen eines Lehrlings aus Azora, um eine neue Runenschnitzenvorlage zu erschaffen." }
entries[203784] = { ["name"] = "Rechtes oberes Kartenteil", ["text"] = "Benutzen: Kombiniert ein Stück mit 3 anderen, um die vollständige Karte zu erhalten.\n\"Ein abgerissenes Stück von etwas, das wie eine Karte aussieht...\"" }
entries[203785] = { ["name"] = "Linkes oberes Kartenteil", ["text"] = "Benutzen: Kombiniert ein Stück mit 3 anderen, um die vollständige Karte zu erhalten.\n\"Ein abgerissenes Stück von etwas, das wie eine Karte aussieht...\"" }
entries[203786] = { ["name"] = "Rechtes unteres Kartenteil", ["text"] = "Benutzen: Kombiniert ein Stück mit 3 anderen, um die vollständige Karte zu erhalten.\n\"Ein abgerissenes Stück von etwas, das wie eine Karte aussieht...\"" }
entries[203787] = { ["name"] = "Linkes unteres Kartenteil", ["text"] = "Benutzen: Kombiniert ein Stück mit 3 anderen, um die vollständige Karte zu erhalten.\n\"Ein abgerissenes Stück von etwas, das wie eine Karte aussieht...\"" }
entries[203960] = { ["name"] = "Notizen eines Lehrlings aus Azora: Seite 2", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kombiniert 6 Notizen eines Lehrlings aus Azora, um eine neue Runenschnitzenvorlage zu erschaffen." }
entries[203961] = { ["name"] = "Notizen eines Lehrlings aus Azora: Seite 3", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kombiniert 6 Notizen eines Lehrlings aus Azora, um eine neue Runenschnitzenvorlage zu erschaffen." }
entries[203962] = { ["name"] = "Notizen eines Lehrlings aus Azora: Seite 4", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kombiniert 6 Notizen eines Lehrlings aus Azora, um eine neue Runenschnitzenvorlage zu erschaffen." }
entries[203990] = { ["name"] = "Rune der Verstümmelung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Eure Handschuhe mit der Rune 'Verstümmeln':\n\nGreift sofort mit beiden Waffen an, verursacht 95% Waffenschaden sowie mit jeder Waffe zusätzlich [Quellwert] Schaden. Der Schaden gegen vergiftete Ziele ist um 20% erhöht. Gewährt 2 Combopunkte.\n\nSofern nicht anders angegeben, profitiert 'Verstümmeln' von allen Talenten und Effekten, die durch 'Meucheln' ausgelöst werden oder 'Meucheln' modifizieren.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[203991] = { ["name"] = "Rune des Pistolenhelden", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Pistolenheld':\n\nZieht Eure Fernkampfwaffe und feuert einen Schnellschuss auf einen Gegner ab, der normalen Distanzwaffenschaden verursacht und die Bewegungsgeschwindigkeit des Ziels 6 Sek. lang um 50% verringert. Gewährt 1 Combopunkt.\n\n'Pistolenheld' profitiert von allen Talenten und Effekten, die durch 'Finsterer Stoß' ausgelöst werden oder 'Finsterer Stoß' modifizieren.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[203992] = { ["name"] = "Rune der Täuschung", ["text"] = "Klassen: Schurke\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[203993] = { ["name"] = "Rune des Abschlachtens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Hinterhältiger Mord':\n\nVerringert die Energiekosten Eurer Fähigkeiten 'Meucheln' und 'Hinterhalt' um 30 und erhöht den Schaden, den sie Zielen zufügen, die nicht von Spielercharakteren kontrolliert werden, um 70%. [ Handschuhe prägen - Verstümmeln : Gilt nicht für 'Verstümmeln' / Gilt nicht für Fähigkeiten, die durch andere Runen erlernt wurden.]\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[203994] = { ["name"] = "Rune der tödlichen Mischung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Tödliche Mischung':\n\nGewährt Euren Giften mehrere Verbesserungen:\n\nWenn Ihr das Ziel mit irgendeinem anderen Gift vergiftet, belegt Ihr es auch mit tödlichem Gift.\n\nWenn Eure Waffe mit keinem Gift überzogen ist, besteht eine Chance, dass sie sofort wirkendes Gift anwendet, als wäre sie mit sofort wirkendem Gift überzogen.\n\nDer Schaden des tödlichen Gifts und des sofort wirkenden Gifts wird nun durch Eure Angriffskraft erhöht.\n\nEuer 'Tödliches Gift' kann jetzt gegen Ziele wirken, die bereits vom 'Tödlichen Gift' eines anderen Schurken betroffen sind.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[204174] = { ["name"] = "Rune der Präzision", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Eure Hosen mit der Rune 'Zwischen die Augen':\n\nFinishing-Move für den Distanzkampf, der durch Angriffskraft erhöhten Schaden pro Combopunkt verursacht und das Ziel betäubt:\n\n1 Punkt: [Quellwert] bis [Quellwert] Schaden, 1 Sek. Betäubung\n2 Punkte: [Quellwert] bis [Quellwert] Schaden, 2 Sek. Betäubung\n3 Punkte: [Quellwert] bis [Quellwert] Schaden, 3 Sek. Betäubung\n4 Punkte: [Quellwert] bis [Quellwert] Schaden, 4 Sek. Betäubung\n5 Punkte: [Quellwert] bis [Quellwert] Schaden, 5 Sek. Betäubung\n\nTeilt sich die Abklingzeit mit 'Nierenhieb'.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[204270] = { ["name"] = "Tiefenkern", ["text"] = "Einzigartig" }
entries[204441] = { ["name"] = "Rune der Blutraserei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Euer Brustteil mit der Rune 'Blutraserei':\n\n'Verwunden' kann jetzt in der Berserker-Stellung eingesetzt werden. Der Schaden von 'Verwunden' wird um 100% erhöht, und 'Verwunden' verursacht jedes Mal, wenn es Schaden verursacht, zusätzlichen Schaden in Höhe von 4% Eurer Angriffskraft.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[204476] = { ["name"] = "Abgetrennter Koboldkopf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine grausige Trophäe. Könnte für den richtigen Sammler interessant sein...\"" }
entries[204477] = { ["name"] = "Abgetrennter Murlockopf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine grausige Trophäe. Könnte für den richtigen Sammler interessant sein...\"" }
entries[204478] = { ["name"] = "Abgetrennter Gnollkopf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine grausige Trophäe. Könnte für den richtigen Sammler interessant sein...\"" }
entries[204688] = { ["name"] = "Erstes Runenbruchstück des Monsterjägers", ["text"] = "Benutzen: Mit 2 anderen Stücken kombinieren, um die vollständige Rune zu erhalten." }
entries[204689] = { ["name"] = "Zweites Runenbruchstück des Monsterjägers", ["text"] = "Benutzen: Mit 2 anderen Stücken kombinieren, um die vollständige Rune zu erhalten." }
entries[204690] = { ["name"] = "Drittes Runenbruchstück des Monsterjägers", ["text"] = "Benutzen: Mit 2 anderen Stücken kombinieren, um die vollständige Rune zu erhalten." }
entries[204703] = { ["name"] = "Rune der Verwüstung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Eure Handschuhe mit der Rune 'Verwüsten':\n\nWährend Ihr Euch in der 'Verteidigungshaltung' befindet und einen Schild tragt, verursacht 'Rüstung zerreißen' zusätzlich pro Sekunde Schaden in Höhe von 150% des Schadens Eurer ausgerüsteten Waffe. Dieser Effekt ist pro Stapel von 'Rüstung zerreißen', der bereits auf dem Ziel ist, um 15% erhöht. Schaden von 'Verwüsten' erzeugt ein hohes Maß an Bedrohung, während Ihr Euch in der 'Verteidigungshaltung' befindet.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[204716] = { ["name"] = "Rune des rasenden Angriffs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Eure Hosen mit der Rune 'Rasender Angriff':\n\nWährend Ihr Zweihandwaffen tragt, ist Euer Angriffstempo um 40% erhöht und Eure erfolgreichen Nahkampfangriffe erzeugen 2 zusätzliche Wut oder 4 zusätzliche Wut, wenn sie kritische Treffer sind.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[204795] = { ["name"] = "Rune des Schattenschlags", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Eure Handschuhe mit der Rune 'Schattenschlag':\n\nTeleportiert Euch hinter Euer Ziel und schlägt zu, um ihm 150% Waffenschaden zuzufügen. Muss im Verstohlenheitsmodus sein. Gewährt 1 Combopunkt.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[204804] = { ["name"] = "Hydraxianische Reifen", ["text"] = "Wird beim Aufheben gebunden\nHandgelenke Kette\n95 Rüstung\n+4 Stärke\n+7 Ausdauer\nHaltbarkeit 40 / 40\nBenötigt Stufe 25" }
entries[204806] = { ["name"] = "Rune des Siegesrauschs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Eure Handschuhe mit der Rune 'Siegesrausch':\n\nGreift das Ziel sofort an. Verursacht (1 + Angriffskraft * 45 / 100) Schaden und heilt Euch um 30% Eurer maximalen Gesundheit. Kann nur innerhalb von 20 Sek., nachdem Ihr einen Gegner getötet habt, der Erfahrung oder Ehre gewährt, eingesetzt werden.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[204807] = { ["name"] = "Tiefenklinge", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Schwert\n71 - 107 Schaden Tempo 3.60\n(24.72 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\nBenötigt Stufe 25\nTrefferchance: Trifft alle Gegner vor Euch mit einem Schwall Druckwasser.\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n\"Das Geräusch brechender Wellen erklingt mit jedem Schwung.\"" }
entries[204809] = { ["name"] = "Rune des wütenden Donners", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Eure Hosen mit der Rune 'Wütender Donner':\n\n'Donnerknall' erhöht nun die Zeit zwischen Angriffen um zusätzliche 6%, kann in jeder Haltung eingesetzt werden, verursacht 100% mehr Schaden und erzeugt 75% mehr Bedrohung.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[204864] = { ["name"] = "Notizen eines Lehrlings aus Azora", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (6)\nBenutzen: Kombiniert 6 Notizen eines Lehrlings aus Azora, um eine neue Runenschnitzenvorlage zu erschaffen." }
entries[204905] = { ["name"] = "Ominöser Foliant", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Soboz beschwören\n\"Bringt den Kiefer eines Wolfs und das Blut eines Gnolls zum Bauch des Lamms. Beginnt dann die Anrufung.\"" }
entries[204906] = { ["name"] = "Gnollblut", ["text"] = "Einzigartig\n\"Ein in einem Beschwörungsritual eingesetztes Reagenz.\"" }
entries[204907] = { ["name"] = "Wolfskieferknochen", ["text"] = "Einzigartig\n\"Ein in einem Beschwörungsritual eingesetztes Reagenz.\"" }
entries[204912] = { ["name"] = "Rune der Anmut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Eure Hosen mit der Rune 'Dämonische Anmut':\n\nEin Anstieg der Teufelsenergie erhöht Eure Ausweichchance und die Eures Begleiters um 20% und Eure Chance, mit allen Angriffen kritisch zu treffen, um 20%. Hält 6 Sek. lang an.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[205019] = { ["name"] = "Besudelter Seelensplitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[205020] = { ["name"] = "Reiner Seelensplitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[205022] = { ["name"] = "Rune des Seelenentzugs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Euren Umhang mit der Rune 'Seelenentzug':\n\n'Blutsauger' verursacht 3-mal schneller Schaden. Erhöht die durch Eure Zauber 'Blutsauger' und 'Seelendieb' abgezogene Menge um zusätzliche 6% für jeden Eurer Hexenmeister-Schatteneffekte, von dem das Ziel betroffen ist, bis zu einem zusätzlichen Effekt von maximal 18%. Wenn 'Seelendieb' gegen ein Ziel mit weniger als 20% Gesundheit eingesetzt wird, wird die abgezogene Menge um 50% pro Effekt erhöht, bis maximal 150%. Zusätzlich kann 'Seelendieb' das Talent 'Einbruch der Nacht' auslösen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[205181] = { ["name"] = "Nicht identifiziertes Artefakt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Irgendein esoterisches magisches Objekt. Ein erfahrenerer Hexenmeister könnte Euch vermutlich mehr dazu sagen.\"" }
entries[205182] = { ["name"] = "Machtloses Artefakt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Opfert Euer Blut, um das Artefakt zu ermächtigen." }
entries[205183] = { ["name"] = "Teufelsverstärktes Artefakt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[205184] = { ["name"] = "Notiz eines Akolythen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n<Zum Lesen rechtsklicken>" }
entries[205215] = { ["name"] = "Rune der Taktiken", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Dämonische Taktiken':\n\nErhöht die Chance für einen kritischen Nahkampf- oder Zaubertreffer von Euch und Eurem Dämon um 10%.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[205218] = { ["name"] = "Buchband der Entdeckung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Buchband\nKlassen: Paladin\nBenötigt Stufe 5\nPrägt Euren Umhang mit der Rune 'Seelenentzug':\n\n'Blutsauger' verursacht 3-mal schneller Schaden. Erhöht die durch Eure Zauber 'Blutsauger' und 'Seelendieb' abgezogene Menge um zusätzliche 6% für jeden Eurer Hexenmeister-Schatteneffekte, von dem das Ziel betroffen ist, bis zu einem zusätzlichen Effekt von maximal 18%. Wenn 'Seelendieb' gegen ein Ziel mit weniger als 20% Gesundheit eingesetzt wird, wird die abgezogene Menge um 50% pro Effekt erhöht, bis maximal 150%. Zusätzlich kann 'Seelendieb' das Talent 'Einbruch der Nacht' auslösen.\n\"Erreicht einen Zustand der Inspiration, indem Ihr fünf Gegner tötet, dann benutzt dies, um eine neue Fähigkeit zu erlernen.\"" }
entries[205228] = { ["name"] = "Rune des Chaosblitzes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Eure Handschuhe mit der Rune 'Chaosblitz':\n\nSchleudert einen Blitz chaotischen Feuers auf den Gegner und fügt ihm [Quellwert] bis [Quellwert] Chaosschaden zu. 'Chaosblitz' trifft immer, dem Zauber kann nicht widerstanden werden und sein Wissen sorgt dafür, dass alle Eure Feuerzauber Absorptionseffekte durchschlagen. Es besteht eine hohe Chance, dass dem 'Chaosblitz' widerstanden wird, wenn er gegen Monster eingesetzt wird, die mehr als 3 Stufen über Euch sind.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[205230] = { ["name"] = "Rune der Heimsuchung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Eure Handschuhe mit der Rune 'Heimsuchung':\n\nJagt eine geisterhafte Seele auf den Gegner, die [Quellwert] bis [Quellwert] Schaden verursacht und sämtlichen regelmäßigen Schattenschaden, den Ihr dem Ziel zufügt, 15 Sek. lang um 40% erhöht. Wenn 'Heimsuchung' endet oder gebannt wird, werdet Ihr in Höhe des Schadens geheilt, die der Zauber dem Ziel zugefügt hat.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[205364] = { ["name"] = "Knappsack des Akolythen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n<Zum Öffnen rechtsklicken>" }
entries[205420] = { ["name"] = "Buchband des Richturteils", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Buchband\nKlassen: Paladin\nPrägt Eure Handschuhe mit der Rune 'Kreuzfahrerstoß':\n\nEin sofortiger Stoß, der 75% Waffenschaden als Heiligschaden verursacht und 5% Eures maximalen Manas regeneriert. Die Dauer aller Richturteilseffekte auf dem Ziel wird auf 30 Sek. zurückgesetzt.\n\"Erlernt eine neue Fähigkeit, nachdem Ihr 10 Siegel auf Eure Gegner entfesselt habt.\"" }
entries[205683] = { ["name"] = "Rune der Zurechtweisung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Eure Hosen mit der Rune 'Zurechtweisung':\n\nUnterbricht das Wirken von Zaubern und verhindert 3 Sek. lang, dass Zauber dieser Art gewirkt werden können.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[205685] = { ["name"] = "Rune der Aegis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Euer Brustteil mit der Rune 'Aegis':\n\nErhöht Euren Blockwert um 30% und modifiziert Euer Talent 'Verschanzen'. 'Verschanzen' hat nun eine Chance von 10%, von jedem Nahkampf- oder Distanzangriff gegen Euch ausgelöst zu werden, und wird immer ausgelöst, wenn Ihr einen kritischen Nahkampftreffer erzielt. Zusätzlich erhält Euer 'Abrechnung'-Talent eine Chance von 2% pro Talentpunkt, durch Nah- oder Fernkampfangriffe gegen Euch ausgelöst zu werden.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[205863] = { ["name"] = "Verderbter Buchband", ["text"] = "Klassen: Paladin" }
entries[205864] = { ["name"] = "Verkohlte Notiz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n<Zum Lesen rechtsklicken>" }
entries[205897] = { ["name"] = "Rune des göttlichen Lichts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Euren Umhang mit der Rune 'Göttliches Licht':\n\nHeilt ein verbündetes Ziel um [Quellwert] bis [Quellwert] Gesundheit. 50% der überschüssigen Heilung auf dem Ziel werden zu einem Absorptionsschild umgewandelt, der 15 Sek. lang anhält. Mehrere Einsätze von 'Göttliches Licht' steigern den Wert des Schilds nicht.\n\n'Göttliches Licht' profitiert von allen Talenten und Effekten, die von 'Heiliges Licht' ausgelöst werden oder es modifizieren.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[205905] = { ["name"] = "Erinnerung an einen ergebenen Champion", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Okkultismus':\n\n'Gedankenschinden' und 'Gedankenschlag' verursachen 50% mehr Schaden, wenn das Ziel von Eurem 'Schattenwort: Schmerz' betroffen ist.\nBenutzen: Konzentriert Euch auf die Erinnerung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über die spirituellen Geheimnisse Azeroths geklärten Geist." }
entries[205932] = { ["name"] = "Prophezeiung des Tods eines Königs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Eure Handschuhe mit der Rune 'Schattenwort: Tod':\n\nEin Wort der bindenden Dunkelheit, das dem Ziel [Quellwert] bis [Quellwert] Schattenschaden zufügt. Wenn das Ziel durch 'Schattenwort: Tod' nicht stirbt, erleidet der Zaubernde Schaden in Höhe von 50% des Schadens, der dem Ziel zugefügt werden sollte.\nBenutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist.", ["unresolvedValues"] = true }
entries[205940] = { ["name"] = "Erinnerung an einen dunklen Zweck", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nGraviert Eure Stiefel mit der Rune 'Pest der Leere':\n\nInfiziert das Ziel mit einer Krankheit zu, die im Verlauf von 18 Sek. [Quellwert] Schattenschaden verursacht.\nBenutzen: Konzentriert Euch auf die Erinnerung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über die spirituellen Geheimnisse Azeroths geklärten Geist.", ["unresolvedValues"] = true }
entries[205942] = { ["name"] = "Chimärische Offenbarung", ["text"] = "Prägt Eure Hosen mit der Rune 'Gebet der Besserung':\n\nBelegt das Ziel mit einem Zauber, der es um [Quellwert] Gesundheit heilt, wenn es das nächste Mal Schaden erleidet oder geheilt wird. Wird die Heilung ausgelöst, springt 'Gebet der Besserung' zu einem Gruppen- oder Schlachtzugsmitglied innerhalb von 20 Metern über. Springt bis zu 5-mal und hält nach jedem Sprung 30 Sek. lang an. Dieser Zauber kann nur auf einem Ziel gleichzeitig platziert werden.", ["unresolvedValues"] = true }
entries[205943] = { ["name"] = "Prophezeiung einer entweihten Zitadelle", ["text"] = "Einzigartig\nPrägt Eure Hosen mit der Rune 'Homunculi':\n\nBricht Splitter aus Eurer Seele, um 3 Miniaturkopien von Euch zum Leben zu erwecken, die versuchen, Euer aktuelles Ziel mit einem Streitkolben, Schwert und einer Axt anzugreifen. Dadurch verringern sie das Angriffstempo, die Angriffskraft bzw. die Rüstung aller getroffenen Ziele.\nBenutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist." }
entries[205944] = { ["name"] = "Gegenseitige Offenbarung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Eure Hosen mit der Rune 'Gebet der Besserung':\n\nBelegt das Ziel mit einem Zauber, der es um [Quellwert] Gesundheit heilt, wenn es das nächste Mal Schaden erleidet oder geheilt wird. Wird die Heilung ausgelöst, springt 'Gebet der Besserung' zu einem Gruppen- oder Schlachtzugsmitglied innerhalb von 20 Metern über. Springt bis zu 5-mal und hält nach jedem Sprung 30 Sek. lang an. Dieser Zauber kann nur auf einem Ziel gleichzeitig platziert werden.\n\"Erlernt eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[205945] = { ["name"] = "Erinnerung an einen eingekerkerten Retter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Eure Hosen mit der Rune 'Geteilter Schmerz':\n\nEuer 'Schattenwort: Schmerz' wirkt jetzt zusätzlich auf bis zu 2 zusätzliche Ziele im Umkreis von 15 Metern.\nBenutzen: Konzentriert Euch auf die Erinnerung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über die spirituellen Geheimnisse Azeroths geklärten Geist." }
entries[205946] = { ["name"] = "Erinnerung an den Verrat eines Anführers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Eure Stiefel mit der Rune 'Schmerzunterdrückung':\n\nVerringert sofort sämtlichen Schaden, den ein verbündetes Ziel erleidet, um 40% und erhöht den Widerstand gegen Bannzauber 8 Sek. lang um 65%.\nBenutzen: Konzentriert Euch auf die Erinnerung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über die spirituellen Geheimnisse Azeroths geklärten Geist." }
entries[205947] = { ["name"] = "Prophezeiung einer entweihten Zitadelle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Eure Hosen mit der Rune 'Homunculi':\n\nBricht Splitter aus Eurer Seele, um 3 Miniaturkopien von Euch zum Leben zu erwecken, die versuchen, Euer aktuelles Ziel mit einem Streitkolben, Schwert und einer Axt anzugreifen. Dadurch verringern sie das Angriffstempo, die Angriffskraft bzw. die Rüstung aller getroffenen Ziele.\nBenutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist." }
entries[205948] = { ["name"] = "Wohltuende Offenbarung", ["text"] = "Prägt Euren Umhang mit der Rune 'Vampirberührung':\n\nBelegt Euer Ziel mit Eurer 'Vampirumarmung'. Fügt dem Ziel im Verlauf von 15 Sek. [Quellwert] Schattenschaden zu und gewährt allen Gruppenmitgliedern Mana in Höhe von 2% des Schattenzauberschadens, den Ihr dem Ziel zufügt.", ["unresolvedValues"] = true }
entries[205949] = { ["name"] = "Vielfache Offenbarung", ["text"] = "Klassen: Priester\nPrägt Eure Handschuhe mit der Rune 'Kreis der Heilung':\n\nHeilt alle Gruppenmitglieder des anvisierten Spielercharakters innerhalb von 43.5 Metern um ihn herum um [Quellwert] bis [Quellwert] Gesundheit.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[205950] = { ["name"] = "Finstere Offenbarung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Eure Handschuhe mit der Rune 'Gedankenbrand':\n\nLöst eine Explosion von Schattenmagie aus, die dem Ziel und Gegnern innerhalb von 10 Metern um das Ziel herum 6 Sek. lang alle 1 Sek. [Quellwert] bis [Quellwert] Schattenschaden zufügt.\n\"Erlernt eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[205951] = { ["name"] = "Erinnerung an einen besorgten Akolythen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Eure Handschuhe mit der Rune 'Sühne':\n\nSchleudert eine Salve heiligen Lichts auf das Ziel, die einem Gegner [Quellwert] Heiligschaden zufügt oder ein verbündetes Ziel sofort sowie 2 Sek. lang alle 1 Sek. um [Quellwert] Gesundheit heilt.\nBenutzen: Konzentriert Euch auf die Erinnerung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über die spirituellen Geheimnisse Azeroths geklärten Geist.", ["unresolvedValues"] = true }
entries[205952] = { ["name"] = "Erinnerung an eine zerschmetterte Welt", ["text"] = "Benutzen: Konzentriert Euch auf die Erinnerung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über die spirituellen Geheimnisse Azeroths geklärten Geist." }
entries[205953] = { ["name"] = "Prophezeiung eines gebrochenen Schwurs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Euren Gürtel mit der Rune 'Gedankenstachel':\n\nFügt dem Ziel [Quellwert] bis [Quellwert] Schattenfrostschaden zu und erhöht die kritische Trefferchance Eures nächsten Einsatzes von 'Gedankenschlag' gegen das Ziel um 30%, bis zu 3-mal stapelbar.\nBenutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist.", ["unresolvedValues"] = true }
entries[205961] = { ["name"] = "Vogelfleisch aus Mulgore", ["text"] = "Einzigartig\nBenutzen: Platziert einen Köder in der Nähe eines Bergkatzenbaus." }
entries[205979] = { ["name"] = "Rune des Flankierens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nPrägt Eure Hosen mit der Rune 'Flankenangriff':\n\nIhr und Euer Tier verursacht sofort und gleichzeitig 100% Nahkampfschaden. Anschließend verursacht Ihr 10 Sek. lang 8% mehr Schaden. Bis zu 3-mal stapelbar. Die einfachen Angriffe Eures Tiers haben eine Chance von 50%, die Abklingzeit von 'Flankenangriff' abzuschließen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[205995] = { ["name"] = "Präriehundmoschus", ["text"] = "Klassen: Jäger\nBenutzen: Eure Fähigkeit 'Wildtier zähmen' wirkt auch bei Präriehunden (als Haustier). (10 Min Abklingzeit)" }
entries[206032] = { ["name"] = "Rune des Zerlegens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nPrägt Eure Handschuhe mit der Rune 'Zerlegen':\n\nEin weitreichender Angriff, der allen Gegnern vor Euch mit Euren Nahkampfwaffen 65% Waffenschaden zufügt. Euer Primärziel erleidet 50% mehr Schaden.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[206155] = { ["name"] = "Rune der Treffsicherheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Meister der Treffsicherheit':\n\nErhöht Eure kritische Trefferchance um 5% und verringert die Manakosten aller Eurer Schussfähigkeiten um 25%.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[206157] = { ["name"] = "Zephyriumbergbauladung", ["text"] = "Questgegenstand\nEinzigartig (5)" }
entries[206159] = { ["name"] = "Verkleidung der Venture Co.", ["text"] = "Questgegenstand\n\"Sieht nicht wie eine besonders gute Verkleidung aus...\"" }
entries[206168] = { ["name"] = "Rune der Chimäre", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nPrägt Eure Handschuhe mit der Rune 'Schimärenschuss':\n\nVerursacht 135% Waffenschaden, erneuert die Dauer des auf das Ziel wirkenden Stiches oder Bisses und löst einen Effekt aus:\n\nSchlangenbiss - Verursacht sofort 48% des von Eurem Schlangenbiss verursachten Schadens.\n\nVipernbiss - Stellt sofort 60% des von Eurem Vipernbiss abgezogenen Manas bei Euch wieder her.\n\nSkorpidstich - Versucht, das Ziel 10 Sek. lang zu entwaffnen. Dieser Effekt kann nur einmal pro Minute auftreten.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[206169] = { ["name"] = "Rune des Explosivschusses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nPrägt Eure Handschuhe mit der Rune 'Explosivschuss':\n\nFeuert ein Explosivgeschoss in das gegnerische Ziel, das allen Gegnern innerhalb von 8 Metern [Fernkampfangriffskraft * 0.039 + 62 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] bis [Fernkampfangriffskraft * 0.039 + 94 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] Feuerschaden zufügt. Die Sprengladung verursacht 2 Sek. lang pro Sekunde weiteren Schaden.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[206170] = { ["name"] = "Windzornzapfen", ["text"] = "Questgegenstand" }
entries[206175] = { ["name"] = "Piniensalbe", ["text"] = "Questgegenstand\nEinzigartig" }
entries[206176] = { ["name"] = "Mörser und Stößel", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Zerstampft 8 Windzornzapfen, um eine giftige Waffensalbe herzustellen. Theoretisch." }
entries[206177] = { ["name"] = "Pinienkernbutter", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 18 Sek. 61.2 Punkt(e) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 2 Punkt(e) Ausdauer und Willenskraft." }
entries[206264] = { ["name"] = "Rune der Inspiration", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Eure Hosen mit der Rune 'Inspirationsvorbild':\n\nEure inspirierende Präsenz bannt regelmäßig Furcht- und Schlafeffekte von Gruppenmitgliedern in der Nähe.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[206344] = { ["name"] = "Messersatz", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Versucht, einen rohen glänzenden Kleinfisch zu filetieren." }
entries[206345] = { ["name"] = "Fischstücke", ["text"] = "Questgegenstand\nEinzigartig" }
entries[206376] = { ["name"] = "Bollwerksymbol", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nKlassen: Schamane\nBenötigt Stufe 3\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Schildmeisterschaft':\n\nJedes Mal, wenn Ihr blockt, regeneriert Ihr Mana in Höhe von 8% Eures maximalen Manas und erhaltet Rüstung in der Höhe von 30% des Rüstungswertes Eures Schildes. Bis zu 5-mal stapelbar. Ihr erhaltet außerdem immer eine um 10% erhöhte Blockchance und einen um 15% erhöhten Blockwert.\n\nAußerdem erhaltet Ihr immer, wenn Ihr eine Schockfähigkeit einsetzt, 4 Zauberschaden pro Punkt Eurer Verteidigungsfertigkeit, der über ( 60 * 5) hinausgeht. Hält 15 Sek. lang an.\n\"Erlernt eine neue Fähigkeit, nachdem Ihr Gegner 25-mal mit 'Waffe des Felsbeißers' getroffen habt.\"" }
entries[206381] = { ["name"] = "Dyadisches Symbol", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nKlassen: Schamane\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Überladung':\n\nVerleiht Euren Zaubern 'Blitzschlag', 'Kettenblitzschlag', 'Kettenheilung', 'Welle der Heilung' und 'Lavaeruption' eine Chance von 60%, kostenlos einen zweiten, ähnlichen Zauber auf das gleiche Ziel auszulösen. Dieser verursacht nur halben Schaden bzw. halbe Heilung und erzeugt keine Bedrohung.\n\"Erlernt eine neue Fähigkeit, nachdem Ihr 10-mal Naturschaden erlitten habt.\"" }
entries[206382] = { ["name"] = "Orkansymbol", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nKlassen: Schamane\nPrägt Eure Handschuhe mit der Rune 'Wasserschild':\n\nDer Zaubernde wird von 3 Wasserkugeln umgeben, die alle 5 Sek. 1% Eures maximalen Manas gewähren. Trifft ein Zauber-, Nahkampf- oder Distanzangriff den Zaubernden, werden 4% seines maximalen Manas wiederhergestellt und eine Wasserkugel wird aufgelöst. Alle paar Sekunden kann nur eine Wasserkugel aktiviert werden. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n\"Erlernt eine neue Fähigkeit, nachdem Ihr 10 Gegner, die keine Spielercharaktere sind, mit drei verschiedenen Elementen getroffen habt (Natur, Frost, Feuer).\"" }
entries[206383] = { ["name"] = "Lithisches Symbol", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nKlassen: Schamane\nBenötigt Stufe 3\nPrägt Eure Hosen mit der Rune 'Erdschild':\n\nSchützt das Ziel mit einem Erdschild, der die Erhöhung der Zauberzeit oder Verringerung der Kanalisierungsdauer durch erlittenen Schaden um 30% verringert und Angriffe das geschützte Ziel um [Quellwert] Gesundheit heilen lässt. Dieser Effekt tritt nur einmal alle paar Sekunden auf. 9 Aufladungen. Hält 10 Min. lang an. Der Erdschild kann immer nur auf jeweils einem Ziel aktiv sein.\n\"Erlernt eine neue Fähigkeit, nachdem Ihr 20 Angriffe mit Eurem Schild geblockt habt.\"", ["unresolvedValues"] = true }
entries[206384] = { ["name"] = "Astralsymbol", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nKlassen: Schamane\nBenötigt Stufe 3\n\"Erlernt eine neue Fähigkeit, nachdem Ihr Gegner 25-mal mit 'Waffe des Felsbeißers' getroffen habt.\"" }
entries[206385] = { ["name"] = "Klastisches Symbol", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nKlassen: Schamane\nBenötigt Stufe 3\nPrägt Eure Hosen mit der Rune 'Weg der Erde':\n\nWährend 'Waffe des Felsbeißers' auf Eurer Waffenhand aktiv ist und Ihr einen Schild ausgerüstet habt, erzeugt Ihr 65% mehr Bedrohung, erhaltet 25% mehr Gesundheit, erleidet 10% weniger Schaden. Eure Chance, von Nahkampfangriffen kritisch getroffen zu werden, ist um 6% verringert. Euer 'Erdschock' verspottet Ziele, damit sie Euch angreifen, und hat eine von anderen Schockzaubern getrennte Abklingzeit, aber seine Reichweite wird auf Nahkampfreichweite verringert. Die Reichweite Eurer Zauber 'Blitzschlag', 'Kettenblitzschlag', 'Kettenheilung', 'Welle der Heilung' und 'Lavaeruption' ist jedoch um 20 Meter verringert.\n\"Erlernt eine neue Fähigkeit, nachdem Ihr 20 Gegner mit 'Erdschock' besiegt habt.\"" }
entries[206386] = { ["name"] = "Galvanisches Symbol", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nKlassen: Schamane\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Schildmeisterschaft':\n\nJedes Mal, wenn Ihr blockt, regeneriert Ihr Mana in Höhe von 8% Eures maximalen Manas und erhaltet Rüstung in der Höhe von 30% des Rüstungswertes Eures Schildes. Bis zu 5-mal stapelbar. Ihr erhaltet außerdem immer eine um 10% erhöhte Blockchance und einen um 15% erhöhten Blockwert.\n\nAußerdem erhaltet Ihr immer, wenn Ihr eine Schockfähigkeit einsetzt, 4 Zauberschaden pro Punkt Eurer Verteidigungsfertigkeit, der über ( 60 * 5) hinausgeht. Hält 15 Sek. lang an.\n\"Erlernt eine neue Fähigkeit, nachdem Ihr Gegner 10-mal mit 'Blitzschlag' besiegt habt.\"" }
entries[206387] = { ["name"] = "Kajarisches Symbol", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nKlassen: Schamane\nPrägt Eure Handschuhe mit der Rune 'Lavaeruption':\n\nIhr schleudert flüssige Lava auf das Ziel, die [Quellwert] bis [Quellwert] Feuerschaden verursacht. Wenn das Ziel von 'Flammenschock' betroffen ist, wird 'Lavaeruption' einen kritischen Treffer erzielen.\n\"Lernt eine neue Fähigkeit, nachdem Ihr 5-mal Schaden von Lava erlitten habt. (Verringert den Schaden einiger Lavaquellen)\"", ["unresolvedValues"] = true }
entries[206388] = { ["name"] = "Schwefliges Symbol", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nKlassen: Schamane\nPrägt Eure Handschuhe mit der Rune 'Schmelzschlag':\n\nÜberzieht bis zu 10 Gegner in einem kegelförmigen Bereich vor Euch mit [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 72 / 100 + 5 / 100 * Angriffskraft] bis [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 108 / 100 + 5 / 100 * Angriffskraft] Feuerschaden. Diese Fähigkeit generiert eine große Menge Bedrohung. Der regelmäßige Schaden von 'Flammenschock' hat eine Chance von 10%, die Abklingzeit von 'Schmelzschlag' abzuschließen.\n\"Erlernt eine neue Fähigkeit, nachdem Ihr 10 Gegner mit 'Erdschock' besiegt habt.\"" }
entries[206389] = { ["name"] = "Schwefelsymbol", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nKlassen: Schamane\nBenötigt Stufe 3\nPrägt Euren Gürtel mit der Rune 'Feuernova':\n\nEuer Totem der Feuernova wird durch 'Feuernova' ersetzt. Dadurch verursacht Euer derzeitiges Feuertotem Schaden an seinem Standort.\n\"Erlernt eine neue Fähigkeit, nachdem Ihr Gegner 25-mal mit 'Waffe des Felsbeißers' getroffen habt.\"" }
entries[206390] = { ["name"] = "Ichthyosymbol", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nKlassen: Schamane\nBenötigt Stufe 3\nPrägt Eure Handschuhe mit der Rune 'Wasserschild':\n\nDer Zaubernde wird von 3 Wasserkugeln umgeben, die alle 5 Sek. 1% Eures maximalen Manas gewähren. Trifft ein Zauber-, Nahkampf- oder Distanzangriff den Zaubernden, werden 4% seines maximalen Manas wiederhergestellt und eine Wasserkugel wird aufgelöst. Alle paar Sekunden kann nur eine Wasserkugel aktiviert werden. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n\"Erlernt eine neue Fähigkeit, nachdem Ihr Gegner 25-mal mit 'Waffe des Felsbeißers' getroffen habt.\"" }
entries[206391] = { ["name"] = "Syzygiensymbol", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nKlassen: Schamane\nBenötigt Stufe 3\nPrägt Eure Armschienen mit der Rune 'Springflut':\n\nHeilt ein verbündetes Ziel um [Quellwert] bis [Quellwert] Gesundheit und im Verlauf von 15 Sek. um weitere [Quellwert] Gesundheit. Wenn Ihr innerhalb von 15 Sek. 'Kettenheilung' auf dieses Hauptziel wirkt, wird die hervorgerufene Heilung um 25% erhöht. Dieser Zauber löst außerdem 'Erwachen der Ahnen' aus.\n\"Erlernt eine neue Fähigkeit, nachdem Ihr Gegner 25-mal mit 'Waffe des Felsbeißers' getroffen habt.\"", ["unresolvedValues"] = true }
entries[206466] = { ["name"] = "Präriekrone", ["text"] = "Benutzen: Erweckt einen Geist der Ebenen." }
entries[206469] = { ["name"] = "Prärieblume", ["text"] = "Klassen: Druide\nBenutzen: Verflechtet 3 Prärieblumen zu einer Krone." }
entries[206954] = { ["name"] = "Götze der Bärenwut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Götze\nKlassen: Druide\nPrägt Eure Handschuhe mit der Rune 'Zerfleischen':\n\nZerfleischt das Ziel, fügt ihm 160% des normalen Schadens zu und lässt es 1 Min. lang 30% zusätzlichen Schaden durch Blutungseffekte und 'Schreddern' erleiden. Diese Fähigkeit profitiert von allen Effekten von 'Klaue' und 'Zermalmen' und löst diese aus.\n\nWenn Ihr ein Ziel mit 'Zerfleischen (Bär)' trefft, erhaltet Ihr zudem 4 Angriffskraft für jeden Punkt Eurer Verteidigungsfertigkeit über ( 60 * 5). Hält 15 Sek. lang an.\n\"Erlernt eine neue Fähigkeit, nachdem Ihr Eure Wut in Bärengestalt 60 Sek. lang auf 50 oder höher gehalten habt.\"" }
entries[206963] = { ["name"] = "Rune des Naturpotenzials", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Samenkorn des Lebens':\n\nWenn Ihr mit Euren nicht regelmäßigen Heilzaubern einen kritischen Treffer erzielt, pflanzt Ihr dem Ziel für 50% des geheilten Wertes ein 'Samenkorn des Lebens' ein. Das Samenkorn wird erblühen, wenn das Ziel das nächste Mal Schaden erleidet oder nicht regelmäßige Heilung erhält. Hält 15 Sek. lang an.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[206966] = { ["name"] = "Satyrkrautknolle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Der Setzling einer invasiven Pflanzengattung.\"" }
entries[206970] = { ["name"] = "Rune des Lebens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Eure Hosen mit der Rune 'Blühendes Leben':\n\nVerringert die globale Abklingzeit Eurer Fähigkeiten 'Verjüngung' und 'Blühendes Leben' um 0.5 Sek. und Ihr erhaltet die Fähigkeit 'Blühendes Leben':\n\nHeilt das Ziel im Verlauf von 7 Sek. um [Quellwert] Gesundheit. Wenn 'Blühendes Leben' endet oder gebannt wird, wird das Ziel sofort um [Quellwert] Gesundheit geheilt und der Druide erhält die Hälfte der Zauberkosten erstattet. Dieser Effekt ist bis zu 3-mal auf einem Ziel stapelbar.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[206975] = { ["name"] = "Artefaktlagertruhenschlüssel", ["text"] = "Einzigartig\n\"Öffnet die Artefaktlagertruhe.\"" }
entries[206985] = { ["name"] = "Echo des Alphas", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nBenötigt Stufe 3\nPrägt Eure Stiefel mit der Rune 'Geist des Alphas':\n\nErfüllt das Ziel mit dem Geist eines Alphawolfes, was die generierte Bedrohung des Ziels 30 Min. lang um 45% erhöht. Maximal 1 Ziel. Wenn der Schamane diesen Zauber nicht auf sich selbst wirkt, erhält er 'Treuer Beta', was 30 Min. lang seinen verursachten körperlichen Schaden um 5% erhöht und jegliche erzeugte Bedrohung um 30% verringert. Ein Ziel kann nicht gleichzeitig mit 'Geist des Alphas' und 'Treuer Beta' belegt sein.\n\"Erlernt eine neue Fähigkeit.\"" }
entries[206989] = { ["name"] = "Rune der Sonne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Eure Handschuhe mit der Rune 'Sonnenfeuer':\n\nVerbrennt den Gegner und fügt ihm [Quellwert] bis [Quellwert] Naturschaden sowie im Verlauf von 12 Sek. [Quellwert] zusätzlichen Naturschaden zu.\n\nAußerdem wird, während Ihr in Bärengestalt, Katzengestalt oder Terrorbärengestalt seid, Euer 'Mondfeuer' durch 'Sonnenfeuer (Bär)' oder 'Sonnenfeuer (Katze)' ersetzt. Dieser Zauber profitiert von allen Effekten von 'Mondfeuer' und löst diese aus.\n\n'Sonnenfeuer (Bär)'\nVerbrennt den Gegner und fügt ihm [Quellwert] bis [Quellwert] Naturschaden sowie im Verlauf von 12 Sek. [Quellwert] zusätzlichen Naturschaden zu.\n\n'Sonnenfeuer (Katze)'\nVerbrennt den Gegner und fügt ihm [Quellwert] bis [Quellwert] Naturschaden sowie im Verlauf von 12 Sek. [Quellwert] zusätzlichen Naturschaden zu. Generiert 1 Combopunkt.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[206992] = { ["name"] = "Rune des Schädelstoßes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Eure Handschuhe mit der Rune 'Schädelstoß':\n\nStürmt auf ein Ziel innerhalb von 13 Metern zu und schlagt ihm gegen den Schädel, was das Wirken von Zaubern unterbricht und 2 Sek. lang verhindert, dass Zauber dieser Art gewirkt werden können. Gemeinsame Abklingzeit mit 'Wilde Attacke'.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[206994] = { ["name"] = "Abgetrennter Stacheleberkopf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine grausige Trophäe. Könnte für den richtigen Sammler interessant sein...\"" }
