entries[208085] = { ["name"] = "Signet des Scharlachroten Leutnants", ["text"] = "Einzigartig\nBenutzen: Erstellt gefälschte Dokumente, die den Scharlachroten Kreuzzug gegen die Allianz belasten. Benötigt Schreibutensilien, die im Rathaus von Brill zu finden sind." }
entries[208086] = { ["name"] = "Gefälschtes scharlachrotes Memorandum", ["text"] = "Einzigartig\n\"Eine unfassbare Sammlung von Gedanken menschlicher Extremisten, die die Führung der Allianz sicher aufrütteln wird.\"" }
