entries[208220] = { ["name"] = "Schatzkarte von Dun Morogh", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schurke\nBenutzen: Gräbt einen Schatz an dem markierten Ort aus. (1 Min Abklingzeit)\n\"Unter der Brücke von Kharanos nach Ironforge.\"" }
entries[208222] = { ["name"] = "Vergelter der alten Wache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Axt\n163 - 245 Schaden Tempo 3.90\n(52.31 Schaden pro Sekunde)\n+8 Stärke\n+10 Beweglichkeit\n+41 Ausdauer\nHaltbarkeit 100 / 100\nKlassen: Krieger\nBenötigt Stufe 55\nAnlegen: Wird ein Todesstoß ausgeführt, der Erfahrung oder Ehre gewährt, trifft Euer nächster Angriff kritisch.\n\"Der vorherige Besitzer hat sich sehr sorgfältig um diese Waffe gekümmert.\"" }
entries[208223] = { ["name"] = "Knappsack des Akolythen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n<Zum Öffnen rechtsklicken>" }
entries[208224] = { ["name"] = "Notiz eines Akolythen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n<Zum Lesen rechtsklicken>" }
entries[208414] = { ["name"] = "Mondgötze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Götze\nKlassen: Druide\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Furor von Sturmgrimm':\n\nVerringert die Manakosten von 'Zorn' um 100%. Jedes Mal, wenn Ihr Schaden mit 'Zorn' verursacht, besteht eine Chance von 12%, dass Eure nächste 'Heilende Berührung' innerhalb von 15 Sek. ein Spontanzauber ist und in allen Gestaltwandelgestalten einsetzbar ist. Erlaubt in Baum-des-Lebens-Gestalt 'Zorn' zu zaubern.\n\"Besiegt sechs Kreaturen, die von Eurem Mondfeuer betroffen sind, um eine neue Fähigkeit zu erlernen.\"" }
entries[208425] = { ["name"] = "Glänzende archaische Überreste", ["text"] = "Accountgebunden\nEinzigartig\nHals\n+6 Willenskraft\nBenutzen: Bringt Euch zurück nach Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern. (1 Stunde Abklingzeit)" }
entries[208484] = { ["name"] = "Sonnenlicht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nEinhändig\n10 - 14 Schaden Tempo 1.70\n(7.06 Schaden pro Sekunde)\n+11 Ausdauer\n+34 Willenskraft\n+17 Schattenwiderstand" }
