entries[208607] = { ["name"] = "Rehmoschus", ["text"] = "Klassen: Jäger\nBenutzen: Eure Fähigkeit 'Wildtier zähmen' wirkt auch bei Rehen (als Haustier). (10 Min Abklingzeit)" }
entries[208608] = { ["name"] = "Vogelfleisch von Teldrassil", ["text"] = "Einzigartig\nBenutzen: Platziert einen Köder in der Höhle eines großen Bären." }
entries[208609] = { ["name"] = "Lichtungsblume", ["text"] = "Klassen: Druide\nBenutzen: Verflicht 3 Lichtungsblumen zu einer Krone." }
