entries[208682] = { ["name"] = "Verlassenes Schnappkieferei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n\"Braucht ein neues Zuhause.\"" }
entries[208687] = { ["name"] = "Rune des Aufschlitzens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Eure Hosen mit der Rune 'Aufschlitzen':\n\nSchlitzt ein gegnerisches Ziel auf, was im Verlauf von 15 Sek. [Quellwert] Blutungsschaden und pro existierender Anwendung von 'Aufschlitzen' auf dem Ziel 20% Waffenschaden verursacht. Generiert hohe Bedrohung. Dieser Effekt ist bis zu 5-mal auf demselben Ziel stapelbar.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[208689] = { ["name"] = "Wilder Götze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Götze\nKlassen: Druide\nPrägt Eure Hosen mit der Rune 'Wildes Brüllen':\n\nFinishing-Move, der den verursachten körperlichen Schaden in Katzengestalt um 30% erhöht. Hält pro Combopunkt länger an:\n1 Punkt: 14 Sek.\n2 Punkte: 19 Sek.\n3 Punkte: 24 Sek.\n4 Punkte: 29 Sek.\n5 Punkte: 34 Sek.\n\"Belegt Humanoide 20-mal mit Blutungsschaden und setzt dann diesen Götzen ein, um eine neue Fähigkeit zu erlernen.\"" }
entries[208701] = { ["name"] = "Rune des Meisters der Tiere", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Meister der Tiere':\n\nErhöht Schaden und Gesundheit Eures Tiers um 15% und seine Fokusregeneration um 50%. Außerdem verspottet das 'Knurren' Eures Tiers das Ziel 3 Sek. lang.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[208739] = { ["name"] = "Kriegsbanner der Horde", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n\"Stoßt dies in den Boden Eurer Gegner.\"" }
entries[208741] = { ["name"] = "Rune der endlosen Wut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Euren Helm mit der Rune 'Endlose Wut':\n\nIhr erhaltet 25% mehr Wut durch sämtlichen von Euch verursachten Schaden.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[208743] = { ["name"] = "Seele der Gier", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister" }
entries[208744] = { ["name"] = "Rune der Schattenblitze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Eure Handschuhe mit der Rune 'Schattenblitzsalve':\n\nEuer 'Schattenblitz' trifft jetzt bis zu 5 Ziele in einer Kette innerhalb von 10 Metern, aber mit um 30% verringertem Schaden.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[208749] = { ["name"] = "Kistenschlüssel der Knarzklauen", ["text"] = "Einzigartig\n\"Auf den Griff ist grobschlächtig ein Ast geschnitzt.\"" }
entries[208750] = { ["name"] = "Rune des Kanalisierens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Meisterkanalisierer':\n\nEuer Zauber 'Blutsauger' wird nicht mehr kanalisiert, hält 15 Sek. lang an mit einer Abklingzeit von 15 Sek., kostet 100% mehr Mana und heilt Euch jedes Mal, wenn er Schaden verursacht, um 50% mehr.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[208753] = { ["name"] = "Zaubernotizen: Regeneration", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Regeneration':\n\nHeilt das Ziel im Verlauf von 3 Sek. um [Quellwert] Gesundheit und belegt es für 30 Sek. mit 'Zeitenleuchtfeuer'.\n\nZeitenleuchtfeuer\n\nErfasst die raumzeitliche Position des Subjekts. 70% sämtlichen Arkanschadens, den der Zaubernde verursacht hat, werden für alle aktuellen Ziele von 'Zeitenleuchtfeuer' des Zaubernden in chronomantische Heilung umgewandelt. Diese Heilung ist für den Zaubernden selbst um 50% verringert und wird zudem um 80% verringert, wenn durch arkane Zauber, die mehrere Ziele gleichzeitig treffen, Schaden verursacht wird.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[208754] = { ["name"] = "Zaubernotizen: TENGIRONEERA", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenutzen: Entschlüsselt die Zaubernotizen mit einem Verständnisamulett, um einen neuen Runenschnitzenzauber zu erlernen." }
entries[208758] = { ["name"] = "Irdene Rune", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Eure Hosen mit der Rune 'Weg der Erde':\n\nWährend 'Waffe des Felsbeißers' auf Eurer Waffenhand aktiv ist und Ihr einen Schild ausgerüstet habt, erzeugt Ihr 65% mehr Bedrohung, erhaltet 25% mehr Gesundheit, erleidet 10% weniger Schaden. Eure Chance, von Nahkampfangriffen kritisch getroffen zu werden, ist um 6% verringert. Euer 'Erdschock' verspottet Ziele, damit sie Euch angreifen, und hat eine von anderen Schockzaubern getrennte Abklingzeit, aber seine Reichweite wird auf Nahkampfreichweite verringert. Die Reichweite Eurer Zauber 'Blitzschlag', 'Kettenblitzschlag', 'Kettenheilung', 'Welle der Heilung' und 'Lavaeruption' ist jedoch um 20 Meter verringert.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[208760] = { ["name"] = "Lichtungskrone", ["text"] = "Benutzen: Erweckt einen Geist der Ebenen." }
entries[208764] = { ["name"] = "Rune der Gedanken", ["text"] = "Einzigartig\nKlassen: Priester\nPrägt Euren Gürtel mit der Rune 'Gedankenstachel':\n\nFügt dem Ziel [Quellwert] bis [Quellwert] Schattenfrostschaden zu und erhöht die kritische Trefferchance Eures nächsten Einsatzes von 'Gedankenschlag' gegen das Ziel um 30%, bis zu 3-mal stapelbar.", ["unresolvedValues"] = true }
entries[208765] = { ["name"] = "Helfende Hand", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n\"Die Hand wird sich für einen Retter öffnen.\"" }
entries[208766] = { ["name"] = "Helfende Hand", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n\"Die Hand hat sich für Euch geöffnet.\"\n<Zum Öffnen rechtsklicken>" }
entries[208767] = { ["name"] = "Rune der Besserung", ["text"] = "Einzigartig\nKlassen: Priester\nPrägt Eure Hosen mit der Rune 'Gebet der Besserung':\n\nBelegt das Ziel mit einem Zauber, der es um [Quellwert] Gesundheit heilt, wenn es das nächste Mal Schaden erleidet oder geheilt wird. Wird die Heilung ausgelöst, springt 'Gebet der Besserung' zu einem Gruppen- oder Schlachtzugsmitglied innerhalb von 20 Metern über. Springt bis zu 5-mal und hält nach jedem Sprung 30 Sek. lang an. Dieser Zauber kann nur auf einem Ziel gleichzeitig platziert werden.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[208768] = { ["name"] = "Streichholzkästchen des Bukaniers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n\"Zum Entzünden brennbarer Materialien.\"" }
entries[208771] = { ["name"] = "Rune des Klingentanzes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Eure Hosen mit der Rune 'Klingentanz':\n\nFinishing-Move, der Eure Parierchance um 10% erhöht und Euch 4 Angriffskraft pro Punkt Eurer Verteidigungsfähigkeit über ( 60 * 5) hinaus gewährt. Hält pro Combopunkt länger an:\n\n1 Punkt: 14 Sek.\n2 Punkte: 18 Sek.\n3 Punkte: 22 Sek.\n4 Punkte: 26 Sek.\n5 Punkte: 30 Sek.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[208772] = { ["name"] = "Rune des Säbelschlitzers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Eure Handschuhe mit der Rune 'Säbelschlitzer':\n\nSchlitzt einen Gegner brutal auf, fügt ihm 100% Waffenschaden zu und lässt das Ziel 12 Sek. lang alle 2 Sek. (Angriffskraft * 5 / 100) Blutungsschaden erleiden. Bis zu 3-mal stapelbar. Jeder Stapel erhöht außerdem den durch 'Säbelschlitzer' und 'Finsterer Stoß' verursachten Schaden um 50%. Gewährt 1 Combopunkt.\n\n'Säbelschlitzer' nutzt die Vorteile aller Talente und Effekte, die durch 'Finsterer Stoß' ausgelöst werden oder 'Finsterer Stoß' modifizieren.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[208773] = { ["name"] = "Fischfangharpune", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Krieger , Jäger\nBenutzen: Wirft die Harpune auf das Ziel (40 Meter Reichweite).\n\"Ein Muss für jeden angehenden Haijäger!\"" }
entries[208777] = { ["name"] = "Rune des Scharfschützen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nPrägt Eure Hosen mit der Rune 'Scharfschützentraining':\n\nDie kritische Trefferchance Eurer Schussfähigkeiten ist um 2% erhöht, wenn Ihr Euch in den letzten 2 Sek. nicht bewegt habt. Dieser Effekt stapelt sich pro Sekunde bis auf maximal 5 Stapel. Bei 2 oder mehr Stapeln kann 'Gezielter Schuss' sofort eingesetzt werden. Während Ihr Euch bewegt, verliert Ihr 1 Stapel pro Sekunde.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[208778] = { ["name"] = "Rune des rasanten Schlags", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Eure Handschuhe mit der Rune 'Rasanter Schlag':\n\nEin tollkühner, sofortiger Nahkampfangriff mit Eurer Zweihandwaffe, der (Angriffskraft * 30 / 100) bis (Angriffskraft * 40 / 100) körperlichen Schaden verursacht. Diese Fähigkeit profitiert von allen Effekten von 'Heldenhafter Stoß' und löst diese aus.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[208799] = { ["name"] = "Zaubernotizen: Lebende Bombe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Eure Handschuhe mit der Rune 'Lebende Bombe':\n\nDas Ziel wird zu einer lebenden Bombe und erleidet im Verlauf von 12 Sek. [Quellwert] Feuerschaden. Nach Ablauf von 12 Sek., oder wenn der Zauber gebannt wird, explodiert das Ziel und fügt allen Gegnern innerhalb von 10 Metern [Quellwert] Feuerschaden zu.\n\n'Lebende Bombe' profitiert von allen Talenten und Effekten, die durch 'Versengen' ausgelöst werden oder 'Versengen' verändern.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[208800] = { ["name"] = "Baxtan: Über zerstörerische Magie", ["text"] = "Einzigartig\n\"Die Aufzeichnungen eines namhaften Goblinmagiers. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\"" }
entries[208823] = { ["name"] = "Opfermünze", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Priester\nBenutzen: Wirft die Rune in einen Brunnen in der Nähe werfen, um einen Wunsch zu erhalten." }
entries[208828] = { ["name"] = "Erinnerung an einen gebrochenen Schwur", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Euren Gürtel mit der Rune 'Gedankenstachel':\n\nFügt dem Ziel [Quellwert] bis [Quellwert] Schattenfrostschaden zu und erhöht die kritische Trefferchance Eures nächsten Einsatzes von 'Gedankenschlag' gegen das Ziel um 30%, bis zu 3-mal stapelbar.\nBenutzen: Konzentriert Euch auf die Erinnerung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über die spirituellen Geheimnisse Azeroths geklärten Geist.", ["unresolvedValues"] = true }
entries[208833] = { ["name"] = "Böswilliger Kuchen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n\"Ein Gebäck mit fieser Energie.\"" }
entries[208838] = { ["name"] = "Dunkeleisenschließkassette", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nVerschlossen\nBenötigt Schlossknacken (1)" }
entries[208843] = { ["name"] = "Kampftotem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nBenutzen: Fordert einen Tauren zu einem Duell heraus.\n\"Ein Symbol der Aggression zwischen Mitgliedern der Horde.\"" }
entries[208847] = { ["name"] = "Schädelförmige Geode", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n\"Könnte mit einem ordentlichen Schlag aufgebrochen werden.\"" }
entries[208848] = { ["name"] = "Aufgebrochene schädelförmige Geode", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n\"Die Geode wurde aufgebrochen.\"\n<Zum Öffnen rechtsklicken>" }
entries[208849] = { ["name"] = "Segensbuchband", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Buchband\nKlassen: Paladin\nPrägt Euer Brustteil mit der Rune 'Geheiligter Boden':\n\nEure 'Weihe' heilt Gruppenmitglieder im Effektbereich um 200% des Schadenswerts von 'Weihe'.\n\"Erlernt eine neue Fähigkeit, nachdem Ihr fünf verschiedene Spielercharaktere gesegnet habt.\"" }
entries[208851] = { ["name"] = "Gerechtigkeitsbuchband", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Buchband\nKlassen: Paladin\nPrägt Eure Handschuhe mit der Rune 'Hand der Abrechnung':\n\nVerspottet das Ziel, damit es Euch angreift. Hat keinen Effekt, wenn Ihr von dem Ziel bereits angegriffen werdet.\n\nWährend Ihr diese Fähigkeit kennt, ist der Bedrohungsbonus von 'Zorn der Gerechtigkeit' auf 80% erhöht. Wenn Ihr von anderen Charakteren geheilt werdet, sorgt 'Zorn der Gerechtigkeit' dafür, dass Ihr Mana in Höhe von 25% der hervorgerufenen Heilung erhaltet. Zusätzlich wird Schaden, der Eure Gesundheit unter 35% senkt, um 20% verringert, während 'Zorn der Gerechtigkeit' aktiv ist. 'Zorn der Gerechtigkeit' bleibt aktiv, bis er abgebrochen wird.\n\"Erlernt eine neue Fähigkeit, nachdem Ihr 10 durch 'Hammer der Gerechtigkeit' betäubte Gegner getötet habt.\"" }
entries[208853] = { ["name"] = "Zaubernotizen: Hirnfrost", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenötigt Runenschnitzen\n(1)\nPrägt Eure Stiefel mit der Rune 'Hirnfrost':\n\nEure Frostzauber mit Kälteeffekten haben eine Chance von 20%, Euren nächsten Einsatz von 'Feuerball', 'Zauberfrostblitz', 'Qualfeuerblitz' oder 'Frostfeuerblitz' zu einem Spontanzauber werden zu lassen, der kein Mana kostet.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[208854] = { ["name"] = "Zerkaute Zaubernotizen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenutzen: Entschlüsselt die Zaubernotizen mit einem Verständnisamulett, um einen neuen Runenschnitzenzauber zu erlernen.\n\"Troggschamanen sind wirklich unersättliche Leser.\"" }
entries[208855] = { ["name"] = "Köder aus Regenbogenflossenthunfisch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nBenutzen: Füttert das Ziel mit dem Köder.\n\"Ein schönes Leckerli für Seemonster.\"" }
