entries[209559] = { ["name"] = "Wanderstecken des Zwielichtpropheten", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n51 - 78 Schaden Tempo 2.60\n(24.81 Schaden pro Sekunde)\n+5 Ausdauer\n+10 Willenskraft\nHaltbarkeit 100 / 100\nBenötigt Stufe 25\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 24." }
