entries[209561] = { ["name"] = "Rute des uralten Schlafwandlers", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n37 - 63 Schaden Tempo 2.00\n(25.00 Schaden pro Sekunde)\n+15 Intelligenz\n+14 Willenskraft\n+5 Schattenwiderstand\nHaltbarkeit 120 / 120\nBenötigt Stufe 25\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 26." }
entries[209562] = { ["name"] = "Todbringender Stoß der Hydra", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Schwert\n87 - 132 Schaden Tempo 3.50\n(31.29 Schaden pro Sekunde)\nHaltbarkeit 120 / 120\nBenötigt Stufe 25\nTrefferchance: Besprengt das Ziel mit uraltem Ätzgift, das alle 3 Sek. 20 Naturschaden verursacht und 15 Sek. lang die Rüstung des Ziels um 150 verringert." }
