entries[209570] = { ["name"] = "Foliant der Höhlenlehren", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+6 Ausdauer\nBenötigt Stufe 25\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 7.\n\"Der etwas verblüffende Untertitel lautet: \"Ein strategischer Führer zu den Sternen und zurück.\"\"" }
