entries[209573] = { ["name"] = "Zornige Spitze", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n55 - 84 Schaden Tempo 2.80\n(24.82 Schaden pro Sekunde)\n+11 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Stufe 25\nAnlegen: Erhöht durch Naturzauber und Natureffekte zugefügten Schaden um bis zu 17.\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 26." }
entries[209574] = { ["name"] = "Weggeworfene Grundsätze der Silbernen Hand", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Buchband\nBenötigt Stufe 25\nAnlegen: +15 Angriffskraft, wenn gegen Untote gekämpft wird.\n\"Dieser abgenutzte Foliant weist an den Rändern Brandspuren auf.\"" }
entries[209575] = { ["name"] = "Ikone aus geschnitztem Treibholz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nBenötigt Stufe 25\nAnlegen: Stellt alle 5 Sek. 2 Punkt(e) Mana wieder her." }
entries[209576] = { ["name"] = "Bewusstseinserweiternder Pilz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Götze\nBenötigt Stufe 25\nAnlegen: +5 Willenskraft." }
entries[209577] = { ["name"] = "Faust der Wildnis", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Streitkolben\n44 - 72 Schaden Tempo 2.80\n(20.71 Schaden pro Sekunde)\n60 Rüstung\n+6 Stärke\n+6 Beweglichkeit\n+6 Ausdauer\n+6 Intelligenz\n+6 Willenskraft\nHaltbarkeit 100 / 100\nBenötigt Stufe 25\nAnlegen: +59 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt." }
