entries[210015] = { ["name"] = "Rune des wütenden Schlags", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Euer Brustteil mit der Rune 'Wütender Schlag':\n\nEin wilder Schlag, der 115% Waffenschaden verursacht, jedoch nur eingesetzt werden kann, während 'Wutanfall', 'Berserkerwut' oder 'Blutrausch' aktiv ist. Jede andere Nahkampffähigkeit, die eingesetzt wird, während 'Wutanfall', 'Berserkerwut' oder 'Blutrausch' aktiv ist, verringert die verbleibende Abklingzeit von 'Wütender Schlag' um 1 Sek.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[210026] = { ["name"] = "Symbol der dritten Eule", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n\"Ihr beherrscht das Reich des Meeres.\"" }
entries[210043] = { ["name"] = "Symbol der zweiten Eule", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n\"Agons Seele hat endlich Frieden gefunden.\"" }
