entries[210137] = { ["name"] = "Rune des Wildwuchses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Eure Handschuhe mit der Rune 'Wildwuchs':\n\nHeilt alle Gruppenmitglieder des anvisierten Spielercharakters innerhalb von 43.5 Metern um ihn herum im Verlauf von 7 Sek. um [Quellwert] Gesundheit. Die Heilung wird zunächst schnell und mit zunehmender Dauer von 'Wildwuchs' langsamer angewendet.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
