entries[210147] = { ["name"] = "Automatische Bergungseinheit Schredder", ["text"] = "Benutzen: Birgt das Wrack eines Schredders für Ersatzteile." }
entries[210177] = { ["name"] = "Ataeric: Arkane Merkwürdigkeiten", ["text"] = "Einzigartig\n\"Die Aufzeichnungen eines namhaften Erzmagiers der Kirin Tor. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\"" }
