entries[210183] = { ["name"] = "Horn von Xelthos", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Daraus ertönt ein sanfter und eindringlicher Ton.\"" }
entries[210186] = { ["name"] = "Sprengladung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Öffnet ein schweres Tor auf Goblinweise!" }
