entries[210188] = { ["name"] = "Zerfetzter Arbeitsauftrag", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Anscheinend im Kampf kaputt gegangen.\"" }
entries[210195] = { ["name"] = "Unausgewuchteter Götze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Götze\nKlassen: Druide\nBenötigt Stufe 10\nBenutzen: Gleicht die Mächte des Mondes, des Smaragdgrünen Traums und der Wildnis aus, um eine neue Fähigkeit zu erlernen." }
entries[210209] = { ["name"] = "Zwillingsschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke" }
entries[210210] = { ["name"] = "Gründerzertifikat von Grizzwerks Verteidigungsvertrieb", ["text"] = "\"Das Kleingedruckte macht deutlich, dass mit diesem Zertifikat keinerlei Börsenwert oder Rechtsanspruch verbunden ist. Wenn Ihr Euren Daumen auf diesen Teil legt, könnte es jemand kaufen.\"" }
entries[210212] = { ["name"] = "Bruders Halbschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kombiniert Bruders und Schwesters Halbschlüssel." }
entries[210213] = { ["name"] = "Schwesters Halbschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kombiniert Bruders und Schwesters Halbschlüssel." }
entries[210229] = { ["name"] = "Rune der Verstümmelung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Eure Handschuhe mit der Rune 'Verstümmeln':\n\nGreift sofort mit beiden Waffen an, verursacht 95% Waffenschaden sowie mit jeder Waffe zusätzlich [Quellwert] Schaden. Der Schaden gegen vergiftete Ziele ist um 20% erhöht. Gewährt 2 Combopunkte.\n\nSofern nicht anders angegeben, profitiert 'Verstümmeln' von allen Talenten und Effekten, die durch 'Meucheln' ausgelöst werden oder 'Meucheln' modifizieren.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[210250] = { ["name"] = "Gravierter Goldring", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n\"Die Gravierung lautet: Kniet __ der __ auf __ Friedhof, __ Ihr __ Ringe __\"" }
entries[210251] = { ["name"] = "Gravierter Silberring", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n\"Die Gravierung lautet: __ vor __ Statue __ dem __ während __ beide __ tragt.\"" }
entries[210252] = { ["name"] = "Rune der Klinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Eure Handschuhe mit der Rune 'Halsabschneider':\n\nFür den Einsatz Eurer Fähigkeiten 'Hinterhalt', 'Meucheln' und 'Erdrosseln' müsst Ihr nicht mehr hinter Eurem Gegner sein, und 'Meucheln' hat eine Chance von 15%, dass Ihr bei Eurem nächsten Einsatz von 'Hinterhalt' innerhalb von 10 Sek. nicht in Verstohlenheit sein müsst.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[210253] = { ["name"] = "Verfalltotem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ruft die Geister der Elemente an.\n\"Ein traditionelles Totem... verdreht und krumm durch dunkle Magie, kaum wiederzuerkennen für jene, die Zwiesprache mit den Elementen halten.\"" }
entries[210322] = { ["name"] = "Rune des Toxins", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Eure Hosen mit der Rune 'Vergiften':\n\nFinishing-Move, der sofort Giftschaden abhängig von den Dosen 'Tödliches Gift' auf dem Ziel verursacht. Nach einem Angriff mit 'Vergiften' ist die Frequenz, mit der das Ziel mit 'Sofort wirkendes Gift' belegt werden kann, für 1 Sek. plus je 1 weitere Sekunde pro Combopunkt um 75% erhöht. Pro Combopunkt wird eine Dosis aktiviert:\n1 Dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) + Angriffskraft * 0.072] Schaden\n2 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 2 + Angriffskraft * 0.144] Schaden\n3 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 3 + Angriffskraft * 0.216] Schaden\n4 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 4 + Angriffskraft * 0.288] Schaden\n5 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 5 + Angriffskraft * 0.36] Schaden\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[210323] = { ["name"] = "Tresorkombination", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n\"0-4-5-1\"" }
entries[210329] = { ["name"] = "Hillsbradschatzkarte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n\"Folgt dem Fluss nach Norden, am Alteracgebirge vorbei. Was Ihr sucht, befindet sich unterhalb der Stromschnellen.\"" }
entries[210330] = { ["name"] = "Heißer Tipp", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Gute Informationen sind nicht billig.\"\n<Zum Öffnen rechtsklicken>" }
entries[210410] = { ["name"] = "Süßwasserschnapperköder", ["text"] = "Klassen: Jäger\nBenutzen: Wirft einen Köder. (5 Min Abklingzeit)\n\"Werft ein paar ins Wasser, um einen Großen hervorzulocken!\"" }
entries[210499] = { ["name"] = "Moorcheln", ["text"] = "Benutzen: Essen (auf eigene Gefahr)." }
entries[210500] = { ["name"] = "Rune der Sterne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Eure Hosen mit der Rune 'Sternensog':\n\nEntfesselt eine Sogwelle stellarer Energien, die [Quellwert] bis [Quellwert] Arkanschaden verursacht und 15 Sek. lang für 1 Einsatz den verursachten Schaden von 'Sternenfeuer' um 80% erhöht.\n\n'Sternensog' profitiert von den meisten Talenten und Effekten und löst diese aus, die auch 'Zorn' oder 'Sternenfeuer' auslösen oder davon profitieren.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[210534] = { ["name"] = "Götze der Wildnis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Götze\nKlassen: Druide\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Wilde Stöße':\n\nWährend Ihr in Katzengestalt, Bärengestalt oder Terrorbärengestalt seid, erlangen Gruppen- oder Schlachtzugsmitglieder im Umkreis von 100 Metern erhöhte Kampfwildheit. Bei jedem Nahkampftreffer besteht eine Chance von 20%, dem Angreifer einen Zusatzangriff mit 20% höherer Angriffskraft zu gewähren. Kein Effekt, wenn das Ziel bereits vom Totem des Windzorns profitiert.\n\"Heilt 10 verschiedene Wildtiere und benutzt anschließend diesen Götzen, um eine neue Fähigkeit zu erlernen.\"" }
entries[210568] = { ["name"] = "Schwächelndes Phylakterium", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine abscheuliche Aura dringt aus dem Artefakt.\"" }
entries[210569] = { ["name"] = "Rune der Geißelung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Euer Brustteil mit der Rune 'Geißelung':\n\nIhr erlangt Wut von erlittenem körperlichen Schaden, als ob Ihr keine Rüstung tragen würdet.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[210573] = { ["name"] = "Rune der verzehrenden Wut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Eure Hosen mit der Rune 'Von Wut zerfressen':\n\nVersetzt Euch 12 Sek. lang in einen Wutzustand (und aktiviert Fähigkeiten, die einen Wutzustand erfordern), nachdem Ihr 60 Wut überschritten habt. Außerdem trifft 'Wirbelwind' auch mit Schildhandwaffen, während Ihr Euch in einem Wutzustand befindet.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[210589] = { ["name"] = "Echo der Urahnen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Eure Hosen mit der Rune 'Führung der Ahnen':\n\nFür die nächsten 10 Sek. werden 25% Eures Schadens in Heilung für bis zu 3 Gruppenmitglieder in der Nähe umgewandelt. 100% Eurer Heilung werden in Schaden umgewandelt und dem letzten Ziel von Eurem 'Flammenschock' zugefügt.\n\"Erlernt eine neue Runenschnitzenfähigkeit.\"" }
entries[210596] = { ["name"] = "Rune der Kobrastöße", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Kobrastöße':\n\nEure kritischen Treffer mit Euren Schuss- und Stoßfähigkeiten sowie 'Mungobiss' lassen die nächsten 2 Spezialangriffe Eures Tiers kritisch treffen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[210653] = { ["name"] = "Rune des Parierdolchs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Eure Handschuhe mit der Rune 'Parierdolch':\n\nGreift sofort mit Eurer Schildhandwaffe an und verursacht normalen Schildhandwaffenschaden. Erhöht Eure Parierchance 5 Sek. lang um 100% oder bis Ihr erfolgreich pariert. Nach dem Einsatz von 'Parierdolch' kostet 'Finsterer Stoß' 20 Sek. lang 20 weniger Energie, verursacht 50% mehr Bedrohung, gewährt Stapel von 'Schläge abschwächen', und sowohl 'Finsterer Stoß' als auch 'Ausweiden' verursachen 50% mehr Schaden. Gewährt 1 Combopunkt.\n\n'Parierdolch' nutzt die Vorteile der meisten Talente und Effekte, die durch 'Finsterer Stoß' ausgelöst werden oder 'Finsterer Stoß' modifizieren. Der Effekt von 'Parierdolch' wird 'Parierdolch' selbst nicht verstärken oder günstiger machen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[210654] = { ["name"] = "Zaubernotizen: Zeit zurückdrehen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Eure Armschienen mit der Rune 'Zeit zurückdrehen':\n\nEuer aktuelles mit Eurem 'Zeitenleuchtfeuer' belegtes Ziel wird sofort um sämtlichen Schaden geheilt, den es in den letzten 5 Sek. erlitten hat. Wirkungslos bei Zielen, die vor 5 Sek. nicht mit 'Zeitenleuchtfeuer' belegt waren.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[210655] = { ["name"] = "Zaubernotizen: ZÜDE RHENZUCKITER", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Entschlüsselt die Zaubernotizen mit einem Verständnisamulett, um einen neuen Runenschnitzenzauber zu erlernen." }
entries[210665] = { ["name"] = "Partikel strömender Wut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[210667] = { ["name"] = "Partikel teuflischer Wut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[210668] = { ["name"] = "Partikel seismischer Wut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[210696] = { ["name"] = "Moderbann", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand Schwert\n18 - 34 Schaden Tempo 2.60\n(10.00 Schaden pro Sekunde)\nHaltbarkeit 60 / 60\nKlassen: Krieger\nBenötigt Stufe 14\n\"Blutverkrustet wie sie ist, hat diese Klinge lange ihren Glanz im Licht verloren und dient nun stattdessen als Warnung...\"" }
entries[210708] = { ["name"] = "Elixier der verschmolzenen Reue", ["text"] = "Benötigt Stufe 20\nBenutzen: Ermöglicht es dem Anwender, mit dem Leichnam eines Individuums zu sprechen, das in der Welt der Sterblichen noch unerledigte Angelegenheiten hat. Kann außerdem bei Verdauungsstörungen helfen. (3 Sek. Abklingzeit)" }
entries[210709] = { ["name"] = "Rezept: Elixier der verschmolzenen Reue", ["text"] = "Benötigt Alchimie (90)\nBenutzen: Lehrt euch, wie man ein Elixier der verschmolzenen Reue herstellt.\nElixier der verschmolzenen Reue\nBenötigt Stufe 20\nBenutzen: Ermöglicht es dem Anwender, mit dem Leichnam eines Individuums zu sprechen, das in der Welt der Sterblichen noch unerledigte Angelegenheiten hat. Kann außerdem bei Verdauungsstörungen helfen. (3 Sek. Abklingzeit)\nBenötigt Würgetang (5), Verbleite Phiole , Grabmoos (5), Seelenstaub" }
entries[210712] = { ["name"] = "Elixier der Einsicht", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Vernehmt eine Vision an Je'neus Freudenfeuer." }
entries[210713] = { ["name"] = "Gequälte Seele", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nBenutzen: Reicht eine Opfergabe des Blutes dar, um diese gequälte Seele freizugeben." }
entries[210724] = { ["name"] = "Hirzeks Stab", ["text"] = "Wird beim Aufheben gebunden" }
entries[210741] = { ["name"] = "Automatischer Meuteverprügler", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Streitkolben\n53 - 85 Schaden Tempo 2.00\n(34.50 Schaden pro Sekunde)\n+22 Stärke\n+8 Beweglichkeit\nHaltbarkeit 100 / 100\nKlassen: Paladin , Schamane , Druide\nBenötigt Stufe 40\nAnlegen: +69 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\nBenutzen: Erhöht Euer Angriffstempo 30 Sek. lang um 50%. Keine Wirkung auf Charaktere über Stufe 55. (3 Min Abklingzeit)\n\"Es wurden eine Vielzahl an Verbesserungen vorgenommen, um die Funktionalität des diesjährigen Modells zu verbessern.\"" }
entries[210746] = { ["name"] = "Rune des Erdschilds", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Eure Hosen mit der Rune 'Erdschild':\n\nSchützt das Ziel mit einem Erdschild, der die Erhöhung der Zauberzeit oder Verringerung der Kanalisierungsdauer durch erlittenen Schaden um 30% verringert und Angriffe das geschützte Ziel um [Quellwert] Gesundheit heilen lässt. Dieser Effekt tritt nur einmal alle paar Sekunden auf. 9 Aufladungen. Hält 10 Min. lang an. Der Erdschild kann immer nur auf jeweils einem Ziel aktiv sein.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[210763] = { ["name"] = "Alteks Zweig", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Ein gesplittertes Fragment der Macht. Es scheint, als wäre dies einst Teil einer bedeutenden Waffe gewesen.\"" }
entries[210765] = { ["name"] = "Kugel von Des", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Flammen und dunkle Magie wirbeln durch die Kugel, hypnotisierend und doch zutiefst bedrückend. Es scheint, als wäre dies einst Teil einer bedeutenden Waffe gewesen.\"" }
entries[210771] = { ["name"] = "Abgefangene Vorräte: Kupferbarren", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: [Waylaid Shipment] (12)\nBenutzen: Fügt 20 Kupferbarren hinzu, um die Lieferung zu vervollständigen." }
entries[210772] = { ["name"] = "Versorgungslieferung: Kupferbarren", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: [Supply Shipment] (1)\n\"Liefert sie an einen Versorgungsoffizier, um eine beträchtliche Belohnung zu erhalten.\"" }
entries[210773] = { ["name"] = "Mantel des Zweiten Krieges", ["text"] = "Wird beim Anlegen gebunden\nSchulter Kette\n163 Rüstung\n+8 Ausdauer\nHaltbarkeit 70 / 70\nBenötigt Stufe 25\nAnlegen: Erhöht durch Heiligzauber und Heiligeffekte zugefügten Schaden um bis zu 11." }
entries[210779] = { ["name"] = "Pläne: Mantel des Zweiten Krieges", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (150)\nBenutzen: Lehrt Euch, wie man einen Mantel des Zweiten Krieges herstellt.\nMantel des Zweiten Krieges\nWird beim Anlegen gebunden\nSchulter Kette\n163 Rüstung\n+8 Ausdauer\nHaltbarkeit 70 / 70\nBenötigt Stufe 25\nAnlegen: Erhöht durch Heiligzauber und Heiligeffekte zugefügten Schaden um bis zu 11.\nBenötigt Bronzebarren (20), Moosachat (2), Geringer Mondstein (2), Schillernde Perle (2), Silberbarren (4)" }
entries[210781] = { ["name"] = "Phönixbindungen", ["text"] = "Wird beim Anlegen gebunden\nHandgelenke Stoff\n21 Rüstung\nHaltbarkeit 30 / 30\nBenötigt Stufe 25\nAnlegen: Erhöht durch Feuerzauber und Feuereffekte zugefügten Schaden um bis zu 13." }
entries[210794] = { ["name"] = "Veränderliche silberne Brustplatte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Void-Touched] (1)\nBrust Kette\n238 Rüstung\n+12 Stärke\n+5 Ausdauer\nHaltbarkeit 145 / 145\nBenötigt Stufe 25\nBenötigt Schmiedekunst (100)\nAnlegen: Dieser Gegenstand ist mit der rohen Macht der Leere erfüllt. Wenn der Träger angegriffen wird, hat dieser Gegenstand eine hohe Chance, einen schrecklichen Fluch zu wirken, durch den der Angreifer 15 Sek. lang zusätzlichen Schaden aus allen Quellen erleidet. (Procchance: 25%)\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%." }
entries[210795] = { ["name"] = "Extraplanare Spinnenseidenstiefel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Void-Touched] (1)\nFüße Stoff\n35 Rüstung\n+5 Ausdauer\n+5 Intelligenz\n+6 Willenskraft\nHaltbarkeit 50 / 50\nBenötigt Stufe 25\nBenötigt Schneiderei (100)\nBenutzen: Tretet zeitweise in eine andere Existenzebene ein, was sofort die Bedrohung reduziert und allen erlittenen und verursachten Schaden 6 Sek. lang um 30% verringert. (10 Min Abklingzeit)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 7.\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%." }
entries[210811] = { ["name"] = "Rune des urzeitlichen Zorns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Eure Hosen mit der Rune 'Großer Geisterwolf':\n\nEure Fähigkeit 'Geisterwolf' kann nun drinnen benutzt werden und verringert sämtlichen erlittenen Schaden um 10%, so lange sie aktiv ist.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[210817] = { ["name"] = "Rune des Überlebens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Überleben des Stärkeren':\n\nVerringert die Chance, dass Ihr einen kritischen Treffer durch Nahkampfangriffe erleidet, um 6% und verringert jeglichen erlittenen Schaden um 10%. Verringert den erlittenen Schaden zusätzlich um 10%, während Ihr in Bärengestalt oder Terrorbärengestalt seid.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[210818] = { ["name"] = "Rune des einsamen Wolfs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Einsamer Wolf':\n\nIhr verursacht mit allen Angriffen 25% mehr Schaden, während Ihr kein Tier aktiviert habt.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[210820] = { ["name"] = "Rune der Opferung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Eure Hosen mit der Rune 'Hand der Aufopferung':\n\nLässt das anvisierte Gruppen- oder Schlachtzugsmitglied pro Treffer 30% des erlittenen Schadens auf den Zaubernden übertragen. Hält 12 Sek. lang an oder bis Schaden in Höhe von 100% der maximalen Gesundheit des Zaubernden übertragen wurde.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[210822] = { ["name"] = "Harmonische Offenbarung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Glücksfall':\n\nEure Heilung mit 'Blitzheilung' verringert die Zauberzeit Eures nächsten Einsatzes von 'Geringe Heilung', 'Heilung', 'Große Heilung' oder 'Gebet der Heilung' 20 Sek. lang um 20%. Bis zu 3-mal stapelbar.\n\"Erlernt eine neue Runenschnitzenfähigkeit.\"" }
entries[210823] = { ["name"] = "Rune der Beidhändigkeitsspezialisierung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Beidhändigkeitsspezialisierung':\n\nErhöht beim beidhändigen Führen Eure Chance, mit Zaubern und Nahkampfangriffen Treffer zu landen, um 5%. Außerdem trifft Eure Fähigkeit 'Sturmschlag' jetzt mit beiden Waffen, wenn Ihr beidhändig führt, und erhöht den verursachten Schaden Eurer Schildhandwaffe um 60%.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[210824] = { ["name"] = "Rune des Pakts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Eure Hosen mit der Rune 'Dämonischer Pakt':\n\nEure Feuer- und Schattenzauber verursachen 10% mehr Schaden und die kritischen Treffer Eures Begleiters belegen Eure Gruppen- oder Schlachtzugsmitglieder 45 Sek. lang mit dem Effekt 'Dämonischer Pakt'. Der dämonische Pakt erhöht den Zauberschaden und die Heilung um 10% Eures Zauberschadens oder um ( 60 / 2), je nachdem, welcher Wert höher ist. Unterworfene Dämonen können diesen Effekt nicht auslösen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[210825] = { ["name"] = "Rune des Kriegshetzers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Euer Brustteil mit der Rune 'Kriegstreiber':\n\nEure Fähigkeiten 'Sturmangriff', 'Abfangen' und 'Einschreiten' sind nun während des Kampfes und in jeder Haltung nutzbar und werden bei Aktivierung jegliche bewegungseinschränkenden Effekte entfernen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[210953] = { ["name"] = "Auge von Bhossca", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Obwohl das Auge leblos ist, fühlt Ihr Euch dennoch beobachtet...\"" }
entries[210955] = { ["name"] = "Uniform eines scharlachroten Initianden", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verkleidet Euch als ein Mitglied des Scharlachroten Kreuzzugs. Verdächtiges Verhalten lässt die Verkleidung auffliegen." }
entries[210963] = { ["name"] = "Seherschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke" }
entries[210966] = { ["name"] = "Blut der Legion", ["text"] = "Questgegenstand\nEinzigartig (10)\n\"Dunkel und dick... Dieses Blut reicht zurück zu großen Kommandanten der Legion.\"" }
entries[210967] = { ["name"] = "Vertrauliche Nachricht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n<Zum Lesen rechtsklicken>" }
entries[210968] = { ["name"] = "Reliquiarschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke" }
entries[210979] = { ["name"] = "Rune des Schattenschritts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Euren Gürtel mit der Rune 'Schattenschritt':\n\nVersucht, in die Schatten zu tauchen, um hinter dem Gegner zu erscheinen. Erhöht 3 Sek. lang die Bewegungsgeschwindigkeit um 70%.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[210980] = { ["name"] = "Rune der Metamorphose", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Eure Handschuhe mit der Rune 'Metamorphose':\n\nVerwandelt Euch in einen Dämon. Eure Rüstung wird um 500% und Eure Gesundheit um 15% erhöht und die Chance, kritische Treffer zu erleiden, um 6% verringert. Eure Bedrohung wird um 50% erhöht und 'Aderlass' gewährt 100% mehr Mana, doch Euer sämtlicher verursachter Schaden wird um 10% verringert. 'Metamorphose' verändert einige Fähigkeiten und gewährt neue:\n\n'Sengender Schmerz': Wird zu einem Spontanzauber.\n\n'Schattenblitz': Wird zu 'Schattenspalten', einem Nahkampfangriff, der bis zu 10 Gegner in der Nähe mit Schattenschaden trifft, aber eine Abklingzeit von 6 Sek. hat.\n\n'Furcht': Wird durch 'Plagegeist' ersetzt.\n\nVerspottet das Ziel, damit es Euch angreift. Hat keinen Effekt, wenn Ihr von dem Ziel bereits angegriffen werdet.\n\n'Dämonischer Ansturm'\n\nStürmt auf einen Gegner zu und betäubt ihn für 1 Sek. Kann nicht im Kampf verwendet werden.\n\n'Dämonisches Heulen'\n\nZwingt alle Gegner in der Nähe 6 Sek. lang, ihre Angriffe auf Euch zu konzentrieren.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[211205] = { ["name"] = "Rune des Kobraschlächters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nPrägt Eure Handschuhe mit der Rune 'Kobraschlächter':\n\n'Mungobiss' hat bei jedem Eurer Nahkampfangriffe eine Chance von 10%, aktiviert zu werden, sowie eine Chance von 100%, wenn der Gegner ausweicht. Diese Chance sammelt sich an und steigt durch jeden Angriff in Folge, bei dem sie nicht zurückgesetzt wird, um 10%. 'Mungobiss' verursacht zusätzlichen Schaden in Höhe von 45% Eurer Angriffskraft.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[211247] = { ["name"] = "Muster: Phönixbindungen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (125)\nBenutzen: Lehrt Euch, wie man Phönixbindungen näht.\nPhönixbindungen\nWird beim Anlegen gebunden\nHandgelenke Stoff\n21 Rüstung\nHaltbarkeit 30 / 30\nBenötigt Stufe 25\nAnlegen: Erhöht durch Feuerzauber und Feuereffekte zugefügten Schaden um bis zu 13.\nBenötigt Wollstoffballen (6), Fläschchen Öl (2), Feiner Faden (2)" }
entries[211263] = { ["name"] = "Brustschutz des Richturteils", ["text"] = "Wird beim Aufheben gebunden\nBrust Platte\n857 Rüstung\n+17 Stärke\n+25 Ausdauer\n+20 Intelligenz\n+10 Feuerwiderstand\n+10 Naturwiderstand\nHaltbarkeit 165 / 165\nKlassen: Paladin\nBenötigt Stufe 60\nAnlegen: Verteidigung +6.\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 14.\nAnlegen: Erhöht den Blockwert Eures Schilds um 32.\n\nBollwerk des Richturteils (0/1)\nBrustschutz des Richturteils\n(3) Set : Eure Aura der Hingabe verringert zusätzlich jeglichen erlittenen Zauberschaden um 5%.\n(5) Set : 'Richturteil' generiert zusätzlich 50% Bedrohung beim Ziel.\n(8) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 47." }
entries[211269] = { ["name"] = "Einfache Zeichnung", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest." }
entries[211272] = { ["name"] = "Leerer Köderkäfig", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fangt ein Kleintier, das als Köder genutzt werden kann." }
entries[211273] = { ["name"] = "Gefangenes Kleintier", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert ein Kleintier als Köder." }
entries[211293] = { ["name"] = "Blutrote Trophäenfeder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[211301] = { ["name"] = "Rune der aufgedeckten Schwäche", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nPrägt Euren Gürtel mit der Rune 'Schwäche aufdecken':\n\nEure kritischen Treffer mit Nahkampf- und Distanzangriffen erhöhen 7 Sek. lang Eure Angriffskraft um 40% Eurer aktuellen Beweglichkeit.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
