entries[211329] = { ["name"] = "Abgefangene Vorräte: Kräutergebackene Eier", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: [Waylaid Shipment] (12)\nBenutzen: Fügt 20 kräutergebackene Eier hinzu, um die Lieferung zu vervollständigen." }
