entries[211367] = { ["name"] = "Versorgungslieferung", ["text"] = "Wird beim Aufheben gebunden\n\"Liefert sie an einen Versorgungsoffizier, um eine beträchtliche Belohnung zu erhalten.\"" }
entries[211368] = { ["name"] = "Versorgungslieferung", ["text"] = "Wird beim Aufheben gebunden\n\"Liefert sie an einen Versorgungsoffizier, um eine beträchtliche Belohnung zu erhalten.\"" }
entries[211382] = { ["name"] = "Kleiner Kurierbeutel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n10 Platz Behälter" }
entries[211384] = { ["name"] = "Robuste Kuriertasche", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n12 Platz Behälter" }
entries[211385] = { ["name"] = "Rune der Schlangenspur", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nPrägt Eure Hosen mit der Rune 'Schlangenspur':\n\nZiele, die von Eurem 'Mehrfachschuss' getroffen werden, werden ebenfalls 12 Sek. lang mit 'Schlangenbiss' belegt.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[211386] = { ["name"] = "Zaubernotizen: Arkane Woge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Eure Hosen mit der Rune 'Arkane Woge':\n\nKanalisiert all Euer verbleibendes Mana in einer Woge aus Energie auf das Ziel. Verursacht [Quellwert] bis [Quellwert] Arkanschaden, der abhängig von Eurem verbleibenden Mana um bis zu 300% erhöht ist. Anschließend wird Eure normale Manaregeneration aktiviert und ist 8 Sek. lang um 300% erhöht.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[211387] = { ["name"] = "Rune des lockenden Lichts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Eure Handschuhe mit der Rune 'Flamme des Glaubens':\n\nDas Ziel wird für alle Gruppen- und Schlachtzugsmitglieder in einem Radius von 40 Metern zu einer Flamme des Glaubens. Alle auf diese Mitglieder gewirkten Heilungen heilen auch die Flamme um 75% der gewirkten Heilung. Es kann immer nur ein Ziel zur gleichen Zeit eine Flamme des Glaubens sein. Hält 1 Stunde lang an.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[211390] = { ["name"] = "Rune des Reizens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Nur eine Fleischwunde':\n\nIhr erleidet 20% weniger körperlichen Schaden, während 'Klingentanz' aktiv ist, verringert um weitere 1% pro 12 Punkte Eurer Verteidigungsfähigkeit über ( 60 * 5) hinaus. Außerdem wird Eure Ausweichchance mit 50% multipliziert und die Chance, dass Ihr kritische Treffer durch Nahkampfangriffe erleidet, um 6% verringert, Ihr verursacht 20% weniger Schaden, die Bedrohung durch all Eure Aktionen ist massiv erhöht und Eure Fähigkeit 'Finte' wird durch 'Reizen' ersetzt. 'Reizen' verspottet das Ziel, damit es Euch angreift.\n\nVerspottet das Ziel, damit es Euch angreift. Hat keinen Effekt, wenn Ihr von dem Ziel bereits angegriffen werdet.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[211391] = { ["name"] = "Rune des heilenden Regens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Heilender Regen':\n\nWählt einen Bereich von 15 Metern um den anvisierten Spielercharakter aus und heilt alle Gruppenmitglieder des anvisierten Spielercharakters im Bereich pro Sekunde um [Quellwert] Gesundheit.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[211392] = { ["name"] = "Rune der immerwährenden Gebrechen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Euren Hosen mit der Rune 'Immerwährende Gebrechen':\n\n'Blutsauger', 'Seelendieb', 'Schattenblitz', 'Schattenspalten', 'Sengender Schmerz', 'Einäschern' und 'Heimsuchung' setzen die Dauer Eurer 'Verderbnis' auf dem Ziel auf das Maximum zurück.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[211393] = { ["name"] = "Rune des zielstrebigen Furors", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Eure Handschuhe mit der Rune 'Zielstrebiger Furor':\n\nWenn Ihr mit zwei Waffen kämpft, wird Eure Bewegungsgeschwindigkeit um 10% erhöht und Ihr erhaltet immer, wenn Euer automatischer Angriff das selbe Ziel wie Euer vorheriger automatischer Angriff trifft, 4% Angriffstempo, bis zu einem Maximum von 5 Stapeln. Hält 10 Sek. lang an oder bis Eure automatischen Angriffe ein anderes Ziel treffen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[211419] = { ["name"] = "Handvoll veränderlicher Schuppen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Diese seltsamen Schuppen schimmern leicht, als wären sie nicht ganz körperlich. Hier ist sicherlich wundersame Magie am Spiel... wenn Ihr nur jemanden finden könntet, der mehr über sie weiß.\"" }
entries[211420] = { ["name"] = "Veränderlicher Schuppentalisman", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\n+5 Willenskraft\nBenötigt Stufe 25\nAnlegen: Schützt den Träger vor den Effekten von 'Erdrückende Dunkelheit'." }
entries[211421] = { ["name"] = "Die Kiste", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Versucht, eine mächtige Quelle des Lichts einzusetzen, um die Kiste zu zerstören.\n\"Wenn Ihr die Kiste mit bloßen Händen berührt, werdet Ihr sofort von tiefem Unwohlsein erfüllt... aber auch von einem Gefühl der kreativen Inspiration, das Ihr noch nie verspürt habt.\"" }
entries[211422] = { ["name"] = "Splitter der Leere", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Alles, was von der Kiste noch übrig ist, ist ein kleiner Splitter eines pechschwarzen Kristalls. Er scheint, das Licht anzuziehen und zu verschlucken.\"" }
entries[211423] = { ["name"] = "Leerenberührte Lederhandschuhe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Void-Touched] (1)\nHände Leder\n110 Rüstung\n+6 Beweglichkeit\n+6 Ausdauer\n+4 Willenskraft\nHaltbarkeit 70 / 70\nBenötigt Stufe 25\nBenötigt Lederverarbeitung (100)\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nBenutzen: Verfallt in Wahnsinn und erhöht so 10 Sek. lang Euer Angriffstempo um 10% sowie Eure erzeugte Bedrohung. (10 Min Abklingzeit)" }
entries[211426] = { ["name"] = "Zweig der Schatten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Dieser vom Smaragdgrünen Alptraum besudelte Splitter entzieht seinem Träger das Leben.\"" }
entries[211427] = { ["name"] = "Seelengefäß", ["text"] = "\"Fängt Dämonenseelen ein und entzieht ihnen Macht.\"" }
entries[211443] = { ["name"] = "Klinge des Zorns", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Schwert\n31 - 47 Schaden Tempo 3.50\n(11.14 Schaden pro Sekunde)\n50 Rüstung\n+3 Stärke\nHaltbarkeit 60 / 60\nBenötigt Stufe 13" }
entries[211444] = { ["name"] = "Beschwörerumhang", ["text"] = "Wird beim Aufheben gebunden\nRücken\n16 Rüstung\n+3 Intelligenz\n+1 Willenskraft\nBenötigt Stufe 13" }
