entries[211471] = { ["name"] = "Cliffspring-Schlüssel", ["text"] = "Einzigartig" }
entries[211472] = { ["name"] = "Buchband der Verbannung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Buchband\nKlassen: Paladin\nPrägt Eure Hosen mit der Rune 'Aurenmeisterschaft':\n\nVerleiht allen durch Eure Fähigkeit 'Aura der Konzentration' gestärkten Zielen Immunität gegen Unterbrechungs- und Stilleeffekte. Die Effekte aller anderen Auren werden um 100% erhöht. Hält 6 Sek. lang an.\n\"Erlernt eine neue Fähigkeit, nachdem Ihr 'Untote vertreiben' auf 5 Gegner gewirkt und diese dann mit 'Exorzismus' getötet habt.\"" }
entries[211476] = { ["name"] = "Rune des Feuersees", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'See des Feuers':\n\nEuer 'Feuerregen' wird nicht mehr kanalisiert, aber erhält eine Abklingzeit von 8 Sek.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[211477] = { ["name"] = "Rune des Verbrennens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Eure Armschienen mit der Rune 'Verbrennen':\n\nVerbrennt Euren Gegner, fügt ihm [Quellwert] bis [Quellwert] Schaden zu und erhöht jeglichen von Euch verursachten Feuerschaden 15 Sek. lang um 40%.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[211482] = { ["name"] = "Opfergabe der Shatterspear", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[211487] = { ["name"] = "Sprengladungen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Platziert eine Bombe mit einer kurzen Lunte auf dem Boden vor Euch.\n\"Scheint nur zum Entfernen von Schutt und Geröll gut zu sein.\"" }
entries[211488] = { ["name"] = "Rune des Rächers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Eure Hosen mit der Rune 'Schild des Rächers':\n\nSchleudert einen heiligen Schild auf den Gegner, der [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Zaubermacht + 0.091 * Angriffskraft] bis [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Zaubermacht + 0.091 * Angriffskraft] Heiligschaden verursacht, ihn benommen macht und dann auf weitere Gegner in der Nähe überspringt. Wirkt auf insgesamt 3 Ziele. Hält 5 Sek. lang an.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[211490] = { ["name"] = "Prophezeiung der tausend Lichter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Eure Handschuhe mit der Rune 'Kreis der Heilung':\n\nHeilt alle Gruppenmitglieder des anvisierten Spielercharakters innerhalb von 43.5 Metern um ihn herum um [Quellwert] bis [Quellwert] Gesundheit.\nBenutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist.\n\"Erlernt eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
