entries[211492] = { ["name"] = "Kelris' Beutel", ["text"] = "Wird beim Aufheben gebunden\n16 Platz Seelentasche\nKlassen: Hexenmeister" }
entries[211498] = { ["name"] = "Nachtsäbler des Schildwachenrekruten", ["text"] = "Wird beim Aufheben gebunden\nReittier\nBenötigt eine Allianz-Rasse\nBenötigt Stufe 25\nBenutzen: Beschwört einen Nachtsäbler des Schildwachenrekruten. Kann nur in Ashenvale verwendet werden. (3 Sek. Abklingzeit)" }
entries[211499] = { ["name"] = "Vorhutwolf des Rekruten", ["text"] = "Wird beim Aufheben gebunden\nReittier\nBenötigt eine Horde-Rasse\nBenötigt Stufe 25\nBenutzen: Beschwört einen Vorhutwolf des Rekruten. Kann nur in Ashenvale verwendet werden. (3 Sek. Abklingzeit)" }
