entries[211501] = { ["name"] = "Brustschutz der Macht", ["text"] = "Wird beim Aufheben gebunden\nBrust Platte\n749 Rüstung\n+27 Stärke\n+18 Ausdauer\n+10 Feuerwiderstand\nHaltbarkeit 165 / 165\nKlassen: Krieger\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Chance, einen kritischen Treffer zu erzielen, um 1%.\nAnlegen: Verbessert Eure Trefferchance um 1%." }
entries[211502] = { ["name"] = "Leerenberührte Lederstulpen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Void-Touched] (1)\nHände Leder\n70 Rüstung\n+5 Ausdauer\n+7 Intelligenz\n+6 Willenskraft\nHaltbarkeit 70 / 70\nBenötigt Stufe 25\nBenötigt Lederverarbeitung (100)\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nBenutzen: Verfallt in Wahnsinn und erhöht so 10 Sek. lang Euren Zauberschaden um 10% sowie Eure erzeugte Bedrohung. (10 Min Abklingzeit)" }
entries[211504] = { ["name"] = "Kettenpanzer des Twilight-Rächers", ["text"] = "Wird beim Aufheben gebunden\nBrust Kette\n218 Rüstung\n+9 Stärke\n+6 Beweglichkeit\n+8 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 25\nAnlegen: Verteidigung +4.\n\nKettenrüstung des Blackfathom-Rächers (0/3)\nStiefel des Twilight-Rächers\nKettenpanzer des Twilight-Rächers\nHelm des Twilight-Rächers\n(2) Set : +12 Angriffskraft.\n(3) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%." }
entries[211505] = { ["name"] = "Helm des Twilight-Rächers", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n176 Rüstung\n+9 Stärke\n+11 Beweglichkeit\n+3 Ausdauer\nHaltbarkeit 70 / 70\nBenötigt Stufe 25\nAnlegen: Verteidigung +4.\n\nKettenrüstung des Blackfathom-Rächers (0/3)\nStiefel des Twilight-Rächers\nKettenpanzer des Twilight-Rächers\nHelm des Twilight-Rächers\n(2) Set : +12 Angriffskraft.\n(3) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%." }
