entries[211508] = { ["name"] = "Fußpolster des Twilight-Elementaristen", ["text"] = "Wird beim Aufheben gebunden\nFüße Leder\n71 Rüstung\n+5 Beweglichkeit\n+7 Intelligenz\n+7 Willenskraft\nHaltbarkeit 55 / 55\nBenötigt Stufe 25\n\nLederrüstung des Blackfathom-Elementaristen (0/3)\nGugel des Twilight-Elementaristen\nFußpolster des Twilight-Elementaristen\nRobe des Twilight-Elementaristen\n(2) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\n(3) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%." }
entries[211509] = { ["name"] = "Robe des Twilight-Elementaristen", ["text"] = "Wird beim Aufheben gebunden\nBrust Leder\n103 Rüstung\n+10 Ausdauer\n+10 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Stufe 25\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 7.\n\nLederrüstung des Blackfathom-Elementaristen (0/3)\nGugel des Twilight-Elementaristen\nFußpolster des Twilight-Elementaristen\nRobe des Twilight-Elementaristen\n(2) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\n(3) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%." }
entries[211510] = { ["name"] = "Gugel des Twilight-Schlächters", ["text"] = "Wird beim Aufheben gebunden\nKopf Leder\n84 Rüstung\n+10 Beweglichkeit\n+9 Ausdauer\nHaltbarkeit 60 / 60\nBenötigt Stufe 25\nAnlegen: +14 Angriffskraft.\n\nLederrüstung des Blackfathom-Schlächters (0/3)\nGugel des Twilight-Schlächters\nFußpolster des Twilight-Schlächters\nTunika des Twilight-Schlächters\n(2) Set : +12 Angriffskraft.\n(3) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%." }
entries[211511] = { ["name"] = "Fußpolster des Twilight-Schlächters", ["text"] = "Wird beim Aufheben gebunden\nFüße Leder\n71 Rüstung\n+5 Stärke\n+7 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 55 / 55\nBenötigt Stufe 25\n\nLederrüstung des Blackfathom-Schlächters (0/3)\nGugel des Twilight-Schlächters\nFußpolster des Twilight-Schlächters\nTunika des Twilight-Schlächters\n(2) Set : +12 Angriffskraft.\n(3) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%." }
entries[211512] = { ["name"] = "Tunika des Twilight-Schlächters", ["text"] = "Wird beim Aufheben gebunden\nBrust Leder\n103 Rüstung\n+13 Beweglichkeit\n+9 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Stufe 25\n\nLederrüstung des Blackfathom-Schlächters (0/3)\nGugel des Twilight-Schlächters\nFußpolster des Twilight-Schlächters\nTunika des Twilight-Schlächters\n(2) Set : +12 Angriffskraft.\n(3) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%." }
entries[211514] = { ["name"] = "Zaubernotizen: Massenregeneration", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Euren Hosen mit der Rune 'Massenregeneration':\n\nHeilt alle verbündeten Gruppenmitglieder des anvisierten Spielercharakters innerhalb von 43.5 Metern um den anvisierten Spielercharakter im Verlauf von 3 Sek. um [Quellwert] Gesundheit und belegt jedes Ziel für 15 Sek. mit 'Zeitenleuchtfeuer'.\n\nZeitenleuchtfeuer\n\nErfasst die raumzeitliche Position des Subjekts. 70% sämtlichen Arkanschadens, den der Zaubernde verursacht hat, werden für alle aktuellen Ziele von 'Zeitenleuchtfeuer' des Zaubernden in chronomantische Heilung umgewandelt. Diese Heilung ist für den Zaubernden selbst um 50% verringert und wird zudem um 80% verringert, wenn durch arkane Zauber, die mehrere Ziele gleichzeitig treffen, Schaden verursacht wird.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[211527] = { ["name"] = "Gemütlicher Schlafsack", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ihr rollt einen Schlafsack aus. Wenn Ihr Euch darin mindestens eine Minute lang ausruht, erhaltet Ihr einen Bonus auf die verdiente Erfahrung. Der Effekt ist 3-mal stapelbar. (1 Stunde Abklingzeit)\n\"Alt, aber noch brauchbar.\"" }
entries[211528] = { ["name"] = "Dunkle Einsicht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nBenutzen: Meditiert über ein gewisses abgelegenes Grab im Dämmerwald, um eine Prophezeiung zu erhalten." }
entries[211530] = { ["name"] = "Prophezeiung der ergriffenen Stadt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Eure Armschienen mit der Rune 'Machtwort: Barriere':\n\nBeschwört eine heilige Barriere, die alle Gruppenmitglieder am Zielort 10 Sek. lang beschützt. Die Barriere verringert sämtlichen erlittenen Schaden um 25% und verhindert, dass erlittener Schaden das Zaubern verzögert.\nBenutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist." }
entries[211531] = { ["name"] = "Prophezeiung der sieben Besucher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Kraftvolle Seele':\n\n'Geringe Heilung', 'Heilung', 'Große Heilung' und 'Blitzheilung' verringern die verbleibende Dauer von 'Geschwächte Seele' auf den geheilten Zielen um 2 Sek. Zusätzlich erhalten Ziele Eures Zaubers 'Machtwort: Schild' 'Wut', wenn sie trotz absorbierten Schadens Schaden erleiden, und 'Zorn der Gerechtigkeit' wird durch von 'Machtwort: Schild' absorbiertem Schaden ausgelöst, als wäre es eine Heilung.\nBenutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist." }
entries[211534] = { ["name"] = "Ursprüngliche Eingebung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nBenutzen: Meditiert über einen Traumfänger der Distelfelle hoch in den Bäumen, um eine Prophezeiung zu erhalten." }
entries[211691] = { ["name"] = "Zaubernotizen: Arkanschlag", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Eure Handschuhe mit der Rune 'Arkanschlag':\n\nÜberzieht das Ziel mit Energie und verursacht [Quellwert] bis [Quellwert] Arkanschaden. Mit jedem Wirken von 'Arkanschlag' wird der verursachte Schaden aller anderen Arkanzauber um 15% und die Manakosten von 'Arkanschlag' werden um 175% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar und hält 6 Sek. lang an oder bis ein anderer Arkanschadenszauber gewirkt wird.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
