entries[211813] = { ["name"] = "Amulett der Schildwache der Silverwing", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Ihr habt das von einem gefallenen Kämpfer der Schildwachen der Silverwing erhalten. Der Scharfseher könnte daran interessiert sein.\"" }
