entries[211842] = { ["name"] = "Rakkamars zerfledderte Denkkappe", ["text"] = "Wird beim Aufheben gebunden\nKopf Stoff\n38 Rüstung\n+8 Intelligenz\n+6 Willenskraft\nHaltbarkeit 55 / 55\nBenötigt Stufe 25\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 14." }
entries[211843] = { ["name"] = "Maske der Verachtung", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n177 Rüstung\n+9 Stärke\n+7 Ausdauer\nHaltbarkeit 70 / 70\nBenötigt Stufe 25\nAnlegen: Verteidigung +7." }
entries[211845] = { ["name"] = "Blackfathom-Wetzstein", ["text"] = "Benutzen: Erhöht die Trefferchance 30 Min. lang um 2%, wenn es auf eine Waffe angewendet wird. Dies hat außerhalb der Blackfathom-Tiefe keinen Effekt.\n\"Diese geheimnisvollen verzauberten Steine scheinen immer heller zu leuchten, je tiefer Ihr in Blackfathom hinabsteigt.\"" }
entries[211846] = { ["name"] = "Pläne: Blackfathom-Wetzstein", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (100)\nBenutzen: Lehrt Euch die Herstellung eines Blackfathom-Wetzsteins.\n\nBlackfathom-Wetzstein\nBenutzen: Erhöht die Trefferchance 30 Min. lang um 2%, wenn es auf eine Waffe angewendet wird. Dies hat außerhalb der Blackfathom-Tiefe keinen Effekt.\n\"Diese geheimnisvollen verzauberten Steine scheinen immer heller zu leuchten, je tiefer Ihr in Blackfathom hinabsteigt.\"\nBenötigt Grober Wetzstein , Geringe Magieessenz" }
entries[211848] = { ["name"] = "Blackfathom-Manaöl", ["text"] = "Benötigt Stufe 25\nBenutzen: Stellt 5 Min. lang alle 5 Sek. 12 Mana wieder her und erhöht dabei den Zaubertrefferwert um 2%, wenn es auf eine Waffe angewendet wird. Dieser Effekt funktioniert nur in der Blackfathom-Tiefe.\n5 Aufladungen" }
entries[211849] = { ["name"] = "Formel: Blackfathom-Manaöl", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (100)\nBenutzen: Lehrt Euch die Herstellung von Blackfathom-Manaöl.\n\nBlackfathom-Manaöl\nBenötigt Stufe 25\nBenutzen: Stellt 5 Min. lang alle 5 Sek. 12 Mana wieder her und erhöht dabei den Zaubertrefferwert um 2%, wenn es auf eine Waffe angewendet wird. Dieser Effekt funktioniert nur in der Blackfathom-Tiefe.\n5 Aufladungen\nBenötigt Verbleite Phiole , Große Magieessenz , Seltsamer Staub (5)" }
entries[211852] = { ["name"] = "Handlappen des besudelten Wassers", ["text"] = "Wird beim Aufheben gebunden\nHände Stoff\n69 Rüstung\n+6 Ausdauer\n+4 Intelligenz\nHaltbarkeit 35 / 35\nBenötigt Stufe 25\nAnlegen: Erhöht durch Schattenzauber und Schatteneffekte zugefügten Schaden um bis zu 9." }
