entries[211940] = { ["name"] = "Ecks'avs Stammeswächter", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stangenwaffe\n155 - 231 Schaden Tempo 3.70\n(52.16 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\nBenötigt Stufe 59\nAnlegen: Gibt in der Nähe befindlichen Gruppenmitgliedern 4 Min. lang 40 zusätzliche Rüstung. Spieler können pro Paladin immer nur jeweils eine Aura besitzen." }
entries[211941] = { ["name"] = "Yari des Windläufers", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stangenwaffe\n147 - 223 Schaden Tempo 3.60\n(51.39 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\nBenötigt Stufe 58\nTrefferchance: Überzieht den Feind mit der Macht des Windes, des Feuers und all solchen Dingen!" }
entries[211944] = { ["name"] = "Tojaras Karma", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stangenwaffe\n158 - 234 Schaden Tempo 3.50\n(56.00 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\nBenötigt Stufe 58\nTrefferchance: Eine Flammenwelle geht vom Zaubernden aus, fügt allen Feinden, die da hineingeraten, 208 bis 249 Punkt(e) Feuerschaden zu und macht sie 6 Sek. lang benommen." }
entries[211953] = { ["name"] = "Schriftrolle der arkanen Erholung I", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 20\nBenutzen: Stellt alle 5 Sek. 8 Mana wieder her." }
entries[211954] = { ["name"] = "Schriftrolle der arkanen Präzision I", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 20\nBenutzen: Erhöht Eure Chance auf Treffer mit Zaubern um 1%." }
entries[211955] = { ["name"] = "Schriftrolle des Arkanschutzes - Feuer I", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 20\nBenutzen: Erhöht 30 Min. lang Euren Feuerwiderstand um 20." }
entries[211956] = { ["name"] = "Schriftrolle des Arkanschutzes - Frost I", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 20\nBenutzen: Erhöht 30 Min. lang Euren Frostwiderstand um 20." }
entries[211957] = { ["name"] = "Schriftrolle der arkanen Macht I", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 20\nBenutzen: Erhöht Eure Chance auf kritische Treffer mit Zaubern um 1%." }
entries[212160] = { ["name"] = "Chronostärkungsversetzer", ["text"] = "Saison der Entdeckungen\nBenutzen: Verändert das Gewebe der Zeit und schiebt positive Welteffekte auf, die aus Düsterbruch, Zul'Gurub und dem Teufelswald, sowie vom Drachentöten stammen. (5 Min Abklingzeit)" }
entries[212225] = { ["name"] = "Endloses Seelengefäß", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Euer nächster Einsatz eines Zaubers, der Seelensplitter verbraucht, kostet keine Seelensplitter. (5 Min Abklingzeit)" }
entries[212230] = { ["name"] = "Bauplan: Seelengefäß", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen: Lehrt Euch die Herstellung eines Seelengefäßes.\nSeelengefäß\n\"Fängt Dämonenseelen ein und entzieht ihnen Macht.\"\nBenötigt Schattenedelstein (4), Schwarzes Vitriol , Dämonenstatuette" }
entries[212347] = { ["name"] = "Illaris Schlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[212548] = { ["name"] = "Rune der Finsternis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Euren Gürtel mit der Rune 'Finsternis':\n\n'Sternenfeuer' erhöht die Chance auf kritische Treffer bei Euren nächsten beiden Einsätzen von 'Zorn' um 30%, und 'Zorn' verringert die Zauberzeit Eures nächsten Einsatzes von 'Sternenfeuer' um 1.0 Sek. Beide Effekte lassen sich bis zu 4-mal stapeln. Bei beiden Zaubern besteht außerdem jederzeit eine Chance von 70%, dass Ihr keine Zauberzeit verliert, wenn Ihr Schaden erleidet.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[212549] = { ["name"] = "Rune des Fallenstellers", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nPrägt Eure Stiefel mit der Rune 'Fallenschleuder':\n\nEure Eiskältefallen, Feuerbrandfallen und Sprengfallen können jetzt an jedem Ort innerhalb von 35 Metern ausgelegt werden. Außerdem haben Eure feuer- und frostbasierten Fallen jetzt getrennte gemeinsame Abklingzeiten.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[212551] = { ["name"] = "Rune der Kriegskunst", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Eure Stiefel mit der Rune 'Die Kunst des Krieges':\n\nEure kritischen Nahkampftreffer verringern die verbleibende Abklingzeit von 'Exorzismus' um 2 Sek., und die Manakosten von 'Exorzismus' werden um 80% verringert.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[212552] = { ["name"] = "Psychosophische Offenbarung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Euren Gürtel mit der Rune 'Gedankenstachel':\n\nFügt dem Ziel [Quellwert] bis [Quellwert] Schattenfrostschaden zu und erhöht die kritische Trefferchance Eures nächsten Einsatzes von 'Gedankenschlag' gegen das Ziel um 30%, bis zu 3-mal stapelbar.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[212553] = { ["name"] = "Juwelenbesetzte Schatulle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n<Zum Öffnen rechtsklicken>" }
entries[212559] = { ["name"] = "Rune der vergifteten Klinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Euren Gürtel mit der Rune 'Vergiftetes Messer':\n\nWirft sofort Eure Schildhandwaffe auf das Ziel und fügt ihm den normalen Schaden dieser Waffe zu. Außerdem besteht eine Chance von 100%, das Ziel mit dem Gift Eurer Schildhandwaffe zu belegen. Gewährt 1 Combopunkt. Erstattet 5 Energie pro Anwendung von 'Tödliches Gift' auf dem Ziel.\n\n'Vergiftetes Messer' nutzt die Vorteile aller Talente und Effekte, die durch 'Finsterer Stoß' ausgelöst werden oder 'Finsterer Stoß' modifizieren.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[212560] = { ["name"] = "Rune des Erwachens der Ahnen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Eure Stiefel mit der Rune 'Erwachen der Ahnen':\n\nWenn Ihr mit 'Welle der Heilung' oder 'Geringe Welle der Heilung' einen kritischen Effekt erzielt, wird ein Ahnengeist beschworen, der sofort das Gruppenmitglied mit der geringsten Gesundheit innerhalb von 40 Metern um 30% des von Euch geheilten Wertes heilt.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[212561] = { ["name"] = "Rune der brennenden Dunkelheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Euren Gürtel mit der Rune 'Schatten und Flamme':\n\nKritische Treffer Eurer Feuer- und Schattenzauber erhöhen den von Euch verursachten Feuer und Schattenschaden 10 Sek. lang um 10%.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[212562] = { ["name"] = "Rune des heilenden Zorns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Eure Stiefel mit der Rune 'Wütende Regeneration':\n\nHeilt Euch im Verlauf von 10 Sek. um 30% Eurer maximalen Gesundheit, kann jedoch nur eingesetzt werden, während 'Wutanfall', 'Berserkerwut' oder 'Blutrausch' aktiv ist. Kann auch während Betäubung eingesetzt werden.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[212568] = { ["name"] = "Wolfskopftrophäe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nBenötigt Stufe 40\nBenutzen: Einen Gegenstand für den Helmplatz dauerhaft verzaubern, sodass Ihr 20 Energie oder 5 Wut erhaltet, wenn Ihr Euch in die Katzen- oder Bärengestalt verwandelt." }
entries[212580] = { ["name"] = "Stab des Wissenshüters", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n57 - 87 Schaden Tempo 2.90\n(24.83 Schaden pro Sekunde)\n+10 Ausdauer\n+6 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Stufe 25\nAnlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her." }
entries[212581] = { ["name"] = "Bogen des Kundschafters", ["text"] = "Wird beim Aufheben gebunden\nDistanz Bogen\n25 - 47 Schaden Tempo 2.40\n(15.00 Schaden pro Sekunde)\nHaltbarkeit 80 / 80\nBenötigt Stufe 25" }
entries[212582] = { ["name"] = "Schwert des Beschützers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nEinhändig Schwert\n35 - 67 Schaden Tempo 2.70\n(18.89 Schaden pro Sekunde)\n+6 Stärke\n+3 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 25" }
entries[212583] = { ["name"] = "Klinge der Schildwache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nEinhändig Dolch\n22 - 43 Schaden Tempo 1.70\n(19.12 Schaden pro Sekunde)\n+6 Beweglichkeit\n+3 Ausdauer\nHaltbarkeit 65 / 65\nBenötigt Stufe 25" }
entries[212584] = { ["name"] = "Knorriger Stab des Beraters", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n57 - 87 Schaden Tempo 2.90\n(24.83 Schaden pro Sekunde)\n+10 Ausdauer\n+6 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Stufe 25\nAnlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her." }
entries[212585] = { ["name"] = "Bogen der Vorhut", ["text"] = "Wird beim Aufheben gebunden\nDistanz Bogen\n25 - 47 Schaden Tempo 2.40\n(15.00 Schaden pro Sekunde)\nHaltbarkeit 80 / 80\nBenötigt Stufe 25" }
entries[212586] = { ["name"] = "Schwert des Legionärs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nEinhändig Schwert\n35 - 67 Schaden Tempo 2.70\n(18.89 Schaden pro Sekunde)\n+6 Stärke\n+3 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 25" }
entries[212587] = { ["name"] = "Klinge des Spähers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nEinhändig Dolch\n22 - 43 Schaden Tempo 1.70\n(19.12 Schaden pro Sekunde)\n+6 Beweglichkeit\n+3 Ausdauer\nHaltbarkeit 65 / 65\nBenötigt Stufe 25" }
entries[212588] = { ["name"] = "Handschuhe des Versorgers", ["text"] = "Wird beim Aufheben gebunden\nHände Stoff\n20 Rüstung\n+3 Ausdauer\n+3 Willenskraft\nHaltbarkeit 20 / 20\nBenötigt Stufe 12" }
entries[212589] = { ["name"] = "Treter des Kuriers", ["text"] = "Wird beim Aufheben gebunden\nFüße Leder\n50 Rüstung\n+4 Beweglichkeit\nHaltbarkeit 35 / 35\nBenötigt Stufe 12" }
entries[212590] = { ["name"] = "Tragegurt", ["text"] = "Wird beim Aufheben gebunden\nTaille Kette\n85 Rüstung\n+2 Stärke\n+2 Ausdauer\nHaltbarkeit 25 / 25\nBenötigt Stufe 12" }
entries[212693] = { ["name"] = "Verdorbener Samen", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest." }
entries[212723] = { ["name"] = "Bebende Essenz", ["text"] = "Questgegenstand\nEinzigartig (10)" }
entries[212724] = { ["name"] = "Wirbelnde Essenz", ["text"] = "Questgegenstand\nEinzigartig (10)" }
entries[212726] = { ["name"] = "Rauschende Essenz", ["text"] = "Questgegenstand\nEinzigartig (10)" }
entries[212748] = { ["name"] = "Zerfledderte Notiz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 30" }
entries[212792] = { ["name"] = "Auge des Gewittersturms", ["text"] = "Questgegenstand\nEinzigartig" }
entries[212982] = { ["name"] = "Böenbrechertrank", ["text"] = "Questgegenstand\nEinzigartig\nBenötigt Stufe 30\nBenutzen: Schützt Euch vor den Elementen. (5 Min Abklingzeit)" }
entries[212994] = { ["name"] = "Bindungen des Sturmjägers", ["text"] = "Wird beim Aufheben gebunden\nHandgelenke Leder\n53 Rüstung\n+8 Stärke\n+7 Beweglichkeit\n+5 Ausdauer\nHaltbarkeit 35 / 35\nKlassen: Schamane\nBenötigt Stufe 35" }
entries[212996] = { ["name"] = "Bindungen des Blitzrufers", ["text"] = "Wird beim Aufheben gebunden\nHandgelenke Leder\n53 Rüstung\n+5 Ausdauer\n+7 Intelligenz\nHaltbarkeit 35 / 35\nKlassen: Schamane\nBenötigt Stufe 35\nAnlegen: Erhöht Eure Chance mit Zaubern zu treffen um 1%." }
entries[212997] = { ["name"] = "Bindungen des Gezeitenrufers", ["text"] = "Wird beim Aufheben gebunden\nHandgelenke Leder\n53 Rüstung\n+5 Ausdauer\n+7 Intelligenz\nHaltbarkeit 35 / 35\nKlassen: Schamane\nBenötigt Stufe 35\nAnlegen: Stellt alle 5 Sek. 3 Punkt(e) Mana wieder her." }
entries[213036] = { ["name"] = "Wasser aus Elune'ara", ["text"] = "Questgegenstand\nDauer: 1 Stunde (Realzeit)\nBenutzen: Gebt einem Urtumschössling Wasser. (1 Min Abklingzeit)\n\"Eine zerbrechliche Kugel mit Wasser, gesegnet vom Urtum Orokai.\"" }
entries[213074] = { ["name"] = "Rune der Pflege", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Euren Gürtel mit der Rune 'Pflege':\n\nHeilt ein verbündetes Ziel um [Quellwert] bis [Quellwert] Gesundheit. Wenn ein durch Euch gewirkter Effekt von 'Verjüngung', 'Nachwachsen', 'Wildwuchs' oder 'Blühendes Leben' auf dem Ziel aktiv ist, erhöht sich die Heilung um zusätzliche 20%. Dieser Zauber profitiert von allen Effekten von 'Heilende Berührung' oder 'Nachwachsen' und löst diese aus.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[213086] = { ["name"] = "Rune des Stroms", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Euren Gürtel mit der Rune 'Waffe des Mahlstroms':\n\nWenn Ihr mit einem Nahkampfangriff Schaden verursacht, besteht eine Chance, dass die Zauberzeit und Manakosten Eures nächsten Einsatzes von 'Blitzschlag', 'Kettenblitzschlag', 'Geringe Welle der Heilung' oder 'Lavaeruption' um 20% verringert werden. Diese Chance ist um 50% erhöht, während Eure Waffenhandwaffe mit 'Waffe des Windzorns' belegt ist, und um weitere 50% erhöht, wenn Ihr eine Zweihandwaffe führt. Bis zu 5-mal stapelbar. Hält 30 Sek. lang an.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213087] = { ["name"] = "Umhang des Waffenträgers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRücken\n24 Rüstung\n+4 Stärke\n+4 Beweglichkeit\n+4 Ausdauer\n+4 Intelligenz\n+4 Willenskraft\nBenötigt Stufe 25" }
entries[213088] = { ["name"] = "Umhang des Waffenträgers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRücken\n24 Rüstung\n+4 Stärke\n+4 Beweglichkeit\n+4 Ausdauer\n+4 Intelligenz\n+4 Willenskraft\nBenötigt Stufe 25" }
entries[213090] = { ["name"] = "Rune der Synergie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Euren Gürtel mit der Rune 'Grimoire der Synergie':\n\nWenn Ihr oder Euer beschworener Dämon Schaden verursacht, besteht eine Chance von 10%, den verursachten Schaden des anderen 15 Sek. lang um 10% zu erhöhen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213092] = { ["name"] = "Rune des Alphas", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Eure Stiefel mit der Rune 'Geist des Alphas':\n\nErfüllt das Ziel mit dem Geist eines Alphawolfes, was die generierte Bedrohung des Ziels 30 Min. lang um 45% erhöht. Maximal 1 Ziel. Wenn der Schamane diesen Zauber nicht auf sich selbst wirkt, erhält er 'Treuer Beta', was 30 Min. lang seinen verursachten körperlichen Schaden um 5% erhöht und jegliche erzeugte Bedrohung um 30% verringert. Ein Ziel kann nicht gleichzeitig mit 'Geist des Alphas' und 'Treuer Beta' belegt sein.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213093] = { ["name"] = "Rune der Kraft", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Euren Gürtel mit der Rune 'Kraftwoge':\n\nJedes Mal, wenn Euer 'Flammenschock' Schaden verursacht, besteht eine Chance von 5%, dass die Abklingzeiten von 'Lavaeruption' und 'Kettenblitzschlag' abgeschlossen werden und Euer nächster Einsatz von 'Lavaeruption' oder 'Kettenblitzschlag' innerhalb von 10 Sek. ein Spontanzauber ist. Jedes Mal, wenn Eure 'Springflut' heilt, besteht eine Chance von 5%, dass Euer nächster Einsatz von 'Kettenheilung' innerhalb von 10 Sek. ein Spontanzauber ist. Zusätzlich erhaltet Ihr alle 5 Sek. Mana in Höhe von 15% Eurer Intelligenz.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213094] = { ["name"] = "Rune der Feuernova", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Euren Gürtel mit der Rune 'Feuernova':\n\nEuer Totem der Feuernova wird durch 'Feuernova' ersetzt. Dadurch verursacht Euer derzeitiges Feuertotem Schaden an seinem Standort.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213096] = { ["name"] = "Rune der Täuschung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Eure Stiefel mit der Rune 'Täuschtotem':\n\nBeschwört zu Füßen des Ziels ein Täuschtotem mit 5 Gesundheit, das 10 Sek. lang bestehen bleibt und den nächsten Nahkampf- oder Distanzangriff auf das Ziel stattdessen auf das Totem ablenkt. Das Totem gewährt dem Ziel außerdem 10 Sek. lang Immunität gegen bewegungseinschränkende Effekte.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213098] = { ["name"] = "Rune der Anrufung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Euren Gürtel mit der Rune 'Anrufung':\n\nWenn Ihr 'Verderben', 'Feuerbrand', 'Fluch der Pein', 'Instabiles Gebrechen', 'Schattenflamme' oder 'Lebensentzug' anwendet, fügt dies dem Ziel sofortigen Schaden in Höhe eines Ticks des regelmäßigen Schadens des Zaubers zu. Wenn die verbleibende Effektdauer weniger als 6 Sek. beträgt, fügt das Erneuern eines dieser Zauber dem Ziel sofortigen Schaden in Höhe des verbleibenden regelmäßigen Schadens des Zaubers zu.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213100] = { ["name"] = "Rune des verbotenen Wissens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Eure Stiefel mit der Rune 'Dämonisches Wissen':\n\nErhöht Zauberschaden und -heilung um einen Wert, der 3% der maximalen Ausdauer plus der Intelligenz Eures Dämons entspricht.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213101] = { ["name"] = "Rune der Schattenflammen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Eure Stiefel mit der Rune 'Schattenflamme':\n\nVerbrennt den Gegner und fügt ihm [Quellwert] Schattenflammenschaden sowie zusätzlich [Quellwert] Schattenflammenschaden im Verlauf von 15 Sek. zu.\n\n'Schattenflamme' wird ausgelöst und profitiert von allen Effekten, die 'Feuerbrand' modifizieren oder damit oder mit Gebrechen-, Zerstörungs-, Feuer- oder Schattenzaubern interagieren. Auf einem Ziel kann immer nur ein Effekt von 'Feuerbrand' oder 'Schattenflamme' pro Hexenmeister aktiv sein. Zusätzlich kann 'Schattenflamme' das Talent 'Verbesserter Schattenblitz' auslösen und gewährt diesem 26 zusätzliche Aufladungen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[213102] = { ["name"] = "Rune der Tücke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Eure Stiefel mit der Rune 'Tanz des Tückischen':\n\nIhr und Euer Dämon erhaltet jedes Mal, wenn Ihr einem Gegner einen kritischen Treffer zufügt, eine Ausweichchance in Höhe von 70% Eurer kritischen Zaubertrefferchance. Ihr beide gewinnt außerdem 2% Eures maximalen Manas zurück.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213103] = { ["name"] = "Rune der Blutwoge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Euren Gürtel mit der Rune 'Blutwoge':\n\nBeim Einsatz von 'Heldenhafter Stoß', 'Blutdurst' und 'Wirbelwind' besteht eine Chance von 30%, dass Euer nächster Einsatz von 'Zerschmettern' innerhalb von 15 Sek. sofort eingesetzt wird, mit beiden Nahkampfwaffen zuschlägt und keine Wut kostet.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213104] = { ["name"] = "Rune der unbarmherzigen Präzision", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Euren Gürtel mit der Rune 'Genau zur rechten Zeit':\n\n'Zerschmettern' wird jetzt sofort eingesetzt, hat allerdings eine Abklingzeit von 6 Sek.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213105] = { ["name"] = "Schawarmageddon", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n50 - 93 Schaden Tempo 2.60\n(27.50 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\nKlassen: Krieger\nBenötigt Stufe 40\nBenutzen: Erhöht das Angriffstempo um 4% und verleiht allen Nahkampfangriffen eine Chance, zusätzlich 7 Feuerschaden zu verursachen. (2 Min Abklingzeit)" }
entries[213109] = { ["name"] = "Rune der fokussierten Wut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Euren Gürtel mit der Rune 'Fokussierte Wut':\n\nVerringert die Wutkosten aller Angriffsfähigkeiten um 3.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213110] = { ["name"] = "Rune des Kommandanten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Eure Stiefel mit der Rune 'Anspornender Schrei':\n\nStoßt einen anspornenden Schrei aus, der die maximale Gesundheit aller Gruppen- und Schlachtzugsmitglieder innerhalb von 40 Metern 10 Sek. lang um 15% erhöht.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213111] = { ["name"] = "Rune des Einschreitens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Eure Stiefel mit der Rune 'Einschreiten':\n\nLauft mit hoher Geschwindigkeit auf ein Gruppenmitglied zu, um den nächsten Nahkampf- oder Distanzangriff gegen diese Person abzufangen und seine gesamte Bedrohung um 10% zu verringern.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213112] = { ["name"] = "Zaubernotizen: Geschosssalve", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Euren Gürtel mit der Rune 'Geschosssalve':\n\nVerleiht Eurem Zauber 'Arkanschlag' eine Chance von 40% sowie Euren Zaubern 'Feuerball' und 'Frostblitz' eine Chance von 20%, die Kanalisierungsdauer Eures nächsten Einsatzes von 'Arkane Geschosse' um 50% zu verringern, die Manakosten um 100% zu verringern und alle 0,5 Sek. Geschosse abzufeuern.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213113] = { ["name"] = "Zaubernotizen: Kampfeshitze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Euren Helm mit der Rune 'Kampfeshitze':\n\nJedes Mal, wenn Ihr mit 'Feuerball', 'Frostfeuerblitz', 'Qualfeuerblitz', 'Feuerschlag', 'Versengen' oder 'Lebende Bombe' 2 unregelmäßige kritische Zaubertreffer in Folge erzielt, wird Euer nächster Einsatz von 'Pyroschlag' innerhalb von 10 Sek. zu einem Spontanzauber und kostet 100% weniger Mana.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213116] = { ["name"] = "Zaubernotizen: Chronostatische Bewahrung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Eure Stiefel mit der Rune 'Chronostatische Bewahrung':\n\nVerbindet Arkan-, Feuer- und Frostmagie, um chronomantische Energie zur Aufbewahrung und späteren Verwendung einzufrieren. Ihr könnt diese Energie bis zu 20 Sek. lang speichern, bevor sie explodiert und verschwindet. Heilt bei Freisetzung ein verbündetes Ziel um [Quellwert] bis [Quellwert] Gesundheit.\n\nDieser Zauber gilt in Interaktionen mit anderen Zaubern, Talenten und Effekten als Arkan, Feuer und Frost.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[213117] = { ["name"] = "Rune des Berserkers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Euren Gürtel mit der Rune 'Berserker':\n\nWenn aktiviert, lässt diese Fähigkeit 'Zerfleischen (Bär)' und 'Aufschlitzen' bis zu 3 Ziele treffen. 'Aufschlitzen' kostet keine Wut und 'Zerfleischen (Bär)' unterliegt keiner Abklingzeit. In Katzengestalt werden die Energiekosten aller Eurer Fähigkeiten um 50% verringert. Hält 15 Sek. lang an. Erfordert Katzengestalt, Bärengestalt oder Terrorbärengestalt.\n\nEntfernt sofort Furchteffekte und macht Euch während seiner Dauer gegen sie immun.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213118] = { ["name"] = "Rune des Königs des Dschungels", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Eure Stiefel mit der Rune 'König des Dschungels':\n\n'Tigerfuror' erhöht nun jeglichen von Euch verursachten körperlichen Schaden um 15% statt eines festen Werts und gewährt Euch sofort 60 Energie. Der Zauber ist nicht mehr an die globale Abklingzeit gebunden, hat aber nun seine eigene Abklingzeit von 30 Sekunden. Zusätzlich bleibt 'Tigerfuror' bestehen, wenn Ihr Euch nicht mehr in Katzengestalt befindet, wird jedoch entfernt, sobald Ihr in Bären- oder Terrorbärengestalt wechselt.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213119] = { ["name"] = "Rune des Instinkts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Eure Stiefel mit der Rune 'Überlebensinstinkte':\n\nNach Aktivierung erhaltet Ihr 20 Sek. lang 30% Eurer maximalen Gesundheit. Während dieser Zeit wird zudem sämtliche von Euch hervorgerufene nichtkörperliche Heilung um 20% erhöht. Nachdem der Effekt abgelaufen ist, geht die Gesundheit verloren. Kann in jeder Gestalt mit Ausnahme der Moonkingestalt eingesetzt werden.\n\nZusätzlich regeneriert Ihr bei jedem Ausweichen in Bärengestalt oder Terrorbärengestalt 5 Wut, in Katzengestalt 10 Energie oder in jeder anderen Gestalt 1% Eures maximalen Manas.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213120] = { ["name"] = "Rune des Träumers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Eure Stiefel mit der Rune 'Traumzustand':\n\nKritische Treffer Eurer nicht regelmäßigen Schadenszauber und jeglicher Schaden von Eurem 'Sternensog' gewähren Euch 8 Sek. lang 50% Manaregeneration, während Ihr Zauber wirkt. Der Arkan- und Naturschaden gegen Ziele, bei denen es sich nicht um Spielercharaktere handelt, wird außerdem 12 Sek. lang um 20% erhöht.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213121] = { ["name"] = "Konservierter Tannenzweig", ["text"] = "Benötigt Stufe 25\nBenutzen: Verwandelt Euer Reittier in eine etwas festlichere Gestalt. (1 Min Abklingzeit)" }
entries[213122] = { ["name"] = "Rune des zuverlässigen Schusses", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nPrägt Euren Gürtel mit der Rune 'Zuverlässiger Schuss':\n\nEin zuverlässiger Schuss, der 100% Schaden mit Distanzwaffen verursacht.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213123] = { ["name"] = "Rune des Aufdeckens", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nPrägt Euren Gürtel mit der Rune 'Schwäche aufdecken':\n\nEure kritischen Treffer mit Nahkampf- und Distanzangriffen erhöhen 7 Sek. lang Eure Angriffskraft um 40% Eurer aktuellen Beweglichkeit.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213124] = { ["name"] = "Rune des Nahkampfs", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nPrägt Euren Gürtel mit der Rune 'Nahkampfspezialist':\n\n'Raptorstoß' ist nun ein Spontanzauber, und 'Mungobiss' und 'Raptorstoß' haben bei jedem Angriff eine Chance von 40%, die Abklingzeiten von 'Mungobiss' und 'Raptorstoß' abzuschließen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213125] = { ["name"] = "Rune der Kräftigung", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nPrägt Eure Stiefel mit der Rune 'Flügeldrachenstoß':\n\nErsetzt Eure Fähigkeit 'Stich des Flügeldrachen' durch 'Flügeldrachenstoß', einen grausamen Stoß, der 140% Waffenschaden verursacht und dem Ziel regelmäßigen Blutungsschaden zufügt.\n\n'Flügeldrachenstoß' erfordert, dass Ihr das Talent 'Stich des Flügeldrachen' erlernt und ersetzt die 'Stich des Flügeldrachen'-Fähigkeiten aus dem Überleben-Zauberbuch.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213126] = { ["name"] = "Rune des Streiters", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nPrägt Eure Stiefel mit der Rune 'Beidhändigkeitsspezialisierung':\n\nErhöht den von Eurer Schildhandwaffe verursachten Schaden um 60% und führt dazu, dass Euer 'Raptorstoß' mit beiden Waffen trifft, wenn Ihr beidhändig kämpft.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213127] = { ["name"] = "Zaubernotizen: BLAUBERZORFSTITZ", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenutzen: Entschlüsselt die Zaubernotizen mit einem Verständnisamulett, um einen neuen Runenschnitzenzauber zu erlernen." }
entries[213128] = { ["name"] = "Rune der Frömmigkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Euren Gürtel mit der Rune 'Formbarer Schutz':\n\nIhr könnt handeln, während 'Göttlicher Schutz' aktiv ist, und die Dauer ist um 50% erhöht. Die Fähigkeit verringert Euren erlittenen Schaden jedoch nur um 50%, anstatt Euch immun zu machen. Das Aktivieren von 'Heiliger Schild' gewährt Euch außerdem 4 Angriffskraft pro Punkt Eurer Verteidigungsfähigkeit, der über ( 60 * 5) hinausgeht. Hält 15 Sek. lang an.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213129] = { ["name"] = "Rune der Umarmung des Lichts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Euren Gürtel mit der Rune 'Ummantelung des Lichts':\n\nWenn Ihr mit Eurer Nahkampfwaffe Schaden verursacht, erhöht sich Euer Zauberschaden 1 Min. lang um einen Betrag in Höhe von 30% Eurer Angriffskraft.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213130] = { ["name"] = "Rune der Infusion", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Euren Gürtel mit der Rune 'Lichtinfusion':\n\nErhöht den Schaden und die Heilung, die Euer 'Heiliger Schock' verursacht, um 50%, und reduziert die Abklingzeit von 'Heiliger Schock' auf 6 Sek. Zudem erstatten Eure kritischen Treffer mit 'Heiliger Schock' die Manakosten und verringern die verbleibende Abklingzeit um 3 Sek.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213131] = { ["name"] = "Rune des geheiligten Schildes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Eure Stiefel mit der Rune 'Geheiligter Schild':\n\nJedes Mal, wenn das Ziel Schaden erleidet, wird es von einem geheiligten Schild umhüllt, der [Quellwert] Schaden absorbiert und die Chance des Paladins, mit 'Lichtblitz' einen kritischen Treffer zu erzielen, bis zu 6 Sek. lang um 50% erhöht. Zusätzlich heilen Eure Einsätze von 'Lichtblitz' Ziele mit 'Geheiligter Schild' im Verlauf von 12 Sek. um weitere 100% Gesundheit. Dieser Effekt kann nur einmal alle 6 Sek. auftreten. Hält 1 Min. lang an. Es kann immer nur jeweils ein Ziel mit diesem Zauber belegt sein.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[213132] = { ["name"] = "Rune des Behüters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Eure Stiefel mit der Rune 'Vom Licht behütet':\n\nJedes Mal, wenn Ihr ein Ziel mit Eurer Nahkampfwaffe trefft, gewinnt Ihr 15 Sek. lang alle 3 Sek. 5% Eures maximalen Manas. Während dieser Manaregeneration ist der durch Eure Heilzauber geheilte Wert jedoch um 50% verringert.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213136] = { ["name"] = "Rune des hinterhältigen Angriffs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Eure Stiefel mit der Rune 'Meister des hinterhältigen Angriffs':\n\nAngriffe, die aus dem Verstohlenheitsmodus und bis zu 6 Sek. nach Verlassen des Verstohlenheitsmodus ausgeführt werden, verursachen 10% zusätzlichen Schaden.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213137] = { ["name"] = "Rune des Auflauernden", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Eure Stiefel mit der Rune 'Auflauern':\n\nDie Treffer Eurer Fähigkeiten 'Hinterhalt' und 'Meucheln' bringen Euer Ziel aus dem Gleichgewicht, was die Zeit zwischen seinen Nahkampfangriffen um 10% erhöht sowie seine Bewegungsgeschwindigkeit um 50% verringert. Hält 8 Sek. lang an.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213138] = { ["name"] = "Rune des Rechtsauslegers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Eure Stiefel mit der Rune 'Schläge abschwächen':\n\nJedes Mal, wenn Ihr ausweicht oder pariert, erhaltet Ihr 5% mehr Gesundheit. Bis zu 5-mal stapelbar.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213139] = { ["name"] = "Rune des Assassinen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Euren Gürtel mit der Rune 'Shurikenwurf':\n\nWirft einen Shuriken auf Euren Gegner, der Schaden in Höhe von 50% Eurer Angriffskraft verursacht und bis zu 4 weitere Gegner in der Nähe trifft. Gewährt 1 Combopunkt pro getroffenem Ziel.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213140] = { ["name"] = "Prophezeiung des beschleunigten Pfads", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Euren Gürtel mit der Rune 'Machterfüllte Erneuerung':\n\nEuer Einsatz von 'Erneuerung' heilt sofort ein weiteres Mal und profitiert bei jeder Heilung um 15% mehr von Eurem Bonus für Heilungseffekte.\n\nDarüber hinaus kann Eure 'Erneuerung' jetzt auf Zielen aktiv sein, die von 'Erneuerung' eines anderen Priesters betroffen sind.\nBenutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist." }
entries[213141] = { ["name"] = "Rune der Hoffnung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Euren Gürtel mit der Rune 'Erneuerte Hoffnung':\n\nErhöht die Effekte Eurer Einsätze von 'Blitzheilung', 'Geringe Heilung', 'Heilung', 'Große Heilung' und 'Sühne' um 20%, wenn Ihr sie auf Ziele anwendet, die mit 'Geschwächte Seele' belegt sind.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213142] = { ["name"] = "Prophezeiung der gefangenen Bösartigkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Eure Stiefel mit der Rune 'Dispersion':\n\nLöst Euch zu reiner Schattenenergie auf und verringert jeglichen erlittenen Schaden um 90%. Ihr könnt weder angreifen noch Zauber wirken, regeneriert jedoch 6 Sek. lang alle 1 Sek. 6% Mana. 'Dispersion' kann gewirkt werden, während Betäubungs-, Furcht- oder Stilleeffekte auf Euch wirken. Bei Anwendung werden alle wirkenden Verlangsamungs- und bewegungseinschränkenden Effekte entfernt und Ihr werdet für die Dauer des Effektes von 'Dispersion' gegen sie immun.\nBenutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist." }
entries[213143] = { ["name"] = "Apokryphische Offenbarung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Eure Stiefel mit der Rune 'Schmerzunterdrückung':\n\nVerringert sofort sämtlichen Schaden, den ein verbündetes Ziel erleidet, um 40% und erhöht den Widerstand gegen Bannzauber 8 Sek. lang um 65%.\n\"Erlernt eine neue Runenschnitzenfähigkeit.\"" }
entries[213144] = { ["name"] = "Leuchtende Offenbarung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Eure Stiefel mit der Rune 'Geist des Erlösers':\n\nAktivieren, um 10 Sek. lang zum Geist der Erlösung zu werden. In dieser Gestalt könnt Ihr alle Heilzauber kostenlos wirken, Ihr könnt Euch aber nicht bewegen, nicht angreifen, nicht angegriffen werden oder von Zaubern oder Effekten als Ziel ausgewählt werden. Erfordert das Talent 'Geist der Erlösung', um aktiviert zu werden, und wenn Ihr sterbt, nehmt Ihr die Gestalt 'Geist der Erlösung' nicht mehr an.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[213165] = { ["name"] = "Basilisken: Muss man Angst vor der Versteinerung haben?", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Ein Versuch einer Forschungsarbeit über die Verwendung von Basiliskenteilen als Reagenzien. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\"" }
entries[213168] = { ["name"] = "Kupferblutmünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Transmutiert 100 Kupferblutmünzen in 1 Silberblutmünze.\n\"Ein Zeichen für Eure bescheidenen Dienste für den Blutloa.\"" }
entries[213169] = { ["name"] = "Silberblutmünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Transmutiert 100 Silberblutmünzen in 1 Goldblutmünze.\n\"Ein Zeichen für Eure Dienste für den Blutloa.\"" }
entries[213170] = { ["name"] = "Goldblutmünze", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Symbol Eurer herausragenden Dienste für den Blutloa.\"" }
entries[213278] = { ["name"] = "Handschützer des Pömpfmeisters", ["text"] = "Wird beim Aufheben gebunden\nHände Leder\n84 Rüstung\n+10 Beweglichkeit\n+11 Ausdauer\nHaltbarkeit 35 / 35\nBenötigt Stufe 40\nAnlegen: Erhöht Faustwaffen um +3.\nAnlegen: Streitkolben +3." }
entries[213279] = { ["name"] = "Reflektierende Schädelkappe", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n222 Rüstung\n+11 Ausdauer\n+13 Intelligenz\n+8 Willenskraft\nHaltbarkeit 70 / 70\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 13." }
entries[213280] = { ["name"] = "Schützensuchervisier", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n222 Rüstung\n+9 Beweglichkeit\n+13 Ausdauer\n+8 Intelligenz\nHaltbarkeit 70 / 70\nBenötigt Stufe 40\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%." }
entries[213281] = { ["name"] = "Elektromagnetischer Hyperflux-Reaktivator", ["text"] = "Wird beim Aufheben gebunden\nKopf Stoff\n55 Rüstung\n+15 Intelligenz\n+12 Willenskraft\nHaltbarkeit 50 / 50\nBenötigt Stufe 40\nBenutzen: Kanalisiert einen Blitzschlag, schleudert ihn auf alle Feinde vor dem Zaubernden und fügt dabei 152 bis 172 Punkt(e) Naturschaden zu. Der Zaubernde ist danach 10 Minuten lang von einer Barriere aus Elektrizität umgeben. (30 Min Abklingzeit)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 16." }
entries[213282] = { ["name"] = "Hochaufgeladene Ausrüstung der Innovation", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Hypercharged Gear] (1)\nFinger\n+5 Intelligenz\n+8 Willenskraft\n+5 Arkanwiderstand\n+5 Naturwiderstand\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 13.\nAnlegen: Stellt alle 5 Sek. 3 Punkt(e) Mana wieder her." }
entries[213283] = { ["name"] = "Hochaufgeladene Ausrüstung der Feuersbrunst", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Hypercharged Gear] (1)\nFinger\n+4 Intelligenz\n+5 Arkanwiderstand\n+5 Naturwiderstand\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 11.\nAnlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her." }
entries[213284] = { ["name"] = "Hochaufgeladene Ausrüstung der Verwüstung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Hypercharged Gear] (1)\nFinger\n+7 Stärke\n+8 Beweglichkeit\n+10 Ausdauer\n+5 Arkanwiderstand\n+5 Naturwiderstand\nBenötigt Stufe 40" }
