entries[213286] = { ["name"] = "Elektrokutor-Nadel", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand Schwert\n41 - 75 Schaden Tempo 1.70\n(34.12 Schaden pro Sekunde)\nHaltbarkeit 105 / 105\nBenötigt Stufe 40\nTrefferchance: Entlädt einen Donnerschlag, der 25 bis 35 Naturschaden verursacht." }
entries[213287] = { ["name"] = "Elektrokutor-Sechskantmutter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n+6 Ausdauer\n+9 Willenskraft\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 8." }
entries[213288] = { ["name"] = "Grubbis schmierige Stulpen", ["text"] = "Wird beim Aufheben gebunden\nHände Platte\n300 Rüstung\n+9 Stärke\n+5 Ausdauer\nHaltbarkeit 45 / 45\nBenötigt Stufe 40\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%." }
entries[213289] = { ["name"] = "Hydrostab", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n78 - 117 Schaden Tempo 2.80\n(34.82 Schaden pro Sekunde)\n+23 Frostwiderstand\nHaltbarkeit 100 / 100\nBenötigt Stufe 40\nAnlegen: Ermöglicht Unterwasseratmung." }
entries[213290] = { ["name"] = "Säurewatstiefel", ["text"] = "Wird beim Aufheben gebunden\nFüße Stoff\n45 Rüstung\n+10 Intelligenz\n+5 Willenskraft\n+5 Naturwiderstand\nHaltbarkeit 40 / 40\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 11." }
entries[213291] = { ["name"] = "Toxinvergelter II", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nEinhändig Dolch\n43 - 80 Schaden Tempo 1.80\n(34.17 Schaden pro Sekunde)\nHaltbarkeit 80 / 80\nBenötigt Stufe 40\nTrefferchance: Fügt allen Gegnern in einem Radius von 8 Metern um den Zaubernden 15 Sek. lang alle 5 Sek. 30 Naturschaden zu." }
entries[213292] = { ["name"] = "Gizmotronisches Gigahackbeil", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Schwert\n102 - 153 Schaden Tempo 3.20\n(39.84 Schaden pro Sekunde)\n+22 Stärke\n+9 Beweglichkeit\nHaltbarkeit 100 / 100\nBenötigt Stufe 40" }
entries[213293] = { ["name"] = "Hightech-Superschusswaffe V7", ["text"] = "Wird beim Aufheben gebunden\nDistanz Schusswaffe\n38 - 71 Schaden Tempo 2.30\n(23.70 Schaden pro Sekunde)\n+4 Ausdauer\n+ 12 Angriffskraft.\nHaltbarkeit 75 / 75\nBenötigt Stufe 40" }
entries[213294] = { ["name"] = "Sabatons der Tiefentroggs", ["text"] = "Wird beim Aufheben gebunden\nFüße Platte\n330 Rüstung\n+7 Stärke\n+9 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 65 / 65\nBenötigt Stufe 40\nAnlegen: Verteidigung +4." }
entries[213295] = { ["name"] = "Ultraschallvibroklinge", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Axt\n49 - 91 Schaden Tempo 2.30\n(30.43 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\nBenötigt Stufe 40\nTrefferchance: Durchsticht die Rüstung des Ziels und verringert sie um 160." }
entries[213296] = { ["name"] = "Überladener Kopffäller", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Axt\n89 - 133 Schaden Tempo 2.80\n(39.64 Schaden pro Sekunde)\n+13 Stärke\n+12 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Stufe 40\nTrefferchance: Trifft ein Ziel mit 80 bis 100 Naturschaden." }
entries[213297] = { ["name"] = "Oszillierender Sprenghammer", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n52 - 94 Schaden Tempo 2.40\n(30.42 Schaden pro Sekunde)\n+5 Stärke\n+7 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 40\nAnlegen: Verteidigung +4." }
entries[213298] = { ["name"] = "Overall des Robobauers", ["text"] = "Wird beim Aufheben gebunden\nBrust Stoff\n185 Rüstung\n+6 Beweglichkeit\n+14 Ausdauer\n+12 Intelligenz\nHaltbarkeit 85 / 85\nBenötigt Stufe 40" }
entries[213299] = { ["name"] = "Petroleumpfützenhose", ["text"] = "Wird beim Aufheben gebunden\nBeine Leder\n117 Rüstung\n<Zufällige Verzauberung>\n+21 Beweglichkeit\n+11 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 40\n\"Von Feuer fernhalten.\"" }
entries[213300] = { ["name"] = "Kämpferasshandschuhe", ["text"] = "Wird beim Aufheben gebunden\nHände Stoff\n111 Rüstung\n+6 Ausdauer\n+10 Intelligenz\nHaltbarkeit 30 / 30\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 9." }
entries[213301] = { ["name"] = "Synthetischer Mantel", ["text"] = "Wird beim Aufheben gebunden\nSchulter Stoff\n99 Rüstung\n+8 Ausdauer\n+9 Intelligenz\nHaltbarkeit 50 / 50\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12." }
entries[213302] = { ["name"] = "Mantel des raffinierten Verhandlers", ["text"] = "Wird beim Aufheben gebunden\nSchulter Leder\n100 Rüstung\n+14 Beweglichkeit\n+11 Ausdauer\nHaltbarkeit 60 / 60\nBenötigt Stufe 40" }
entries[213303] = { ["name"] = "Blitzableiterschiftung", ["text"] = "Wird beim Aufheben gebunden\nSchulter Kette\n205 Rüstung\n+7 Intelligenz\nHaltbarkeit 70 / 70\nBenötigt Stufe 40\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: Erhöht durch Naturzauber und Natureffekte zugefügten Schaden um bis zu 17." }
entries[213304] = { ["name"] = "Troggtöterschulterstücke", ["text"] = "Wird beim Aufheben gebunden\nSchulter Kette\n205 Rüstung\n+12 Beweglichkeit\n+5 Intelligenz\nHaltbarkeit 70 / 70\nBenötigt Stufe 40\nAnlegen: +22 Angriffskraft." }
entries[213305] = { ["name"] = "Schulterplatten aus bearbeiteter Legierung", ["text"] = "Wird beim Aufheben gebunden\nSchulter Platte\n410 Rüstung\n+12 Stärke\n+11 Ausdauer\nHaltbarkeit 80 / 80\nBenötigt Stufe 40" }
entries[213306] = { ["name"] = "Bedeckung des Einfallsreichtums", ["text"] = "Wird beim Aufheben gebunden\nRücken\n32 Rüstung\n+4 Ausdauer\n+9 Intelligenz\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 9." }
entries[213307] = { ["name"] = "Tuch des Zerlegens", ["text"] = "Wird beim Aufheben gebunden\nRücken\n32 Rüstung\n+8 Stärke\n+6 Beweglichkeit\n+7 Ausdauer\nBenötigt Stufe 40" }
entries[213308] = { ["name"] = "Fallschirmumhang-Prototyp", ["text"] = "Wird beim Aufheben gebunden\nRücken\n32 Rüstung\n+12 Beweglichkeit\n+4 Ausdauer\nBenötigt Stufe 40\nBenutzen: Reduziert 10 Sek. lang Euer Falltempo. (30 Min Abklingzeit)\n\"Dieser Umhang ist fantastisch gearbeitet. Er wird an Euch hervorragend aussehen, bis es zur unvermeidlichen Fehlfunktion kommt und er in Flammen aufgeht.\"" }
entries[213309] = { ["name"] = "Umhang des Erfindungsreichtums", ["text"] = "Wird beim Aufheben gebunden\nRücken\n32 Rüstung\n+7 Intelligenz\n+6 Willenskraft\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 15.\nAnlegen: Stellt alle 5 Sek. 2 Punkt(e) Mana wieder her." }
entries[213310] = { ["name"] = "Hyperleitendes Schimmerhemd", ["text"] = "Wird beim Aufheben gebunden\nBrust Stoff\n65 Rüstung\n+6 Ausdauer\n+10 Willenskraft\nHaltbarkeit 80 / 80\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 29.\nAnlegen: Stellt alle 5 Sek. 6 Punkt(e) Mana wieder her.\n\nHyperleitende Heilermeditation (0/3)\nHyperleitendes Schimmerhemd\nHyperleitende Pantalons\nHyperleitende Sandalen\n(2) Set : +14 Willenskraft.\n(3) Set : Stellt alle 5 Sek. 7 Punkt(e) Mana wieder her." }
entries[213311] = { ["name"] = "Hyperleitende Robe", ["text"] = "Wird beim Aufheben gebunden\nBrust Stoff\n145 Rüstung\n+10 Ausdauer\n+11 Intelligenz\nHaltbarkeit 80 / 80\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 18.\n\nHyperleitende Zaubererkleidung (0/3)\nHyperleitende Robe\nHyperleitende Laufschuhe\nHyperleitender Rock\n(2) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n(2) Set : +100 Rüstung.\n(3) Set : Beim Wirken eines Zaubers besteht die Chance, dass Euer Schaden und Eure Heilung 10 Sek. lang um bis zu 40 erhöht werden. (Procchance: 10%)" }
