entries[213376] = { ["name"] = "Echtsilberplatten mit geringer Grundstrahlung" }
entries[213378] = { ["name"] = "Instabiler Mikrofaden", ["text"] = "Wird beim Aufheben gebunden\n\"Ein geschickter Schneider könnte daraus etwas Nützliches herstellen.\"" }
