entries[213390] = { ["name"] = "Wirbelnder Echtsilberzahnradschild", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Schild\n1760 Rüstung\n29 Blocken\n+9 Stärke\n+10 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 40\nBenötigt Ingenieurskunst (225)\nAnlegen: Erhöht Eure Chance, Angriffe mit einem Schild zu blocken, um 1%.\nAnlegen: Bei erfolgreichem Blocken fügen die wirbelnden rasiermesserscharfen Zahnräder dieses Schilds dem Angreifer 5 bis 10 körperlichen Schaden und dem Träger 2 bis 10 körperlichen Schaden zu.\n\"Die rotierenden Schneiden dieses Schilds sind überraschend scharfkantig. Er wirkt genauso gefährlich für den Träger wie für den Angreifer.\"" }
entries[213391] = { ["name"] = "UNBENUTZTE elektrifizierte Mithrilstulpen", ["text"] = "Wird beim Aufheben gebunden\nHände Platte\n300 Rüstung\n+16 Stärke\n+7 Ausdauer\nHaltbarkeit 45 / 45\nBenötigt Stufe 40" }
entries[213407] = { ["name"] = "Katzenminze", ["text"] = "Klassen: Druide\nBenötigt Stufe 20\nBenutzen: Erhöht Euer Angriffstempo 30 Sek. lang um 50%. (3 Min Abklingzeit)\n\"Ursprünglich von Ristell Klaue kultiviert, um die Druiden der Klaue vor dem Kampf anzustacheln.\"" }
entries[213408] = { ["name"] = "Gyromatischer Makroregler", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stangenwaffe\n101 - 152 Schaden Tempo 3.20\n(39.53 Schaden pro Sekunde)\n+15 Beweglichkeit\n+9 Ausdauer\n+15 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Stufe 40" }
entries[213409] = { ["name"] = "Mekkatorques Arkanoschredder", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand Faustwaffe\n62 - 115 Schaden Tempo 2.60\n(34.04 Schaden pro Sekunde)\n+2 Stärke\n+3 Beweglichkeit\nHaltbarkeit 80 / 80\nBenötigt Stufe 40\nTrefferchance: Entlädt eine Explosion arkaner Energie, die 30 Arkanschaden verursacht, sämtliche Widerstände um 45 verringert und sämtlichen erlittenen Zauberschaden 20 Sek. lang um 6% erhöht. Wirkt nur bei Gegnern der Stufe 45 oder niedriger." }
entries[213410] = { ["name"] = "Gleißende Dingsdaklinge", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand Dolch\n20 - 41 Schaden Tempo 1.20\n(25.42 Schaden pro Sekunde)\n70 Rüstung\n+7 Ausdauer\n+4 Intelligenz\nHaltbarkeit 80 / 80\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 19." }
entries[213411] = { ["name"] = "Izzleflicks unlöschbarer Anzünder", ["text"] = "Wird beim Aufheben gebunden\nDistanz Zauberstab\n59 - 110 Feuerschaden Tempo 2.00\n(42.25 Schaden pro Sekunde)\n+8 Intelligenz\nHaltbarkeit 65 / 65\nBenötigt Stufe 40\n\"Jetzt sicher lagerbar!\"" }
entries[213412] = { ["name"] = "Dielektrischer Sicherheitsschild", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Schild\n1760 Rüstung\n29 Blocken\n+9 Intelligenz\nHaltbarkeit 120 / 120\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 22.\nAnlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her." }
entries[213413] = { ["name"] = "Großzügig gefütterte Schulterpolster", ["text"] = "Wird beim Aufheben gebunden\nSchulter Leder\n100 Rüstung\n+8 Intelligenz\n+14 Willenskraft\nHaltbarkeit 50 / 50\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 11." }
entries[213414] = { ["name"] = "Schärpe des Mechheilers", ["text"] = "Wird beim Aufheben gebunden\nTaille Stoff\n37 Rüstung\n+6 Intelligenz\n+6 Willenskraft\nHaltbarkeit 30 / 30\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 24.\nAnlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her." }
entries[213415] = { ["name"] = "Handgelenkwickel des Tüftlers", ["text"] = "Wird beim Aufheben gebunden\nHandgelenke Stoff\n28 Rüstung\n+6 Intelligenz\n+7 Willenskraft\nHaltbarkeit 30 / 30\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 18." }
entries[213416] = { ["name"] = "Thermapluggs Raketenspaltbeil", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Axt\n117 - 175 Schaden Tempo 3.30\n(44.24 Schaden pro Sekunde)\n+29 Stärke\n+12 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 40" }
entries[213417] = { ["name"] = "Echtsilberfadenkappe", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n390 Rüstung\n+8 Ausdauer\n+12 Intelligenz\nHaltbarkeit 80 / 80\nBenötigt Stufe 40\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Stellt alle 5 Sek. 5 Punkt(e) Mana wieder her." }
entries[213418] = { ["name"] = "Geschweißte Echtsilberlocken", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nHandgelenke Platte\n210 Rüstung\n+6 Ausdauer\n+5 Intelligenz\nHaltbarkeit 45 / 45\nBenötigt Stufe 40\nAnlegen: Erhöht durch Heiligzauber und Heiligeffekte zugefügten Schaden um bis zu 14." }
entries[213419] = { ["name"] = "9-60-Reparaturhandbuch", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+6 Ausdauer\n+6 Intelligenz\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 22." }
