entries[213422] = { ["name"] = "Unleserliches Rezept", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest." }
entries[213426] = { ["name"] = "Ogerblitzschlagrute", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: In weicher Erde aufstellen." }
