entries[213442] = { ["name"] = "Klaue des Zahnradmeisters", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Faustwaffe\n60 - 111 Schaden Tempo 2.80\n(30.54 Schaden pro Sekunde)\n+6 Stärke\n+6 Beweglichkeit\n+5 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 40" }
