entries[213444] = { ["name"] = "Matte Gebetsperle I", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Mögen jene, die sich gegen uns wenden, unsere Macht zu spüren bekommen.\"" }
entries[213445] = { ["name"] = "Matte Gebetsperle II", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Möge das Licht uns schützen, wenn wir verwundet sind.\"" }
entries[213446] = { ["name"] = "Matte Gebetsperle III", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Mögen die Frevler und Feiglinge zur Rechenschaft gezogen werden.\"" }
entries[213447] = { ["name"] = "Gebetsperlenkranz des Lichts", ["text"] = "Wird beim Aufheben gebunden\n\"Wird von Mitgliedern der Kirche des Heiligen Lichts oft in Gebeten verwendet.\"" }
entries[213448] = { ["name"] = "Göttliche Gebetsperle I", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert drei göttliche Gebetsperlen, um einen Gebetsperlenkranz herzustellen." }
entries[213449] = { ["name"] = "Göttliche Gebetsperle II", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert drei göttliche Gebetsperlen, um einen Gebetsperlenkranz herzustellen." }
entries[213450] = { ["name"] = "Göttliche Gebetsperle III", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert drei göttliche Gebetsperlen, um einen Gebetsperlenkranz herzustellen." }
entries[213451] = { ["name"] = "Verderbtes Feuertotem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Befleckt durch den Einfluss der Burning Blade ist dieses Totem knorrig, geschwärzt und vernarbt, und doch könnt Ihr das Element darin spüren. Jemand anderes wird über diese Entdeckung sicherlich genauso besorgt sein wie Ihr.\"" }
entries[213452] = { ["name"] = "Inaktive heilige Rune", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n\"Zunächst müsst Ihr Euer Leben für jemand anderes geben. Und dann, bevor Euer Geist loslässt, soll es Euch auf gleiche Weise vergolten werden.\"" }
entries[213513] = { ["name"] = "Buchband der Erlösung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Buchband\nKlassen: Paladin\nBenötigt Stufe 18\nPrägt Eure Stiefel mit der Rune 'Geheiligter Schild':\n\nJedes Mal, wenn das Ziel Schaden erleidet, wird es von einem geheiligten Schild umhüllt, der [Quellwert] Schaden absorbiert und die Chance des Paladins, mit 'Lichtblitz' einen kritischen Treffer zu erzielen, bis zu 6 Sek. lang um 50% erhöht. Zusätzlich heilen Eure Einsätze von 'Lichtblitz' Ziele mit 'Geheiligter Schild' im Verlauf von 12 Sek. um weitere 100% Gesundheit. Dieser Effekt kann nur einmal alle 6 Sek. auftreten. Hält 1 Min. lang an. Es kann immer nur jeweils ein Ziel mit diesem Zauber belegt sein.\n\"Erlernt eine neue Fähigkeit, nachdem Ihr 5-mal 'Segen der Freiheit' eingesetzt habt, um andere Charaktere von bewegungseinschränkenden Effekten zu befreien.\"", ["unresolvedValues"] = true }
entries[213526] = { ["name"] = "Hybride Keule", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Schmeckt wie Rind *und* Hühnchen.\"" }
entries[213527] = { ["name"] = "Gewürzmischung des Schmugglers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Das Kronjuwel in jeder Kombüse. Könnte sogar einem Stiefel Wohlgeschmack verleihen.\"" }
entries[213528] = { ["name"] = "Mildes Gebräu", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Nicht das, was man unter einem \"Kühlen Blonden\" versteht.\"" }
entries[213529] = { ["name"] = "Viskoses Gift", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Frisst sich problemlos durch Sumpfkreaturen. Fantastisch für Marinaden.\"" }
entries[213542] = { ["name"] = "Das Nekro-Gnomikon", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+2 Intelligenz\n+2 Willenskraft\n+3 Schattenwiderstand\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 14." }
entries[213543] = { ["name"] = "Schriftrolle: UPDOG", ["text"] = "Klassen: Magier\nBenutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält." }
entries[213544] = { ["name"] = "Schriftrolle: TOPAZ YORAK", ["text"] = "Klassen: Magier\nBenutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält." }
entries[213545] = { ["name"] = "Schriftrolle: ZAEHLEZ STARKDEUTIEN", ["text"] = "Klassen: Magier\nBenutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält." }
entries[213546] = { ["name"] = "Schriftrolle: SCHUBIDU", ["text"] = "Klassen: Magier\nBenutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält." }
