entries[213548] = { ["name"] = "Schriftrolle des Schwellenübergangs", ["text"] = "Klassen: Magier\nBenötigt Stufe 6\nBenutzen: Teleportiert zu einem Gruppenmitglied. Ihr und das Ziel müsst in einem Gasthaus oder einer Stadt rasten." }
entries[213549] = { ["name"] = "Schriftrolle des arkanen Angelns", ["text"] = "Klassen: Magier\nBenötigt Stufe 12" }
entries[213550] = { ["name"] = "Schriftrolle der Verwandlung: Seltsame Melone", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 16\nBenutzen: Verwandelt das Ziel in eine seltsame Melone. (5 Sek. Abklingzeit)" }
entries[213551] = { ["name"] = "Schriftrolle der kontrollierten Verzerrung", ["text"] = "Klassen: Magier\nBenötigt Stufe 12" }
entries[213552] = { ["name"] = "Träne von Theradras", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Diese werden vom Zentaurenstamm der Gelkis gehortet und streng bewacht und es heißt, sie würden dem Nutzer den Schutz der irdenen Geister gewähren.\"" }
entries[213553] = { ["name"] = "Träne von Theradras", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Diese werden vom Zentaurenstamm der Gelkis gehortet und streng bewacht und es heißt, sie würden dem Nutzer den Schutz der irdenen Geister gewähren.\"" }
entries[213554] = { ["name"] = "Phiole mit Kristallwasser", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Mit den Tränen von Theradras mischen, um eine Elementarsalbe herzustellen, die Verderbnis läutern kann.\n\"Das Wasser ist so kristallklar, dass die Phiole leer erscheint.\"" }
entries[213558] = { ["name"] = "Elementarsalbe", ["text"] = "Benutzen: Über verderbte Objekte gießen, um sie zu läutern.\n\"Eine wirkungsvolle Salbe, die tiefsitzende Verderbnis läutern kann.\"" }
entries[213559] = { ["name"] = "Roboschreiterkuppler", ["text"] = "Wird beim Aufheben gebunden\nDistanz Zauberstab\n44 - 83 Arkanschaden Tempo 1.50\n(42.33 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 9.\n\"Dieser Gegenstand setzt die Existenz von Roboschreitern mit Schaltgetriebe voraus.\"" }
entries[213560] = { ["name"] = "Roboschreiterdämpfer", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n51 - 95 Schaden Tempo 2.40\n(30.42 Schaden pro Sekunde)\n+7 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 40\nAnlegen: +16 Angriffskraft." }
entries[213562] = { ["name"] = "Insektenfangnetz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fangt ein exotisches Insekt und behaltet es als Versuchsobjekt. (30 Sek. Abklingzeit)" }
entries[213563] = { ["name"] = "Leitfaden", ["text"] = "Wird beim Aufheben gebunden\n<Zum Lesen rechtsklicken>" }
entries[213564] = { ["name"] = "Schriftrolle der geringeren Hervorrufung", ["text"] = "Klassen: Magier\nBenutzen: Stellt Mana wieder her. (8 Min Abklingzeit)" }
