entries[213566] = { ["name"] = "Versuchsobjekt: Laubengangtarantel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[213567] = { ["name"] = "Versuchsobjekt: Fleischpflücker", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[213568] = { ["name"] = "Versuchsobjekt: Heurüsselkäfer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[213572] = { ["name"] = "Seele der Leere", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Reine Leerenenergie.\"" }
entries[213573] = { ["name"] = "Amulett des Herbeizauberers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Kombiniert 10 Amulette des Herbeizauberers und eine Seele der Leere in der Nähe eines Leerenprismas." }
entries[213574] = { ["name"] = "Ausgetrocknete Samenkapsel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Muss rehydriert werden, bevor sie eingepflanzt werden kann.\"" }
entries[213583] = { ["name"] = "Schwefelschnitzerei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Es scheint, als hätte der vorherige Besitzer etwas zu häufig mit Feuer gespielt.\"" }
entries[213594] = { ["name"] = "Götze der Zwischenrufe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Götze\nKlassen: Druide\nBenötigt Stufe 28\nPrägt Euren Gürtel mit der Rune 'Berserker':\n\nWenn aktiviert, lässt diese Fähigkeit 'Zerfleischen (Bär)' und 'Aufschlitzen' bis zu 3 Ziele treffen. 'Aufschlitzen' kostet keine Wut und 'Zerfleischen (Bär)' unterliegt keiner Abklingzeit. In Katzengestalt werden die Energiekosten aller Eurer Fähigkeiten um 50% verringert. Hält 15 Sek. lang an. Erfordert Katzengestalt, Bärengestalt oder Terrorbärengestalt.\n\nEntfernt sofort Furchteffekte und macht Euch während seiner Dauer gegen sie immun.\n\"Verspottet 2 oder mehr Gegner mit 'Herausforderndes Gebrüll' und tötet mindestens einen der beiden. Setzt nach 3 Siegen diesen Götzen ein, um eine neue Fähigkeit zu erlernen.\"" }
entries[213599] = { ["name"] = "Beunruhigende Vision", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Euren Gürtel mit der Rune 'Erneuerte Hoffnung':\n\nErhöht die Effekte Eurer Einsätze von 'Blitzheilung', 'Geringe Heilung', 'Heilung', 'Große Heilung' und 'Sühne' um 20%, wenn Ihr sie auf Ziele anwendet, die mit 'Geschwächte Seele' belegt sind.\nBenutzen: Konzentriert Euch auf die Vision, um einen neuen Zauber zu lernen. Erfordert einen Blick auf verderbtes Wissen." }
entries[213632] = { ["name"] = "Unvollständige Zaubernotizen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenutzen: Kombiniert alle gesammelten unvollständigen Zaubernotizen zu einer Schriftrolle, die Euch einen neuen Runenschnitzenzauber lehrt.\n\"Eine lückenhafte Seite, die den Schriftrollen zu ähneln scheint, die Runenschnitzenfähigkeiten lehren. Zwei Drittel fehlen.\"" }
entries[213633] = { ["name"] = "Unvollständige Zaubernotizen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenutzen: Kombiniert alle gesammelten unvollständigen Zaubernotizen zu einer Schriftrolle, die Euch einen neuen Runenschnitzenzauber lehrt.\n\"Eine lückenhafte Seite, die den Schriftrollen zu ähneln scheint, die Runenschnitzenfähigkeiten lehren. Zwei Drittel fehlen.\"" }
entries[213634] = { ["name"] = "Unvollständige Zaubernotizen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenutzen: Kombiniert alle gesammelten unvollständigen Zaubernotizen zu einer Schriftrolle, die Euch einen neuen Runenschnitzenzauber lehrt.\n\"Eine lückenhafte Seite, die den Schriftrollen zu ähneln scheint, die Runenschnitzenfähigkeiten lehren. Zwei Drittel fehlen.\"" }
entries[213641] = { ["name"] = "Kiste mit Bergungsgut aus Gnomeregan", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Kiste mit Bergungsgut aus Gnomeregan könnte etwas enthalten, was Euch in Eurem Beruf nützt.\"\n<Zum Öffnen rechtsklicken>" }
entries[213701] = { ["name"] = "Kräftige Harpyienfeder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Kombiniert 10 kräftige Harpyienfedern und 3 Wolkenschlangenfangzähne mit einem Seidenfaden, um eine Opfergabe für den Windgeist herzustellen." }
entries[213709] = { ["name"] = "Wolkenschlangenreißzahn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (3)\nBenutzen: Kombiniert 10 kräftige Harpyienfedern und 3 Wolkenschlangenfangzähne mit einem Seidenfaden, um eine Opfergabe für den Windgeist herzustellen." }
entries[213735] = { ["name"] = "Makelloser G-7-K.E.R.N.-Prozessor", ["text"] = "Wird beim Aufheben gebunden\n\"Dieses Ding kann über 4 Millionen Gigaflops an relationalen Codebündeln niedriger Varianz vorberechnen. Wow!\"" }
entries[213736] = { ["name"] = "Korrodierter G-7-K.E.R.N.-Prozessor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Dieser Prozessorkern ist voller verkrusteter Korrosionsrückstände und überzogen mit einer klebrigen schwarzen Substanz. Eine Modellnummer und ein paar unleserliche Worte lassen sich wegen der zähen Masse kaum noch entziffern. Ihr werdet wohl einen Spezialisten brauchen, um ihn wieder auf Vordermann zu bringen.\"" }
entries[213737] = { ["name"] = "Opfergabe für den Windgeist", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bringt dem Windgeist eine Opfergabe dar und beweist Euren Glauben." }
entries[214435] = { ["name"] = "Schlüssel zum Pumakäfig", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenutzen: Öffnet den Pumakäfig." }
entries[215111] = { ["name"] = "Gneuro-verkettetes Arkanfaden-Monokel", ["text"] = "Wird beim Aufheben gebunden\nKopf Stoff\n58 Rüstung\n+10 Ausdauer\n+11 Intelligenz\nHaltbarkeit 60 / 60\nBenötigt Stufe 40\nBenötigt Schneiderei (225)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 22.\nAnlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her.\nBenutzen: Ihr macht Euch die latente Arkanenergie in der Umgebungsluft zunutze und erhaltet 'Aufgeladene Inspiration', was 12 Sek. lang die Manakosten aller Zauber um 50% verringert und ihren verursachten Schaden und die durch sie hervorgerufene Heilung um bis zu 50 erhöht. (10 Min Abklingzeit)" }
entries[215114] = { ["name"] = "Leuchtende hyperleitende Schuppenkappe", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n242 Rüstung\n+14 Ausdauer\n+15 Intelligenz\nHaltbarkeit 85 / 85\nBenötigt Stufe 40\nBenötigt Lederverarbeitung (225)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\nBenutzen: Belegt Euch mit 'Hyperleitender Schock', was Euch sofort 312 bis 688 Schaden zufügt, aber auch Euer Zauberwirken 10 Sek. lang um 20% beschleunigt. (10 Min Abklingzeit)" }
entries[215115] = { ["name"] = "Hyperleitendes Goldnetz", ["text"] = "Wird beim Aufheben gebunden\nTaille Stoff\n40 Rüstung\n+9 Ausdauer\nHaltbarkeit 35 / 35\nBenötigt Stufe 40\nBenötigt Ingenieurskunst (225)\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nBenutzen: Ihr zieht eine hyperleitende Münze aus Eurem Gürtel und werft sie hoch. Kopf: Erhöht Eure kritische Trefferchance mit allen Zaubern und Angriffen 30 Sek. lang um 3%. Zahl: Erhöht Eure Bewegungsgeschwindigkeit 30 Sek. lang um 10%. (15 Min Abklingzeit)\n\"Dieser Gürtel klickt leise, während Ihr Euch bewegt.\"" }
entries[215127] = { ["name"] = "Hoch wirksame Strahlungsbombe", ["text"] = "Benötigt Stufe 35\nBenötigt Ingenieurskunst (200)\nBenutzen: Verursacht im Explosionsradius 150 bis 250 Feuerschaden und zusätzlich 10 Sek. lang alle 2 Sek. 25 Naturschaden. Verringert außerdem die Bewegungsgeschwindigkeit von betroffenen Zielen bis Abbruch lang um 25%. (1 Min Abklingzeit)" }
entries[215129] = { ["name"] = "Formel: Waffe - Zerlegen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (225)\nBenutzen: Eine Waffe dauerhaft verzaubern, sodass alle Zauber und Angriffe mechanischen Kreaturen manchmal 60 bis 90 zusätzlichen Schaden zufügen." }
entries[215138] = { ["name"] = "Formel: Brust - Vergelter", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (225)\nBenutzen: Lehrt Euch, wie man eine Brustrüstung dauerhaft so verzaubert, dass sie bei eingehenden Nahkampfangriffen 9 Schaden auf den Angreifer zurückwirft." }
entries[215141] = { ["name"] = "Verzaubertes Siegel: Innovation", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (225)\nBenutzen: Lehrt Euch, wie man ein Siegel der Innovation beschwört.\nVerzaubertes Siegel: Innovation\nWird beim Aufheben gebunden\nEinzigartig (5)\nBenötigt Stufe 40\nBenötigt Verzauberkunst (225)\nBenutzen: Erhaltet ein verzaubertes Siegel der Innovation, das Euch ermächtigt, wodurch 30 Min. lang der verursachte Schaden und die hervorgerufene Heilung Eurer Zauber um bis zu 20 und Eure Angriffskraft um 20 erhöht wird. Dieser Effekt kann nur außerhalb des Kampfes angewandt werden. (30 Min Abklingzeit)\nBenötigt Visionenstaub (5)" }
entries[215149] = { ["name"] = "Muster: Gneuro-verkettetes Arkanfaden-Monokel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (225)\nBenutzen: Lehrt Euch, wie man ein Gneuro-verkettetes Arkanfaden-Monokel herstellt.\nGneuro-verkettetes Arkanfaden-Monokel\nWird beim Aufheben gebunden\nKopf Stoff\n58 Rüstung\n+10 Ausdauer\n+11 Intelligenz\nHaltbarkeit 60 / 60\nBenötigt Stufe 40\nBenötigt Schneiderei (225)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 22.\nAnlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her.\nBenutzen: Ihr macht Euch die latente Arkanenergie in der Umgebungsluft zunutze und erhaltet 'Aufgeladene Inspiration', was 12 Sek. lang die Manakosten aller Zauber um 50% verringert und ihren verursachten Schaden und die durch sie hervorgerufene Heilung um bis zu 50 erhöht. (10 Min Abklingzeit)\nBenötigt Hyperleitender Arkanfaden (5), Schwach leuchtendes Leder , Isolierendes Gniodin , Visionenstaub (10), Magiestoffballen (10)" }
entries[215152] = { ["name"] = "Muster: Leuchtende Gneuro-verkettete Gugel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (225)\nBenutzen: Lehrt Euch, wie man eine leuchtende Gneuro-verkettete Gugel herstellt.\nLeuchtende Gneuro-verkettete Gugel\nWird beim Aufheben gebunden\nKopf Leder\n118 Rüstung\n+14 Beweglichkeit\n+14 Ausdauer\nHaltbarkeit 70 / 70\nBenötigt Stufe 40\nBenötigt Lederverarbeitung (225)\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: +3 Waffenschaden.\nBenutzen: Belegt Euch mit 'Gneurologischer Schock', was Euch sofort 343 bis 757 Schaden zufügt, aber auch Eure Nahkampf- und Distanzangriffe 10 Sek. lang um 20% beschleunigt. (10 Min Abklingzeit)\nBenötigt Hyperleitender Arkanfaden , Geschmeidiger dicker Balg (5), Seidenfaden (2), Schwach leuchtendes Leder (5)" }
entries[215153] = { ["name"] = "Bauplan: Wirbelnder Echtsilberzahnradschild", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (225)\nBenutzen: Lehrt Euch, wie man einen wirbelnden Echtsilberzahnradschild herstellt.\nWirbelnder Echtsilberzahnradschild\nWird beim Aufheben gebunden\nSchildhand Schild\n1760 Rüstung\n29 Blocken\n+9 Stärke\n+10 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 40\nBenötigt Ingenieurskunst (225)\nAnlegen: Erhöht Eure Chance, Angriffe mit einem Schild zu blocken, um 1%.\nAnlegen: Bei erfolgreichem Blocken fügen die wirbelnden rasiermesserscharfen Zahnräder dieses Schilds dem Angreifer 5 bis 10 körperlichen Schaden und dem Träger 2 bis 10 körperlichen Schaden zu.\n\"Die rotierenden Schneiden dieses Schilds sind überraschend scharfkantig. Er wirkt genauso gefährlich für den Träger wie für den Angreifer.\"\nBenötigt Echtsilberplatten mit geringer Grundstrahlung (3), Polierte Echtsilberzahnräder (5), Schwach leuchtendes Leder (2), Mithrilgehäuse (2), Gyrochronatom (2), Mithrilbarren (15)" }
entries[215155] = { ["name"] = "Pläne: Gehärteter Interferenzen-negierender Helm", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (225)\nBenutzen: Lehrt Euch, wie man einen gehärteten Interferenzen-negierenden Helm herstellt.\nGehärteter Interferenzen-negierender Helm\nWird beim Aufheben gebunden\nKopf Platte\n426 Rüstung\n+20 Stärke\n+14 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Stufe 40\nBenötigt Schmiedekunst (225)\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nBenutzen: Gewährt höchste Konzentration, die 10 Sek. lang die Bewegungsgeschwindigkeit um 20% verringert, aber währenddessen Euren Zauberwiderstand gegen alle Magiearten um 50 sowie das Angriffstempo im Nahkampf um 20% erhöht. (10 Min Abklingzeit)\n\"Schützt Euer Hirn garantiert vor allen Bedrohungen, physischen wie anderen!\"\nBenötigt Mithrilbarren (25), Echtsilberplatten mit geringer Grundstrahlung (4), Hyperleitender Arkanfaden , Schwach leuchtendes Leder (2)" }
entries[215156] = { ["name"] = "Bauplan: Hyperleitendes Goldnetz", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (225)\nBenutzen: Lehrt Euch, wie man ein hyperleitendes Goldnetz herstellt.\nHyperleitendes Goldnetz\nWird beim Aufheben gebunden\nTaille Stoff\n40 Rüstung\n+9 Ausdauer\nHaltbarkeit 35 / 35\nBenötigt Stufe 40\nBenötigt Ingenieurskunst (225)\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nBenutzen: Ihr zieht eine hyperleitende Münze aus Eurem Gürtel und werft sie hoch. Kopf: Erhöht Eure kritische Trefferchance mit allen Zaubern und Angriffen 30 Sek. lang um 3%. Zahl: Erhöht Eure Bewegungsgeschwindigkeit 30 Sek. lang um 10%. (15 Min Abklingzeit)\n\"Dieser Gürtel klickt leise, während Ihr Euch bewegt.\"\nBenötigt Polierte Echtsilberzahnräder (3), Hyperleitender Arkanfaden (3), Schwach leuchtendes Leder , Goldbarren (10)" }
entries[215161] = { ["name"] = "Gehärteter Interferenzen-negierender Helm", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n426 Rüstung\n+20 Stärke\n+14 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Stufe 40\nBenötigt Schmiedekunst (225)\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nBenutzen: Gewährt höchste Konzentration, die 10 Sek. lang die Bewegungsgeschwindigkeit um 20% verringert, aber währenddessen Euren Zauberwiderstand gegen alle Magiearten um 50 sowie das Angriffstempo im Nahkampf um 20% erhöht. (10 Min Abklingzeit)\n\"Schützt Euer Hirn garantiert vor allen Bedrohungen, physischen wie anderen!\"" }
entries[215162] = { ["name"] = "Leicht bestrahlter Verjüngungstrank", ["text"] = "Benötigt Stufe 35\nBenutzen: Stellt 262 bis 438 Mana und 340 bis 460 Gesundheit wieder her. Erhöht zudem 20 Sek. lang die Angriffskraft um 40 und den durch alle Zauber verursachten Schaden um 35. (2 Min Abklingzeit)\n\"Mögliche Nebenwirkungen: Schwindel, Mundtrockenheit, Erschöpfung, Appetitlosigkeit, akute Strahlenvergiftung, Mutation und Tod. Bei der Anwendung den Anweisungen folgen.\"" }
entries[215163] = { ["name"] = "Rezept: Leicht bestrahlter Verjüngungstrank", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchimie (225)\nBenutzen: Lehrt Euch, wie man einen leicht bestrahlten Verjüngungstrank aufbrüht.\nLeicht bestrahlter Verjüngungstrank\nBenötigt Stufe 35\nBenutzen: Stellt 262 bis 438 Mana und 340 bis 460 Gesundheit wieder her. Erhöht zudem 20 Sek. lang die Angriffskraft um 40 und den durch alle Zauber verursachten Schaden um 35. (2 Min Abklingzeit)\n\"Mögliche Nebenwirkungen: Schwindel, Mundtrockenheit, Erschöpfung, Appetitlosigkeit, akute Strahlenvergiftung, Mutation und Tod. Bei der Anwendung den Anweisungen folgen.\"\nBenötigt Kiste mit besudelter Gniodin-Lösung , Schwacher Verjüngungstrank , Ablagerung von Gnomeregan (3), Kristallphiole (5)" }
entries[215166] = { ["name"] = "Leuchtende Gneuro-verkettete Gugel", ["text"] = "Wird beim Aufheben gebunden\nKopf Leder\n118 Rüstung\n+14 Beweglichkeit\n+14 Ausdauer\nHaltbarkeit 70 / 70\nBenötigt Stufe 40\nBenötigt Lederverarbeitung (225)\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: +3 Waffenschaden.\nBenutzen: Belegt Euch mit 'Gneurologischer Schock', was Euch sofort 343 bis 757 Schaden zufügt, aber auch Eure Nahkampf- und Distanzangriffe 10 Sek. lang um 20% beschleunigt. (10 Min Abklingzeit)" }
entries[215167] = { ["name"] = "Reflektierender Echtsilbergehirnkäfig", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n426 Rüstung\n+14 Ausdauer\n+15 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Stufe 40\nBenötigt Schmiedekunst (225)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\nBenutzen: Gewährt verstärkte Willenskraft, die 10 Sek. lang Stille- und Unterbrechungseffekte sowie Zauberverzögerungen verhindert. (10 Min Abklingzeit)" }
entries[215168] = { ["name"] = "EZ-Thro-Strahlungsbombe", ["text"] = "Benötigt Stufe 40\nBenutzen: Verursacht im Explosionsradius 112 bis 188 Feuerschaden und zusätzlich 10 Sek. lang alle 2 Sek. 10 Naturschaden. Verringert außerdem die Bewegungsgeschwindigkeit von betroffenen Zielen 10 Sek. lang um 25%. (1 Min Abklingzeit)\n\"Eine abgeschwächte, aber nicht weniger tödliche Version ihres komplexeren Gegenstücks, für diejenigen, denen zwar die Kompetenz fehlt, die aber dafür Zuversicht im Überfluss haben.\"" }
entries[215257] = { ["name"] = "Schriftrolle des Verständnis", ["text"] = "Klassen: Magier\nBenutzen: Erschafft 2 Verständnisamulette, oder 4, wenn Ihr in einem Gasthaus oder einer Stadt rastet." }
entries[215365] = { ["name"] = "Mantel des Herbeirufers", ["text"] = "Wird beim Anlegen gebunden\nSchulter Stoff\n32 Rüstung\n+5 Intelligenz\nHaltbarkeit 45 / 45\nBenötigt Stufe 25\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 7." }
entries[215366] = { ["name"] = "Kordel des Herbeirufers", ["text"] = "Wird beim Anlegen gebunden\nTaille Stoff\n24 Rüstung\n+5 Intelligenz\nHaltbarkeit 25 / 25\nBenötigt Stufe 25\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 7." }
entries[215367] = { ["name"] = "Muster: Schwach leuchtendes Leder", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (200)\nBenutzen: Lehrt Euch, wie man ein Bündel schwach leuchtendes Leder herstellt.\nSchwach leuchtendes Leder\nBenötigt Geschmeidiger dicker Balg , Bestrahlte Lederfetzen (5)" }
entries[215368] = { ["name"] = "Muster: Hyperleitender Arkanfaden", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (200)\nBenutzen: Lehrt Euch, wie man einen hyperleitenden Arkanfaden herstellt.\nHyperleitender Arkanfaden\nBenötigt Magiestoffballen (2), Instabiler Mikrofaden (5), Schwerer Seidenfaden (5)" }
entries[215369] = { ["name"] = "Muster: Kordel des Herbeirufers", ["text"] = "Benötigt Schneiderei (150)\nBenutzen: Lehrt Euch, wie man die Kordel des Herbeirufers näht.\nKordel des Herbeirufers\nWird beim Anlegen gebunden\nTaille Stoff\n24 Rüstung\n+5 Intelligenz\nHaltbarkeit 25 / 25\nBenötigt Stufe 25\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 7.\nBenötigt Seidenstoffballen (3), Schattenedelstein , Feiner Faden , Grauer Farbstoff" }
entries[215370] = { ["name"] = "Muster: Mantel des Herbeirufers", ["text"] = "Benötigt Schneiderei (150)\nBenutzen: Lehrt Euch, wie man den Mantel des Herbeirufers näht.\nMantel des Herbeirufers\nWird beim Anlegen gebunden\nSchulter Stoff\n32 Rüstung\n+5 Intelligenz\nHaltbarkeit 45 / 45\nBenötigt Stufe 25\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 7.\nBenötigt Seidenstoffballen (4), Grauer Farbstoff (4), Feiner Faden , Blauer Farbstoff (4)" }
entries[215371] = { ["name"] = "Janis Amulett", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig\nSchmuck\nKlassen: Schurke" }
entries[215373] = { ["name"] = "Übungshammer der Silbernen Hand", ["text"] = "Zweihändig Streitkolben\n17 - 54 Schaden Tempo 3.40\n(10.44 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\nBenötigt Stufe 26\n\"Gefunden auf der Insel Theramore, wo sein Besitzer im Kampf gegen blutrünstige Orc-Horden fiel.\"" }
entries[215374] = { ["name"] = "Schwert der Ahnen", ["text"] = "Zweihändig Schwert\n17 - 46 Schaden Tempo 3.10\n(10.16 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\nBenötigt Stufe 26\n\"Ein Erbstück einer adligen Familie aus Lordaeron. Einst in den Sümpfen um Kyross verloren geglaubt, zusammen mit dem letzten Krieger, der es schwang.\"" }
entries[215375] = { ["name"] = "Stab es Taktikers", ["text"] = "Zweihändig Stab\n16 - 49 Schaden Tempo 3.50\n(9.29 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\nBenötigt Stufe 26\n\"Die scharfsinnige Auffassungsgabe der Besitzerin in Bezug auf Schlachtfeldtaktiken wurde nur übertroffen durch ihre furchteinflößende Beherrschung von Frost und Feuer.\"" }
entries[215376] = { ["name"] = "Streitkolben des Kreuzfahrers", ["text"] = "Waffenhand Streitkolben\n21 - 36 Schaden Tempo 2.90\n(9.83 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\nBenötigt Stufe 26\n\"Gesprenkelt mit getrockneten Resten von Insektenpanzern.\"" }
entries[215377] = { ["name"] = "Bestrahlte Robe", ["text"] = "Wird beim Aufheben gebunden\nBrust Stoff\n65 Rüstung\n-5 Stärke\n-10 Ausdauer\n+7 Intelligenz\n+8 Willenskraft\n+7 Naturwiderstand\nHaltbarkeit 80 / 80\nBenötigt Stufe 40\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 23.\n\nBestrahlte Gewänder (0/3)\nBestrahlte Robe\nBestrahlte Beinkleider\nBestrahlte Stiefel\n(2) Set : -5 Ausdauer.\n(2) Set : Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n(3) Set : Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 11." }
entries[215378] = { ["name"] = "Bestrahlte Stiefel", ["text"] = "Wird beim Aufheben gebunden\nFüße Stoff\n45 Rüstung\n-5 Beweglichkeit\n-10 Ausdauer\n+12 Intelligenz\n+11 Willenskraft\nHaltbarkeit 40 / 40\nBenötigt Stufe 40\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 11.\n\nBestrahlte Gewänder (0/3)\nBestrahlte Robe\nBestrahlte Beinkleider\nBestrahlte Stiefel\n(2) Set : -5 Ausdauer.\n(2) Set : Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n(3) Set : Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 11." }
entries[215379] = { ["name"] = "Bestrahlte Beinkleider", ["text"] = "Wird beim Aufheben gebunden\nBeine Stoff\n57 Rüstung\n-5 Beweglichkeit\n-10 Ausdauer\n+10 Intelligenz\n+13 Willenskraft\n+10 Naturwiderstand\nHaltbarkeit 75 / 75\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 16.\nAnlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her.\n\nBestrahlte Gewänder (0/3)\nBestrahlte Robe\nBestrahlte Beinkleider\nBestrahlte Stiefel\n(2) Set : -5 Ausdauer.\n(2) Set : Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n(3) Set : Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 11." }
