entries[215381] = { ["name"] = "Gneuro-leitende Kapuze des Kanalisierers", ["text"] = "Wird beim Aufheben gebunden\nKopf Leder\n118 Rüstung\n+11 Ausdauer\n+12 Intelligenz\n+11 Willenskraft\nHaltbarkeit 70 / 70\nBenötigt Stufe 40\nBenötigt Lederverarbeitung (225)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\nBenutzen: Gewährt 'Gneuromantische Meditation', wodurch 20 Sek. lang 100% Eurer Manaregeneration während des Zauberwirkens erhalten bleibt und der verursachte Schaden und die hervorgerufene Heilung Eurer Zauber um bis zu 50 erhöht werden. (10 Min Abklingzeit)" }
entries[215382] = { ["name"] = "Strahlungsresistente Schuppenkapuze", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n342 Rüstung\n+10 Ausdauer\n+10 Intelligenz\nHaltbarkeit 85 / 85\nBenötigt Stufe 40\nBenötigt Lederverarbeitung (225)\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: +32 Angriffskraft.\nBenutzen: Aktiviert die Protokolle zur Strahlungsabschwächung in diesem Helm, die sofort alle aktiven Gifteffekte von Euch entfernen und Euch 3 Sek. lang immun gegen jeglichen Naturschaden machen. (10 Min Abklingzeit)" }
entries[215383] = { ["name"] = "Pläne: Reflektierender Echtsilbergehirnkäfig", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (225)\nBenutzen: Lehrt Euch, wie man einen reflektierenden Echtsilbergehirnkäfig herstellt.\nReflektierender Echtsilbergehirnkäfig\nWird beim Aufheben gebunden\nKopf Platte\n426 Rüstung\n+14 Ausdauer\n+15 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Stufe 40\nBenötigt Schmiedekunst (225)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\nBenutzen: Gewährt verstärkte Willenskraft, die 10 Sek. lang Stille- und Unterbrechungseffekte sowie Zauberverzögerungen verhindert. (10 Min Abklingzeit)\nBenötigt Mithrilbarren (25), Echtsilberplatten mit geringer Grundstrahlung (4), Hyperleitender Arkanfaden (2), Polierte Echtsilberzahnräder" }
entries[215384] = { ["name"] = "Pläne: Echtsilberplatten mit geringer Grundstrahlung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (200)\nBenutzen: Lehrt Euch, wie man Echtsilberplatten mit geringer Grundstrahlung herstellt.\nEchtsilberplatten mit geringer Grundstrahlung\nBenötigt Echtsilberbarren , Reflektierender Metallschrott (5)" }
