entries[215422] = { ["name"] = "Muster: Leuchtende hyperleitende Schuppenkappe", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (225)\nBenutzen: Lehrt Euch, wie man eine leuchtende hyperleitende Schuppenkappe herstellt.\nLeuchtende hyperleitende Schuppenkappe\nWird beim Aufheben gebunden\nKopf Kette\n242 Rüstung\n+14 Ausdauer\n+15 Intelligenz\nHaltbarkeit 85 / 85\nBenötigt Stufe 40\nBenötigt Lederverarbeitung (225)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\nBenutzen: Belegt Euch mit 'Hyperleitender Schock', was Euch sofort 312 bis 688 Schaden zufügt, aber auch Euer Zauberwirken 10 Sek. lang um 20% beschleunigt. (10 Min Abklingzeit)\nBenötigt Echtsilberplatten mit geringer Grundstrahlung , Dicke Murlocschuppe (10), Schwach leuchtendes Leder (5), Isolierendes Gniodin" }
entries[215423] = { ["name"] = "Muster: Gneuro-leitende Kapuze des Kanalisierers", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (225)\nBenutzen: Lehrt Euch, wie man eine Gneuro-leitende Kapuze des Kanalisierers herstellt.\nGneuro-leitende Kapuze des Kanalisierers\nWird beim Aufheben gebunden\nKopf Leder\n118 Rüstung\n+11 Ausdauer\n+12 Intelligenz\n+11 Willenskraft\nHaltbarkeit 70 / 70\nBenötigt Stufe 40\nBenötigt Lederverarbeitung (225)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\nBenutzen: Gewährt 'Gneuromantische Meditation', wodurch 20 Sek. lang 100% Eurer Manaregeneration während des Zauberwirkens erhalten bleibt und der verursachte Schaden und die hervorgerufene Heilung Eurer Zauber um bis zu 50 erhöht werden. (10 Min Abklingzeit)\nBenötigt Isolierendes Gniodin , Geschmeidiger dicker Balg (5), Schwach leuchtendes Leder (5), Hyperleitender Arkanfaden" }
entries[215424] = { ["name"] = "Muster: Strahlungsresistente Schuppenkapuze", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (225)\nBenutzen: Lehrt Euch, wie man eine strahlungsresistente Schuppenkapuze herstellt.\nStrahlungsresistente Schuppenkapuze\nWird beim Aufheben gebunden\nKopf Kette\n342 Rüstung\n+10 Ausdauer\n+10 Intelligenz\nHaltbarkeit 85 / 85\nBenötigt Stufe 40\nBenötigt Lederverarbeitung (225)\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: +32 Angriffskraft.\nBenutzen: Aktiviert die Protokolle zur Strahlungsabschwächung in diesem Helm, die sofort alle aktiven Gifteffekte von Euch entfernen und Euch 3 Sek. lang immun gegen jeglichen Naturschaden machen. (10 Min Abklingzeit)\nBenötigt Echtsilberplatten mit geringer Grundstrahlung , Geschmeidiger dicker Balg (5), Schwach leuchtendes Leder (5), Isolierendes Gniodin" }
entries[215425] = { ["name"] = "Echo des Sumpfes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nBenutzen: Ehrt die Archivare." }
