entries[215429] = { ["name"] = "Bauplan: Polierte Echtsilberzahnräder", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (200)\nBenutzen: Lehrt Euch, wie man polierte Echtsilberzahnräder herstellt.\nPolierte Echtsilberzahnräder\nBenötigt Echtsilberbarren , Haufen aus stumpfen Zahnrädern (5)" }
entries[215430] = { ["name"] = "Ablagerung von Gnomeregan" }
entries[215431] = { ["name"] = "Bauplan: Hoch wirksame Strahlungsbombe", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (225)\nBenutzen: Lehrt Euch, wie man eine hoch wirksame Strahlungsbombe herstellt.\nHoch wirksame Strahlungsbombe\nBenötigt Stufe 35\nBenötigt Ingenieurskunst (200)\nBenutzen: Verursacht im Explosionsradius 150 bis 250 Feuerschaden und zusätzlich 10 Sek. lang alle 2 Sek. 25 Naturschaden. Verringert außerdem die Bewegungsgeschwindigkeit von betroffenen Zielen bis Abbruch lang um 25%. (1 Min Abklingzeit)\nBenötigt Robustes Sprengpulver , Ablagerung von Gnomeregan , Mithrilbarren (2)" }
entries[215432] = { ["name"] = "Bauplan: EZ-Thro-Strahlungsbombe", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (225)\nBenutzen: Lehrt Euch, wie man eine EZ-Thro-Strahlungsbombe herstellt.\nEZ-Thro-Strahlungsbombe\nBenötigt Stufe 40\nBenutzen: Verursacht im Explosionsradius 112 bis 188 Feuerschaden und zusätzlich 10 Sek. lang alle 2 Sek. 10 Naturschaden. Verringert außerdem die Bewegungsgeschwindigkeit von betroffenen Zielen 10 Sek. lang um 25%. (1 Min Abklingzeit)\n\"Eine abgeschwächte, aber nicht weniger tödliche Version ihres komplexeren Gegenstücks, für diejenigen, denen zwar die Kompetenz fehlt, die aber dafür Zuversicht im Überfluss haben.\"\nBenötigt Robustes Sprengpulver (2), Ablagerung von Gnomeregan , Mithrilbarren (2)" }
entries[215433] = { ["name"] = "Rezept: Isolierendes Gniodin", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchimie (200)\nBenutzen: Lehrt Euch, wie man eine Phiole isolierendes Gniodin herstellt.\nIsolierendes Gniodin\nBenötigt Verbleite Phiole , Kiste mit besudelter Gniodin-Lösung (5)" }
entries[215434] = { ["name"] = "UNBENUTZT", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchimie (200)\nBenutzen: Lehrt Euch, wie man eine Phiole isolierendes Gniodin herstellt.\nIsolierendes Gniodin\nBenötigt Verbleite Phiole , Kiste mit besudelter Gniodin-Lösung (5)" }
entries[215435] = { ["name"] = "Buchband der Segnung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Buchband\nBenötigt Stufe 40\nAnlegen: Verringert die Manakosten Eurer Siegelzauber um 10." }
entries[215436] = { ["name"] = "Totem der kräftigenden Flamme", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nBenötigt Stufe 40\nAnlegen: Verringert die Manakosten Eures Zaubers 'Flammenschock' um 10." }
entries[215437] = { ["name"] = "Troggwandler 3000", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 40\nBenutzen: Verwandelt den Zaubernden in einen Trogg. (30 Min Abklingzeit)\n\"Wird gewöhnlich zur Aufklärung verwendet.\"" }
entries[215441] = { ["name"] = "Kaputter Hammer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Auf diesem verzierten Kriegshammer sind die Insignien der Silbernen Hand eingestanzt.\"" }
entries[215443] = { ["name"] = "Zerschmettertes Kugelfragment", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Die Überreste der zerschmetterten Kugel geben ein leichtes Leuchten und etwas Wärme ab.\"" }
entries[215449] = { ["name"] = "Weltschrumpfer", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 40\nBenutzen: Verkleinert die gesamte Welt 5 Min. lang oder bis Ihr angreift. (1 Stunde Abklingzeit)\n\"Scheint auf Grundlage eines zerlegten Weltvergrößerers gebaut worden zu sein?\"" }
entries[215450] = { ["name"] = "Wappenrockprojekt (Aidan)", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWappenrock\nBenötigt Der Bund von Arathor\n- Ehrfürchtig" }
