entries[215452] = { ["name"] = "Mittelgroße Schließkassette", ["text"] = "Wird beim Aufheben gebunden\nVerschlossen\nBenötigt Schlossknacken (35)" }
entries[215453] = { ["name"] = "Kleine Schließkassette", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nVerschlossen\nBenötigt Schlossknacken (45)" }
entries[215454] = { ["name"] = "Winzige Schließkassette", ["text"] = "Wird beim Aufheben gebunden\nVerschlossen\nBenötigt Schlossknacken (55)" }
entries[215456] = { ["name"] = "Angesengte Nachricht", ["text"] = "\"Wer nicht hören will...\"" }
entries[215458] = { ["name"] = "Beigefügte Nachricht", ["text"] = "Klassen: Schurke\n\"Ernsthaft, versucht JA NICHT, die letzte Schachtel zu öffnen. Ihr habt bereits, was Ihr wolltet.\"" }
